      if (url) {
        try {
          await update(ref(db, `stores/${currentStoreId}`), { image: url });
          // تحديث الصورة في التخزين المحلي أيضاً إذا لزم الأمر
          const localStores = JSON.parse(localStorage.getItem('kimo_local_stores') || '[]');
          const updatedLocal = localStores.map((s: any) => s.id === currentStoreId ? { ...s, image: url } : s);
          localStorage.setItem('kimo_local_stores', JSON.stringify(updatedLocal));
