                  <input type="number" placeholder="السعر" value={newProduct.price || ''} onChange={e => setNewProduct({...newProduct, price: Number(e.target.value)})} className="w-full p-4 bg-primary-50 rounded-3xl font-bold outline-none" />
                  <button onClick={saveProduct} disabled={isSaving || isUploading} className="w-full bg-brand-600 text-white py-4 rounded-3xl font-black shadow-xl disabled:opacity-50">
