import React, { useState, useRef } from 'react';
import { Category, UserRole } from '../types';
import { auth, db } from '../services/firebase';
import { createUserWithEmailAndPassword, signInWithEmailAndPassword } from 'firebase/auth';
import { ref, set } from 'firebase/database';
import { ShoppingBag, Store, Bike, MapPin, ArrowRight, Loader2, Phone, Lock, User, Mail, ChevronLeft, AlertCircle, Upload, Camera, X, Navigation } from 'lucide-react';
import { BIR_EL_ATER_CENTER } from '../utils/helpers';

interface AuthScreenProps {
  onLogin: (role: UserRole, name?: string) => void;
}

const uploadImage = async (file: File): Promise<string | null> => {
  const formData = new FormData();
  formData.append("file", file);
  formData.append("upload_preset", "makemm");
  const cloudName = 'dkqxgwjnr';
  try {
    const res = await fetch(`https://api.cloudinary.com/v1_1/${cloudName}/image/upload`, {
      method: "POST",
      body: formData,
    });
    const data = await res.json();
    return data.secure_url || null;
  } catch (error) {
    console.error("Cloudinary error:", error);
    return null;
  }
};

export const AuthScreen: React.FC<AuthScreenProps> = ({ onLogin }) => {
  const [selectedRole, setSelectedRole] = useState<UserRole | null>(null);
  const [authMode, setAuthMode] = useState<'LOGIN' | 'REGISTER'>('LOGIN');
  const [isLoading, setIsLoading] = useState(false);
  const [isUploading, setIsUploading] = useState(false);
  const [isLocating, setIsLocating] = useState(false);
  const [formData, setFormData] = useState({ 
    name: '', 
    email: '', 
    phone: '', 
    password: '', 
    storeImage: '',
    coords: null as {lat: number, lng: number} | null
  });
  const [error, setError] = useState('');

  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleRoleSelect = (role: UserRole) => {
    setSelectedRole(role);
    setAuthMode('LOGIN');
    setError('');
  };

  const handleBack = () => {
    setSelectedRole(null);
    setFormData({ name: '', email: '', phone: '', password: '', storeImage: '', coords: null });
    setError('');
  };

  const handleGetLocation = () => {
    setIsLocating(true);
    if ("geolocation" in navigator) {
      navigator.geolocation.getCurrentPosition(
        (position) => {
          setFormData(prev => ({ 
            ...prev, 
            coords: { 
              lat: position.coords.latitude, 
              lng: position.coords.longitude 
            } 
          }));
          setIsLocating(false);
          alert("تم تحديد موقعك بنجاح!");
        },
        (error) => {
          console.error(error);
          setIsLocating(false);
          alert("فشل تحديد الموقع، يرجى تفعيل GPS");
        }
      );
    } else {
      setIsLocating(false);
      alert("متصفحك لا يدعم تحديد الموقع");
    }
  };

  const handleImageUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      setIsUploading(true);
      const url = await uploadImage(file);
      if (url) setFormData(prev => ({ ...prev, storeImage: url }));
      setIsUploading(false);
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');

    if (authMode === 'REGISTER' && selectedRole === UserRole.CUSTOMER && !formData.coords) {
      setError('يرجى تفعيل GPS وتحديد موقعك لتسهيل التوصيل');
      return;
    }

    if (!formData.email || !formData.password || (authMode === 'REGISTER' && (!formData.name || !formData.phone))) {
      setError('يرجى ملء جميع الحقول المطلوبة');
      return;
    }

    setIsLoading(true);

    try {
      if (authMode === 'REGISTER') {
        const userCredential = await createUserWithEmailAndPassword(auth, formData.email, formData.password);
        const user = userCredential.user;

        const dbPath = selectedRole === UserRole.CUSTOMER ? 'customers' : selectedRole === UserRole.STORE ? 'stores' : 'drivers';

        const profileData: any = {
            name: formData.name,
            email: formData.email,
            phone: formData.phone,
            role: selectedRole,
            createdAt: Date.now(),
            coordinates: formData.coords || BIR_EL_ATER_CENTER
        };

        if (selectedRole === UserRole.STORE) {
            profileData.category = Category.FOOD;
            profileData.image = formData.storeImage || `https://picsum.photos/400/300?random=${user.uid.slice(0,5)}`;
        }

        await set(ref(db, `${dbPath}/${user.uid}`), profileData);
        onLogin(selectedRole!, formData.name);
      } else {
        await signInWithEmailAndPassword(auth, formData.email, formData.password);
        onLogin(selectedRole || UserRole.CUSTOMER);
      }
    } catch (err: any) {
      setError(err.message);
    } finally {
      setIsLoading(false);
    }
  };

  if (!selectedRole) {
    return (
      <div className="min-h-screen bg-primary-900 flex flex-col items-center justify-center p-4 relative overflow-hidden">
        <div className="absolute top-0 left-0 w-full h-full overflow-hidden pointer-events-none">
           <div className="absolute -top-[10%] -left-[10%] w-96 h-96 bg-brand-500/20 rounded-full blur-[100px] animate-pulse-slow"></div>
        </div>
        <div className="z-10 text-center mb-12 animate-fade-in-up">
          <div className="bg-gradient-to-br from-brand-500 to-brand-700 w-24 h-24 rounded-3xl flex items-center justify-center mx-auto mb-6 shadow-2xl rotate-6">
            <MapPin className="text-white w-12 h-12" />
          </div>
          <h1 className="text-6xl font-black text-white mb-2 font-cairo">كيمو</h1>
          <p className="text-primary-300">اختر فئتك للمتابعة في بئر العاتر</p>
        </div>
        <div className="grid grid-cols-1 md:grid-cols-3 gap-6 w-full max-w-4xl px-4 z-10">
          <RoleCard icon={<ShoppingBag/>} title="أنا زبون" desc="اطلب من أفضل المتاجر" theme="blue" onClick={() => handleRoleSelect(UserRole.CUSTOMER)} />
          <RoleCard icon={<Store/>} title="أنا متجر" desc="ابدأ بيع منتجاتك" theme="emerald" onClick={() => handleRoleSelect(UserRole.STORE)} />
          <RoleCard icon={<Bike/>} title="أنا موصل" desc="وصل الطلبات واربح" theme="orange" onClick={() => handleRoleSelect(UserRole.DRIVER)} />
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-primary-50 flex items-center justify-center p-4 relative overflow-hidden">
      <div className={`absolute top-0 left-0 w-full h-[50vh] bg-primary-900 rounded-b-[4rem] shadow-2xl`}></div>
      <div className="glass-dark w-full max-w-md rounded-4xl shadow-2xl overflow-hidden flex flex-col animate-scale-up z-10 border border-white/10 mt-10">
        <div className="p-8 pb-4">
          <button onClick={handleBack} className="flex items-center text-primary-300 hover:text-white transition-colors mb-4 text-xs font-bold"><ChevronLeft className="w-4 h-4 ml-1" /> رجوع</button>
          <h2 className="text-3xl font-black text-white">{authMode === 'LOGIN' ? 'تسجيل الدخول' : 'حساب جديد'}</h2>
          <p className="text-primary-400 text-sm">أهلاً بك في فئة {selectedRole === UserRole.STORE ? 'المتاجر' : selectedRole === UserRole.DRIVER ? 'الموصلين' : 'الزبائن'}</p>
        </div>

        <form onSubmit={handleSubmit} className="p-8 pt-2 space-y-4">
          {error && <div className="bg-danger/10 text-danger p-3 rounded-2xl text-xs font-bold border border-danger/20">{error}</div>}

          {authMode === 'REGISTER' && (
            <>
              {selectedRole === UserRole.STORE && (
                <div className="flex flex-col items-center mb-6">
                  <div 
                    onClick={() => fileInputRef.current?.click()}
                    className="w-24 h-24 rounded-3xl bg-white/5 border-2 border-dashed border-white/20 flex flex-col items-center justify-center cursor-pointer hover:border-brand-500 transition-all overflow-hidden relative"
                  >
                    {formData.storeImage ? (
                      <img src={formData.storeImage} className="w-full h-full object-cover" />
                    ) : (
                      <div className="text-center">
                        {isUploading ? <Loader2 className="w-6 h-6 animate-spin text-brand-500" /> : <Camera className="w-8 h-8 text-primary-400" />}
                      </div>
                    )}
                    <input type="file" ref={fileInputRef} onChange={handleImageUpload} className="hidden" accept="image/*" />
                  </div>
                  <p className="text-[10px] text-primary-400 mt-2 font-bold">رفع شعار المتجر</p>
                </div>
              )}

              {selectedRole === UserRole.CUSTOMER && (
                <button 
                  type="button" 
                  onClick={handleGetLocation} 
                  className={`w-full p-4 rounded-2xl border-2 border-dashed transition-all flex items-center justify-center gap-2 font-bold ${formData.coords ? 'border-success text-success bg-success/5' : 'border-white/20 text-white bg-white/5'}`}
                >
                  {isLocating ? <Loader2 className="animate-spin w-5 h-5" /> : formData.coords ? <Navigation className="w-5 h-5" /> : <MapPin className="w-5 h-5" />}
                  {formData.coords ? 'تم تحديد موقعك' : 'تحديد موقعي الحالي عبر GPS'}
                </button>
              )}

              <input type="text" value={formData.name} onChange={e => setFormData({...formData, name: e.target.value})} className="w-full p-4 bg-white/5 border border-white/10 rounded-2xl text-white outline-none focus:border-brand-500 font-bold" placeholder="الاسم الكامل" />
              <input type="tel" value={formData.phone} onChange={e => setFormData({...formData, phone: e.target.value})} className="w-full p-4 bg-white/5 border border-white/10 rounded-2xl text-white outline-none focus:border-brand-500 font-bold text-right" placeholder="رقم الهاتف" dir="rtl" />
            </>
          )}

          <input type="email" value={formData.email} onChange={e => setFormData({...formData, email: e.target.value})} className="w-full p-4 bg-white/5 border border-white/10 rounded-2xl text-white outline-none focus:border-brand-500 font-bold" placeholder="البريد الإلكتروني" />
          <input type="password" value={formData.password} onChange={e => setFormData({...formData, password: e.target.value})} className="w-full p-4 bg-white/5 border border-white/10 rounded-2xl text-white outline-none focus:border-brand-500 font-bold" placeholder="كلمة المرور" />

          <button type="submit" disabled={isLoading || isUploading || isLocating} className="w-full bg-brand-600 text-white py-4 rounded-2xl font-bold text-lg hover:bg-brand-700 transition-all shadow-xl flex items-center justify-center gap-2">
            {isLoading ? <Loader2 className="animate-spin" /> : (authMode === 'LOGIN' ? 'دخول' : 'إنشاء حساب')}
          </button>

          <button type="button" onClick={() => setAuthMode(authMode === 'LOGIN' ? 'REGISTER' : 'LOGIN')} className="w-full text-center text-primary-400 text-sm font-bold hover:text-white transition-colors">
            {authMode === 'LOGIN' ? 'ليس لديك حساب؟ سجل الآن' : 'لديك حساب؟ سجل دخولك'}
          </button>
        </form>
      </div>
    </div>
  );
};

const RoleCard = ({ icon, title, desc, onClick }: any) => (
  <button onClick={onClick} className="bg-white/10 glass-dark border border-white/10 p-6 rounded-4xl text-right hover:-translate-y-2 transition-all group w-full">
    <div className="flex items-center gap-4">
      <div className="w-16 h-16 bg-white/10 rounded-2xl flex items-center justify-center text-brand-500 group-hover:bg-brand-600 group-hover:text-white transition-all">
