const DEFAULT_LOCATION = { lat: 34.7520, lng: 8.0550 };

const uploadImage = async (file: File): Promise<string | null> => {
  const formData = new FormData();
  formData.append("file", file);
  formData.append("upload_preset", "makemm");
  const cloudName = 'dkqxgwjnr';
  try {
    const res = await fetch(`https://api.cloudinary.com/v1_1/${cloudName}/image/upload`, {
      method: "POST",
      body: formData,
    });
    const data = await res.json();
    return data.secure_url || null;
  } catch (error) {
    console.error("Cloudinary error:", error);
    return null;
  }
};

export const CustomerScreen: React.FC<CustomerScreenProps> = ({ onLogout, userName }) => {
  const [activeTab, setActiveTab] = useState<'HOME' | 'PROFILE'>('HOME');
  const [selectedCategory, setSelectedCategory] = useState<Category | 'ALL'>('ALL');
  const [activeStore, setActiveStore] = useState<StoreProfile | null>(null);
  const [activeStoreProducts, setActiveStoreProducts] = useState<Product[]>([]);
  const [loadingProducts, setLoadingProducts] = useState(false);
  const [cart, setCart] = useState<{product: Product; quantity: number}[]>([]);
  const [showCart, setShowCart] = useState(false);
  const [isOrdering, setIsOrdering] = useState(false);

  const [userProfile, setUserProfile] = useState<any>(null);
  const [userCoords, setUserCoords] = useState<{lat: number, lng: number}>(DEFAULT_LOCATION);
  const [stores, setStores] = useState<StoreProfile[]>([]);
  const [loadingStores, setLoadingStores] = useState(true);
  const [searchQuery, setSearchQuery] = useState('');
  const [scrolled, setScrolled] = useState(false);

  // Profile Edit State
  const [isUpdatingProfile, setIsUpdatingProfile] = useState(false);
  const [newName, setNewName] = useState(userName);
  const profileImageInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const handleScroll = () => setScrolled(window.scrollY > 20);
    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  useEffect(() => {
    const user = auth.currentUser;
    if (user) {
      const userRef = ref(db, `customers/${user.uid}`);
      onValue(userRef, (snapshot) => {
        if (snapshot.exists()) {
          const data = snapshot.val();
          setUserProfile(data);
          setNewName(data.name || userName);
          if (data.coordinates) setUserCoords(data.coordinates);
        }
      });
    }

    const storesRef = ref(db, 'stores');
    const unsubscribe = onValue(storesRef, (snapshot) => {
        const data = snapshot.val();
        let loadedStores: StoreProfile[] = [];
        if (data) {
            loadedStores = Object.keys(data).map(key => ({
                id: key, 
                ...data[key],
                rating: data[key].rating || 4.5,
                reviewCount: data[key].reviewCount || 0
            }));
        }
        setStores(loadedStores);
        setLoadingStores(false);
    });
    return () => unsubscribe();
  }, []);

  const handleUpdateProfile = async () => {
    const user = auth.currentUser;
    if (!user) return;
    setIsUpdatingProfile(true);
    try {
      await update(ref(db, `customers/${user.uid}`), { name: newName });
      alert("تم تحديث الاسم بنجاح");
    } catch (e) {
      alert("خطأ في التحديث");
    } finally {
      setIsUpdatingProfile(false);
    }
  };

  const handleUpdateAvatar = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    const user = auth.currentUser;
    if (file && user) {
      setIsUpdatingProfile(true);
      const url = await uploadImage(file);
      if (url) {
        await update(ref(db, `customers/${user.uid}`), { avatar: url });
      }
      setIsUpdatingProfile(false);
    }
  };

  const storesWithDistance = useMemo(() => {
    return stores.map(store => ({
      ...store,
      distance: calculateDistance(userCoords, store.coordinates)
    })).sort((a, b) => a.distance - b.distance);
  }, [stores, userCoords]);

  const filteredStores = useMemo(() => {
    let result = storesWithDistance;
    if (selectedCategory !== 'ALL') result = result.filter(s => s.category === selectedCategory);
    if (searchQuery) result = result.filter(s => s.name.toLowerCase().includes(searchQuery.toLowerCase()));
    return result;
  }, [selectedCategory, searchQuery, storesWithDistance]);

  const addToCart = (product: Product) => {
    setCart(prev => {
      const existing = prev.find(item => item.product.id === product.id);
      if (existing) return prev.map(item => item.product.id === product.id ? {...item, quantity: item.quantity + 1} : item);
      return [...prev, { product, quantity: 1 }];
    });
  };

  const removeFromCart = (productId: string) => {
    setCart(prev => prev.map(item => item.product.id === productId ? {...item, quantity: Math.max(0, item.quantity - 1)} : item).filter(item => item.quantity > 0));
  };

  const cartTotal = cart.reduce((sum, item) => sum + (item.product.price * item.quantity), 0);
  const deliveryFee = 200; 
  const grandTotal = cartTotal + deliveryFee;

  return (
    <div className="bg-primary-50 min-h-screen pb-28 font-cairo">
      {/* Header */}
      <header className={`fixed top-0 left-0 right-0 z-40 transition-all duration-300 ${scrolled ? 'glass shadow-lg py-2' : 'bg-transparent py-4'}`}>
        <div className="container max-w-lg mx-auto px-4 flex items-center justify-between">
          <div className="flex items-center gap-3">
             <div className="w-10 h-10 bg-brand-600 rounded-2xl flex items-center justify-center shadow-lg"><span className="text-white font-black text-xl">K</span></div>
             <div>
                <h1 className="font-bold text-primary-800 text-sm">مرحباً، {userProfile?.name || userName}</h1>
                <p className="text-[10px] text-primary-500 flex items-center"><MapPin className="w-3 h-3 ml-1 text-brand-500" /> حي السلام، بئر العاتر</p>
             </div>
          </div>
          {activeStore && (
            <button onClick={() => setActiveStore(null)} className="glass px-3 py-1.5 rounded-2xl text-xs font-bold text-primary-700 border border-white/50">إغلاق المتجر</button>
          )}
        </div>
      </header>

      {activeTab === 'HOME' ? (
        <div className="container max-w-lg mx-auto pt-20 px-4">
          {!activeStore ? (
            <div className="space-y-6 animate-fade-in-up">
              <div className="relative">
                 <input type="text" placeholder="ابحث عن مطعم أو منتج..." value={searchQuery} onChange={(e) => setSearchQuery(e.target.value)} className="w-full bg-white border border-primary-100 rounded-3xl py-4 pr-12 shadow-sm font-bold focus:ring-2 focus:ring-brand-500 outline-none" />
                 <Search className="absolute right-4 top-4 w-6 h-6 text-primary-300" />
              </div>

              <div className="bg-white p-2 rounded-4xl shadow-sm border border-primary-100 overflow-hidden">
                  <div className="flex justify-between items-center px-4 py-2">
                     <h2 className="font-bold text-primary-800 text-sm">بالقرب منك</h2>
                     <span className="text-[10px] text-brand-600 font-bold bg-brand-50 px-2 py-1 rounded-lg">عرض الخريطة</span>
                  </div>
                  <div className="rounded-3xl overflow-hidden"><MapVisualizer userType="CUSTOMER" height="h-28" /></div>
              </div>

              <div>
                <h2 className="font-bold text-primary-800 mb-3 text-sm">الأقسام</h2>
                <div className="flex gap-3 overflow-x-auto pb-2 scrollbar-hide">
                  {['ALL', ...Object.values(Category)].map(cat => (
                    <button key={cat} onClick={() => setSelectedCategory(cat as Category | 'ALL')} className={`shrink-0 px-6 py-2 rounded-2xl text-[10px] font-bold transition-all ${selectedCategory === cat ? 'bg-primary-900 text-white shadow-lg' : 'bg-white text-primary-500 border border-primary-100'}`}>
                      {cat === 'ALL' ? 'الكل' : cat}
                    </button>
                  ))}
                </div>
              </div>

              <div className="space-y-4">
                  <h2 className="font-bold text-primary-800 text-sm">المتاجر المتاحة</h2>
                  {loadingStores ? <div className="flex justify-center py-10"><Loader2 className="animate-spin text-brand-500" /></div> : (
                      <div className="grid grid-cols-1 gap-6">
                          {filteredStores.map(store => (
                          <div key={store.id} onClick={() => setActiveStore(store)} className="bg-white rounded-[2.5rem] overflow-hidden shadow-md hover:shadow-xl transition-all cursor-pointer border border-primary-50">
                              <div className="h-48 relative">
                                  <img src={store.image} alt={store.name} className="w-full h-full object-cover" />
                                  <div className="absolute inset-0 bg-gradient-to-t from-black/80 via-transparent to-transparent"></div>
                                  <div className="absolute top-4 left-4 glass bg-white/20 backdrop-blur-md px-3 py-1.5 rounded-2xl text-white text-[10px] font-bold flex items-center gap-1">
                                      <Star className="w-3 h-3 text-warning fill-warning" /> {store.rating}
                                  </div>
                                  <div className="absolute bottom-4 right-4 text-white text-right">
                                      <h3 className="font-black text-2xl mb-1">{store.name}</h3>
                                      <p className="text-[10px] opacity-80 font-medium flex items-center gap-1 justify-end">
                                          بئر العاتر <MapPin className="w-3 h-3" />
                                      </p>
                                  </div>
                              </div>
                              <div className="p-4 flex justify-between items-center bg-white">
                                  <div className="flex gap-2">
                                      <span className="bg-primary-50 px-3 py-1.5 rounded-xl text-[10px] font-bold text-primary-500">{store.category}</span>
                                      <span className="bg-brand-50 px-3 py-1.5 rounded-xl text-[10px] font-bold text-brand-600 flex items-center gap-1"><Clock className="w-3 h-3" /> 25 دقيقة</span>
                                  </div>
                                  <span className="text-xs font-black text-primary-800">{store.distance} كم</span>
                              </div>
                          </div>
                          ))}
                      </div>
                  )}
              </div>
            </div>
          ) : (
            <div className="animate-fade-in-up">
              <div className="relative h-60 rounded-4xl overflow-hidden mb-6">
                  <img src={activeStore.image} className="w-full h-full object-cover" />
                  <div className="absolute inset-0 bg-gradient-to-t from-black/80 to-transparent"></div>
                  <div className="absolute bottom-6 right-6 text-white text-right">
                      <h2 className="text-3xl font-black">{activeStore.name}</h2>
                      <p className="text-sm opacity-80">{activeStore.category}</p>
                  </div>
              </div>
              <div className="space-y-4">
                  {loadingProducts ? <Loader2 className="animate-spin mx-auto" /> : activeStoreProducts.map(p => (
                      <div key={p.id} className="bg-white p-4 rounded-3xl shadow-sm border border-primary-50 flex gap-4">
                          <img src={p.image} className="w-20 h-20 rounded-2xl object-cover" />
                          <div className="flex-1 flex flex-col justify-between">
                              <h4 className="font-bold text-primary-800 text-sm">{p.name}</h4>
                              <div className="flex justify-between items-end">
                                  <span className="text-lg font-black text-brand-600">{formatCurrency(p.price)}</span>
                                  <div className="flex items-center gap-2">
                                     {cart.find(i => i.product.id === p.id) && (
                                       <button onClick={() => removeFromCart(p.id)} className="bg-primary-100 text-primary-600 p-2 rounded-xl"><Minus className="w-4 h-4" /></button>
                                     )}
                                     <button onClick={() => addToCart(p)} className="bg-primary-900 text-white p-2 rounded-xl"><Plus className="w-4 h-4" /></button>
                                  </div>
                              </div>
                          </div>
                      </div>
                  ))}
              </div>
            </div>
          )}
        </div>
      ) : (
        <div className="container max-w-lg mx-auto pt-24 px-6 animate-fade-in-up">
           <div className="bg-white rounded-[3rem] p-8 shadow-xl border border-primary-100 text-center relative overflow-hidden">
              <div className="absolute top-0 right-0 w-32 h-32 bg-brand-500/5 rounded-full blur-3xl"></div>

              <div className="relative inline-block mb-6">
                 <div className="w-32 h-32 rounded-full border-4 border-brand-100 overflow-hidden shadow-inner">
                    <img src={userProfile?.avatar || `https://api.dicebear.com/7.x/avataaars/svg?seed=${userName}`} className="w-full h-full object-cover" />
                 </div>
                 <button onClick={() => profileImageInputRef.current?.click()} className="absolute bottom-0 right-0 bg-brand-600 text-white p-2.5 rounded-full shadow-lg border-2 border-white hover:scale-110 transition-all">
                    <Camera className="w-5 h-5" />
                 </button>
                 <input type="file" ref={profileImageInputRef} onChange={handleUpdateAvatar} className="hidden" accept="image/*" />
              </div>

              <div className="space-y-6 text-right">
                 <div>
                    <label className="text-xs font-black text-primary-400 block mb-2 px-2">الاسم الكامل</label>
                    <input 
                      type="text" 
                      value={newName} 
                      onChange={(e) => setNewName(e.target.value)}
                      className="w-full bg-primary-50 p-4 rounded-3xl font-black text-primary-800 outline-none focus:ring-2 focus:ring-brand-500"
                    />
                 </div>
                 <button 
                  onClick={handleUpdateProfile} 
                  disabled={isUpdatingProfile}
                  className="w-full bg-brand-600 text-white py-4 rounded-3xl font-black shadow-lg hover:bg-brand-700 transition-all flex items-center justify-center gap-2"
                 >
                    {isUpdatingProfile ? <Loader2 className="animate-spin" /> : <><CheckCircle className="w-5 h-5" /> حفظ التغييرات</>}
                 </button>

                 <div className="pt-4 border-t border-primary-50">
                    <button onClick={onLogout} className="w-full bg-danger/10 text-danger py-4 rounded-3xl font-black flex items-center justify-center gap-2 hover:bg-danger hover:text-white transition-all">
                       <LogOut className="w-5 h-5" /> تسجيل الخروج
                    </button>
                 </div>
              </div>
           </div>
        </div>
      )}

      {/* Bottom Navigation */}
      <nav className="fixed bottom-6 left-6 right-6 glass-dark rounded-[2.5rem] p-2 flex justify-around items-center shadow-2xl z-50 border border-white/10">
         <button onClick={() => setActiveTab('HOME')} className={`flex flex-col items-center p-3 rounded-3xl transition-all ${activeTab === 'HOME' ? 'bg-brand-600 text-white scale-110 shadow-lg shadow-brand-500/30' : 'text-primary-400'}`}>
            <Home className="w-6 h-6" />
         </button>
         <button onClick={() => setActiveTab('PROFILE')} className={`flex flex-col items-center p-3 rounded-3xl transition-all ${activeTab === 'PROFILE' ? 'bg-brand-600 text-white scale-110 shadow-lg shadow-brand-500/30' : 'text-primary-400'}`}>
            <User className="w-6 h-6" />
         </button>
      </nav>

      {/* Cart Logic Remains Same */}
      {cart.length > 0 && !showCart && activeTab === 'HOME' && (
        <button onClick={() => setShowCart(true)} className="fixed bottom-24 left-6 right-6 bg-primary-900 text-white py-4 rounded-3xl font-black text-lg shadow-2xl flex items-center justify-between px-8 z-50 animate-bounce-small">
            <div className="flex items-center gap-3"><ShoppingCart className="w-6 h-6" /> <span className="bg-brand-500 px-2 py-0.5 rounded-lg text-xs">{cart.length}</span></div>
            <span>عرض السلة</span>
            <span>{formatCurrency(grandTotal)}</span>
        </button>
      )}
    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { MapVisualizer } from '../components/MapVisualizer';
import { RatingModal } from '../components/RatingModal';
import { MapPin, Navigation, CheckCircle, Clock, ExternalLink, Loader2, Package, Bike as BikeIcon, ArrowRight, User, LogOut, Camera, Settings } from 'lucide-react';
import { db, auth } from '../services/firebase';
import { ref, onValue, update, get } from 'firebase/database';
import { Order, OrderStatus } from '../types';
import { calculateDistance, USER_LOCATION, formatCurrency } from '../utils/helpers';

interface DriverScreenProps {
  onLogout: () => void;
  userName: string;
}

const uploadImage = async (file: File): Promise<string | null> => {
  const formData = new FormData();
  formData.append("file", file);
  formData.append("upload_preset", "makemm");
  const cloudName = 'dkqxgwjnr';
  try {
    const res = await fetch(`https://api.cloudinary.com/v1_1/${cloudName}/image/upload`, {
      method: "POST",
      body: formData,
    });
    const data = await res.json();
    return data.secure_url || null;
  } catch (error) {
    return null;
  }
};

export const DriverScreen: React.FC<DriverScreenProps> = ({ onLogout, userName }) => {
  const [activeTab, setActiveTab] = useState<'AVAILABLE' | 'ACTIVE' | 'PROFILE'>('AVAILABLE');
  const [showRating, setShowRating] = useState(false);
  const [availableOrders, setAvailableOrders] = useState<Order[]>([]);
  const [activeOrder, setActiveOrder] = useState<Order | null>(null);
  const [driverProfile, setDriverProfile] = useState<any>(null);
  const [loading, setLoading] = useState(true);

  // Edit State
  const [isUpdating, setIsUpdating] = useState(false);
  const [newName, setNewName] = useState(userName);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const currentDriverId = auth.currentUser?.uid;

  useEffect(() => {
    if (!currentDriverId) return;

    // Profile listener
    const driverRef = ref(db, `drivers/${currentDriverId}`);
    onValue(driverRef, (snap) => {
      if (snap.exists()) {
        const data = snap.val();
        setDriverProfile(data);
        setNewName(data.name || userName);
      }
    });

    const ordersRef = ref(db, 'orders');
    const unsubscribe = onValue(ordersRef, (snapshot) => {
        const data = snapshot.val();
        const available: Order[] = [];
        let myActive: Order | null = null;

        if (data) {
            Object.keys(data).forEach(key => {
                const order = { ...data[key], id: key } as Order;
                if (order.driverId === currentDriverId && order.status === OrderStatus.ACCEPTED_BY_DRIVER) {
                    myActive = order;
                }
                if (order.status === OrderStatus.ACCEPTED_BY_STORE && !order.driverId) {
                    available.push(order);
                }
            });
        }
        setAvailableOrders(available);
        setActiveOrder(myActive);
        setLoading(false);
    });
    return () => unsubscribe();
  }, [currentDriverId]);

  const handleUpdateName = async () => {
    if (!currentDriverId) return;
    setIsUpdating(true);
    await update(ref(db, `drivers/${currentDriverId}`), { name: newName });
    setIsUpdating(false);
    alert("تم التحديث");
  };

  const handleUpdateAvatar = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file && currentDriverId) {
      setIsUpdating(true);
      const url = await uploadImage(file);
      if (url) await update(ref(db, `drivers/${currentDriverId}`), { avatar: url });
      setIsUpdating(false);
    }
  };

  const handleAcceptOrder = async (orderId: string) => {
      try {
          if (!currentDriverId) return;
          await update(ref(db, `orders/${orderId}`), {
              status: OrderStatus.ACCEPTED_BY_DRIVER,
              driverId: currentDriverId,
              driverName: userName
          });
          setActiveTab('ACTIVE');
      } catch (error) {
          alert("فشل قبول الطلب");
      }
  };

  const handleCompleteOrder = async () => {
    if (!activeOrder) return;
    try {
        await update(ref(db, `orders/${activeOrder.id}`), {
            status: OrderStatus.DELIVERED
        });
        setShowRating(true);
    } catch (error) {
        console.error(error);
    }
  };

  const startFullNavigation = () => {
    if (!activeOrder || !activeOrder.coordinates || !activeOrder.storeCoordinates) return;
    const storeLat = activeOrder.storeCoordinates.lat;
    const storeLng = activeOrder.storeCoordinates.lng;
    const destLat = activeOrder.coordinates.lat;
    const destLng = activeOrder.coordinates.lng;
    const url = `https://www.google.com/maps/dir/?api=1&origin=current+location&destination=${destLat},${destLng}&waypoints=${storeLat},${storeLng}&travelmode=driving`;
    window.open(url, '_blank');
  };

  return (
    <div className="min-h-screen bg-primary-100 pb-28 font-cairo">
       {showRating && <RatingModal type="CUSTOMER" targetName={activeOrder?.customerName || "الزبون"} onClose={() => { setShowRating(false); setActiveTab('AVAILABLE'); }} />}

       <header className="bg-primary-900 text-white p-6 shadow-lg sticky top-0 z-10 rounded-b-[3rem]">
        <div className="flex justify-between items-center">
          <div className="flex items-center gap-3">
             <div className="w-12 h-12 rounded-2xl overflow-hidden border-2 border-brand-500 shadow-lg">
                <img src={driverProfile?.avatar || `https://api.dicebear.com/7.x/bottts/svg?seed=${userName}`} className="w-full h-full object-cover" />
             </div>
             <div>
                <h1 className="font-black text-lg">{driverProfile?.name || userName}</h1>
                <p className="text-[10px] text-brand-400 font-bold">سائق كيمو المعتمد</p>
             </div>
          </div>
          <button onClick={() => setActiveTab('PROFILE')} className="p-2 bg-white/10 rounded-xl"><Settings className="w-5 h-5" /></button>
        </div>
      </header>

      <div className="p-4 max-w-lg mx-auto">
        {activeTab !== 'PROFILE' && (
          <div className="flex bg-white p-1 rounded-3xl shadow-md mb-6 border border-primary-100">
            <button onClick={() => setActiveTab('AVAILABLE')} className={`flex-1 py-3 text-xs font-black rounded-2xl transition-all ${activeTab === 'AVAILABLE' ? 'bg-primary-900 text-white shadow-lg' : 'text-primary-500'}`}>الطلبات المتاحة ({availableOrders.length})</button>
            <button onClick={() => setActiveTab('ACTIVE')} disabled={!activeOrder} className={`flex-1 py-3 text-xs font-black rounded-2xl transition-all ${activeTab === 'ACTIVE' ? 'bg-brand-600 text-white shadow-lg' : 'text-primary-500'} disabled:opacity-50`}>الطلب النشط</button>
          </div>
        )}

        {loading ? (
             <div className="flex justify-center mt-10"><Loader2 className="w-8 h-8 animate-spin text-brand-500" /></div>
        ) : activeTab === 'AVAILABLE' ? (
          <div className="space-y-4">
            {availableOrders.length === 0 ? (
                <div className="bg-white rounded-4xl p-10 text-center text-primary-400 border border-dashed border-primary-200">
                    <BikeIcon className="w-16 h-16 mx-auto mb-4 opacity-20" />
                    <p className="font-bold">لا توجد طلبات في بئر العاتر حالياً</p>
                </div>
            ) : (
                availableOrders.map(order => (
                <div key={order.id} className="bg-white p-5 rounded-3xl shadow-md border-r-8 border-success animate-fade-in-up">
                    <div className="flex justify-between items-start mb-3">
                        <h3 className="font-black text-xl text-primary-900">{order.storeName}</h3>
                        <span className="bg-success text-white text-[10px] px-3 py-1 rounded-full font-black">{formatCurrency(order.deliveryFee)} ربح</span>
                    </div>
                    <p className="text-xs text-primary-500 font-bold mb-4 flex items-center gap-1"><MapPin className="w-3 h-3 text-brand-500" /> الوجهة: {order.address}</p>
                    <div className="flex justify-between items-center pt-3 border-t border-primary-50">
                        <span className="text-xs font-bold text-primary-400">مسافة قريبة</span>
                        <button onClick={() => handleAcceptOrder(order.id)} className="bg-primary-900 text-white px-6 py-2 rounded-2xl text-xs font-black shadow-lg">قبول وتوصيل</button>
                    </div>
                </div>
                ))
            )}
          </div>
        ) : activeTab === 'ACTIVE' ? (
          <div className="space-y-4 animate-fade-in-up">
            {activeOrder && (
                <>
                    <div className="bg-white p-4 rounded-4xl shadow-md border border-primary-100">
                        <div className="h-40 rounded-3xl overflow-hidden mb-4"><MapVisualizer userType="DRIVER" height="h-full" /></div>

                        <div className="space-y-3">
                           <div className="p-4 bg-primary-50 rounded-2xl border border-primary-100">
                              <p className="text-[10px] font-black text-brand-600 mb-1">1. استلم من</p>
                              <p className="font-black text-primary-900">{activeOrder.storeName}</p>
                           </div>
                           <div className="flex justify-center"><ArrowRight className="rotate-90 text-primary-200" /></div>
                           <div className="p-4 bg-success/5 rounded-2xl border border-success/20">
                              <p className="text-[10px] font-black text-success mb-1">2. سلم إلى</p>
                              <p className="font-black text-primary-900">{activeOrder.customerName} - {activeOrder.address}</p>
                           </div>
                        </div>

                        <button 
                          onClick={startFullNavigation}
                          className="w-full mt-6 bg-blue-600 text-white py-4 rounded-3xl font-black text-lg shadow-xl flex items-center justify-center gap-2"
                        >
                           <Navigation className="w-6 h-6" /> ابدأ الملاحة GPS
                        </button>
                    </div>

                    <button 
                        onClick={handleCompleteOrder}
                        className="w-full bg-success text-white py-4 rounded-3xl font-black text-xl shadow-xl hover:scale-105 transition-all"
                    >
                        تأكيد تسليم الطلب
                    </button>
                </>
            )}
          </div>
        ) : (
          <div className="animate-fade-in-up space-y-6">
             <div className="bg-white p-8 rounded-[3rem] shadow-xl border border-primary-100 text-center">
                <div className="relative inline-block mb-6">
                   <div className="w-32 h-32 rounded-3xl border-4 border-brand-100 overflow-hidden shadow-lg">
                      <img src={driverProfile?.avatar || `https://api.dicebear.com/7.x/bottts/svg?seed=${userName}`} className="w-full h-full object-cover" />
                   </div>
                   <button onClick={() => fileInputRef.current?.click()} className="absolute -bottom-2 -right-2 bg-brand-600 text-white p-3 rounded-2xl shadow-lg border-2 border-white">
                      <Camera className="w-5 h-5" />
                   </button>
                   <input type="file" ref={fileInputRef} onChange={handleUpdateAvatar} className="hidden" accept="image/*" />
                </div>

                <div className="space-y-6 text-right">
                   <div>
                      <label className="text-xs font-black text-primary-400 block mb-2 px-2">اسم الموصل الرسمي</label>
                      <input 
                        type="text" 
                        value={newName} 
                        onChange={(e) => setNewName(e.target.value)}
                        className="w-full bg-primary-50 p-4 rounded-3xl font-black text-primary-800 outline-none"
                      />
                   </div>
                   <button 
                    onClick={handleUpdateName} 
                    disabled={isUpdating}
                    className="w-full bg-primary-900 text-white py-4 rounded-3xl font-black shadow-lg"
                   >
                      {isUpdating ? <Loader2 className="animate-spin" /> : 'حفظ التعديلات'}
                   </button>
                   <button onClick={onLogout} className="w-full bg-danger/10 text-danger py-4 rounded-3xl font-black flex items-center justify-center gap-2">
                      <LogOut className="w-5 h-5" /> تسجيل الخروج
                   </button>
                </div>
             </div>
          </div>
        )}
      </div>

      {/* Bottom Navbar for Driver */}
      <nav className="fixed bottom-6 left-6 right-6 glass-dark rounded-[2.5rem] p-2 flex justify-around items-center shadow-2xl z-50">
         <button onClick={() => setActiveTab('AVAILABLE')} className={`p-3 rounded-2xl transition-all ${activeTab === 'AVAILABLE' ? 'bg-brand-600 text-white' : 'text-primary-400'}`}>
            <Package className="w-6 h-6" />
         </button>
         <button onClick={() => setActiveTab('ACTIVE')} disabled={!activeOrder} className={`p-3 rounded-2xl transition-all ${activeTab === 'ACTIVE' ? 'bg-brand-600 text-white' : 'text-primary-400'} disabled:opacity-20`}>
