         <button onClick={() => setActiveTab('PROFILE')} className={`p-3 rounded-2xl transition-all ${activeTab === 'PROFILE' ? 'bg-brand-600 text-white' : 'text-primary-400'}`}>
            <User className="w-6 h-6" />
         </button>
      </nav>
    </div>
  );
};

import React, { useState, useRef, useEffect } from 'react';
import { Category, Product, Order, OrderStatus, StoreProfile } from '../types';
import { generateProductDescription } from '../services/geminiService';
import { db, auth } from '../services/firebase';
import { ref, push, set, onValue, remove, update, get } from 'firebase/database';
import { 
  Sparkles, Package, Plus, Settings, MapPin, Store as StoreIcon, 
  ChevronRight, Upload, X, Loader2, Trash2, Edit, ArrowLeft, 
  ClipboardList, ShoppingBag, CheckCircle, Clock, Camera, Home, LogOut 
} from 'lucide-react';
import { BIR_EL_ATER_CENTER, formatCurrency } from '../utils/helpers';

interface StoreScreenProps {
  onLogout: () => void;
  userName: string;
}

const uploadImage = async (file: File): Promise<string | null> => {
  const formData = new FormData();
  formData.append("file", file);
  formData.append("upload_preset", "makemm");
  const cloudName = 'dkqxgwjnr';
  try {
    const res = await fetch(`https://api.cloudinary.com/v1_1/${cloudName}/image/upload`, {
      method: "POST",
      body: formData,
    });
    const data = await res.json();
    return data.secure_url || null;
  } catch (error) {
    console.error("Cloudinary error:", error);
    return null;
  }
};

export const StoreScreen: React.FC<StoreScreenProps> = ({ onLogout, userName }) => {
  const [view, setView] = useState<'PRODUCTS' | 'ORDERS' | 'SETTINGS'>('PRODUCTS');
  const [myProducts, setMyProducts] = useState<Product[]>([]);
  const [orders, setOrders] = useState<Order[]>([]);
  const [storeProfile, setStoreProfile] = useState<StoreProfile | null>(null);
  const [loading, setLoading] = useState(true);

  const [isAddingProduct, setIsAddingProduct] = useState(false);
  const [isGenerating, setIsGenerating] = useState(false);
  const [isUploading, setIsUploading] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const [isUpdatingProfile, setIsUpdatingProfile] = useState(false);

  // Profile Edit State
  const [newStoreName, setNewStoreName] = useState(userName);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const profileImageInputRef = useRef<HTMLInputElement>(null);

  const [newProduct, setNewProduct] = useState<Partial<Product>>({
    name: '', description: '', price: 0, category: Category.FOOD, image: ''
  });

  const currentStoreId = auth.currentUser?.uid;

  useEffect(() => {
    if (!currentStoreId) return;

    const storeRef = ref(db, `stores/${currentStoreId}`);
    const unsubscribeStore = onValue(storeRef, (snapshot) => {
      if (snapshot.exists()) {
        const data = snapshot.val();
        setStoreProfile(data);
        setNewStoreName(data.name || userName);
      }
    });

    const productsRef = ref(db, 'products');
    const unsubscribeProducts = onValue(productsRef, (snapshot) => {
      const data = snapshot.val();
      const list: Product[] = [];
      if (data) {
        Object.keys(data).forEach(key => {
          if (data[key].storeId === currentStoreId) {
            list.push({ ...data[key], id: key });
          }
        });
      }
      setMyProducts(list.reverse());
    });

    const ordersRef = ref(db, 'orders');
    const unsubscribeOrders = onValue(ordersRef, (snapshot) => {
      const data = snapshot.val();
      const list: Order[] = [];
      if (data) {
        Object.keys(data).forEach(key => {
          const order = { ...data[key], id: key };
          if (order.storeId === currentStoreId) {
            list.push(order);
          }
        });
      }
      setOrders(list.sort((a, b) => b.timestamp - a.timestamp));
      setLoading(false);
    });

    return () => {
      unsubscribeStore();
      unsubscribeProducts();
      unsubscribeOrders();
    };
  }, [currentStoreId]);

  const handleUpdateStoreProfile = async () => {
    if (!currentStoreId) return;
    setIsUpdatingProfile(true);
    await update(ref(db, `stores/${currentStoreId}`), { name: newStoreName });
