import React, { useState, useMemo, useEffect, useRef } from 'react';
import { Category, Product, StoreProfile, OrderStatus } from '../types';
import { calculateDistance, formatCurrency, BIR_EL_ATER_CENTER } from '../utils/helpers';
import { MapVisualizer } from '../components/MapVisualizer';
import { db, auth } from '../services/firebase';
import { ref, onValue, push, set, update } from 'firebase/database';
import { Search, Star, Plus, Minus, ShoppingCart, MapPin, X, CheckCircle, Clock, Loader2, Home, User, Camera, LogOut, Navigation } from 'lucide-react';

interface CustomerScreenProps {
  onLogout: () => void;
  userName: string;
}

const DEFAULT_LOCATION = { lat: 34.7495, lng: 8.0617 };

const uploadImage = async (file: File): Promise<string | null> => {
  const formData = new FormData();
  formData.append("file", file);
  formData.append("upload_preset", "makemm");
  const cloudName = 'dkqxgwjnr';
  try {
    const res = await fetch(`https://api.cloudinary.com/v1_1/${cloudName}/image/upload`, {
      method: "POST",
      body: formData,
    });
    const data = await res.json();
    return data.secure_url || null;
  } catch (error) {
    return null;
  }
};

export const CustomerScreen: React.FC<CustomerScreenProps> = ({ onLogout, userName }) => {
  const [activeTab, setActiveTab] = useState<'HOME' | 'PROFILE'>('HOME');
  const [selectedCategory, setSelectedCategory] = useState<Category | 'ALL'>('ALL');
  const [activeStore, setActiveStore] = useState<StoreProfile | null>(null);
  const [activeStoreProducts, setActiveStoreProducts] = useState<Product[]>([]);
  const [loadingProducts, setLoadingProducts] = useState(false);
  const [cart, setCart] = useState<{product: Product; quantity: number}[]>([]);
  const [showCart, setShowCart] = useState(false);
  const [isOrdering, setIsOrdering] = useState(false);

  const [userProfile, setUserProfile] = useState<any>(null);
  const [userCoords, setUserCoords] = useState<{lat: number, lng: number}>(DEFAULT_LOCATION);
  const [stores, setStores] = useState<StoreProfile[]>([]);
  const [loadingStores, setLoadingStores] = useState(true);
  const [searchQuery, setSearchQuery] = useState('');

  // Profile Edit
  const [isUpdatingProfile, setIsUpdatingProfile] = useState(false);
  const [newName, setNewName] = useState(userName);
  const profileImageInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const user = auth.currentUser;
    if (user) {
      const userRef = ref(db, `customers/${user.uid}`);
      onValue(userRef, (snapshot) => {
        if (snapshot.exists()) {
          const data = snapshot.val();
          setUserProfile(data);
          setNewName(data.name || userName);
          if (data.coordinates) setUserCoords(data.coordinates);
        }
      });
    }

    const storesRef = ref(db, 'stores');
    onValue(storesRef, (snapshot) => {
        const data = snapshot.val();
        let loadedStores: StoreProfile[] = [];
        if (data) {
            loadedStores = Object.keys(data).map(key => ({
                id: key, 
                ...data[key]
            }));
        }
        setStores(loadedStores);
        setLoadingStores(false);
    });
  }, []);

  // Fix: Improved Product Fetching Logic
  useEffect(() => {
    if (activeStore) {
      setLoadingProducts(true);
      const productsRef = ref(db, 'products');
      const unsubscribe = onValue(productsRef, (snapshot) => {
        let storeProducts: Product[] = [];
        const data = snapshot.val();
        if (data) {
          Object.keys(data).forEach(key => {
            // Ensure storeId matches exactly
            if (data[key].storeId === activeStore.id) {
              storeProducts.push({ ...data[key], id: key });
            }
          });
        }
        setActiveStoreProducts(storeProducts);
        setLoadingProducts(false);
      });
      return () => unsubscribe();
    } else {
      setActiveStoreProducts([]);
    }
  }, [activeStore]);

  const handleUpdateProfile = async () => {
    const user = auth.currentUser;
    if (!user) return;
    setIsUpdatingProfile(true);
    try {
      await update(ref(db, `customers/${user.uid}`), { name: newName });
      alert("تم تحديث الاسم");
    } catch (e) {
      alert("خطأ في التحديث");
    } finally {
      setIsUpdatingProfile(false);
    }
  };

  const handleUpdateAvatar = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    const user = auth.currentUser;
    if (file && user) {
      setIsUpdatingProfile(true);
      const url = await uploadImage(file);
      if (url) await update(ref(db, `customers/${user.uid}`), { avatar: url });
      setIsUpdatingProfile(false);
    }
  };

  const filteredStores = useMemo(() => {
    let result = stores;
    if (selectedCategory !== 'ALL') result = result.filter(s => s.category === selectedCategory);
    if (searchQuery) result = result.filter(s => s.name.toLowerCase().includes(searchQuery.toLowerCase()));
    return result;
  }, [selectedCategory, searchQuery, stores]);

  const addToCart = (product: Product) => {
    setCart(prev => {
      const existing = prev.find(item => item.product.id === product.id);
      if (existing) return prev.map(item => item.product.id === product.id ? {...item, quantity: item.quantity + 1} : item);
      return [...prev, { product, quantity: 1 }];
    });
  };

  const removeFromCart = (productId: string) => {
    setCart(prev => prev.map(item => item.product.id === productId ? {...item, quantity: Math.max(0, item.quantity - 1)} : item).filter(item => item.quantity > 0));
  };

  const handleCheckout = async () => {
    if (!auth.currentUser || !activeStore) return;
    setIsOrdering(true);
    const orderData = {
      customerId: auth.currentUser.uid,
      customerName: userProfile?.name || userName,
      storeId: activeStore.id,
      storeName: activeStore.name,
      products: cart,
      totalPrice: cart.reduce((s, i) => s + (i.product.price * i.quantity), 0) + 200,
      deliveryFee: 200,
      status: OrderStatus.PENDING,
      timestamp: Date.now(),
      address: "بئر العاتر، حي السلام",
      coordinates: userCoords,
      storeCoordinates: activeStore.coordinates
    };
    try {
      await set(push(ref(db, 'orders')), orderData);
      setCart([]);
      setShowCart(false);
      alert("تم الطلب بنجاح!");
    } catch (e) { alert("خطأ في الطلب"); }
    finally { setIsOrdering(false); }
  };

  return (
    <div className="bg-[#F8F9FA] min-h-screen pb-28 font-cairo select-none">
      {/* Header - Matching Screenshot */}
      <header className="fixed top-0 left-0 right-0 z-40 bg-white/80 backdrop-blur-md py-4 px-6 flex items-center justify-between border-b border-gray-100">
        <button 
          onClick={() => setActiveStore(null)} 
          className={`text-gray-400 text-xs font-bold border border-gray-100 px-3 py-1.5 rounded-xl transition-opacity ${activeStore ? 'opacity-100' : 'opacity-0 pointer-events-none'}`}
        >
          إغلاق المتجر
        </button>

        <div className="text-center">
          <h2 className="text-sm font-black text-gray-800">مرحباً، {userProfile?.name || userName}</h2>
          <p className="text-[10px] text-gray-400 flex items-center justify-center gap-1">
            حي السلام، بئر العاتر <MapPin className="w-2.5 h-2.5 text-brand-500" />
          </p>
        </div>

        <div className="w-10 h-10 bg-brand-500 rounded-2xl flex items-center justify-center shadow-lg shadow-brand-200">
          <span className="text-white font-black text-lg">K</span>
        </div>
      </header>

      <div className="container max-w-lg mx-auto pt-24 px-6">
        {activeTab === 'HOME' ? (
          <>
            {!activeStore ? (
              <div className="space-y-6 animate-fade-in-up">
                <div className="relative">
                   <input type="text" placeholder="ابحث عن مطعم أو منتج..." value={searchQuery} onChange={(e) => setSearchQuery(e.target.value)} className="w-full bg-white border border-gray-100 rounded-3xl py-4 pr-12 shadow-sm font-bold focus:ring-2 focus:ring-brand-500 outline-none" />
                   <Search className="absolute right-4 top-4 w-6 h-6 text-gray-300" />
                </div>

                <div>
                  <h2 className="font-black text-gray-800 mb-3 text-sm">الأقسام</h2>
                  <div className="flex gap-3 overflow-x-auto pb-2 scrollbar-hide">
                    {['ALL', ...Object.values(Category)].map(cat => (
                      <button key={cat} onClick={() => setSelectedCategory(cat as Category | 'ALL')} className={`shrink-0 px-6 py-2 rounded-2xl text-[10px] font-bold transition-all ${selectedCategory === cat ? 'bg-primary-900 text-white' : 'bg-white text-gray-500 border border-gray-100'}`}>
                        {cat === 'ALL' ? 'الكل' : cat}
                      </button>
                    ))}
                  </div>
                </div>

                <div className="space-y-4">
                  {loadingStores ? <Loader2 className="animate-spin mx-auto text-brand-500" /> : filteredStores.map(store => (
                    <div key={store.id} onClick={() => setActiveStore(store)} className="bg-white rounded-[2.5rem] overflow-hidden shadow-sm border border-gray-100 cursor-pointer">
                      <div className="h-48 relative">
                        <img src={store.image} className="w-full h-full object-cover" />
                        <div className="absolute inset-0 bg-gradient-to-t from-black/60 to-transparent"></div>
                        <div className="absolute bottom-4 right-4 text-white">
                           <h3 className="font-black text-xl">{store.name}</h3>
                           <p className="text-xs opacity-80">{store.category}</p>
                        </div>
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            ) : (
              <div className="animate-fade-in-up">
                <div className="relative h-60 rounded-[2.5rem] overflow-hidden mb-6 shadow-xl">
                  <img src={activeStore.image} className="w-full h-full object-cover" />
                  <div className="absolute inset-0 bg-gradient-to-t from-black/80 to-transparent"></div>
                  <div className="absolute bottom-6 right-6 text-white text-right">
                    <h2 className="text-3xl font-black">{activeStore.name}</h2>
                    <p className="text-sm opacity-80">{activeStore.category}</p>
                  </div>
                </div>

                <div className="space-y-4">
                  {loadingProducts ? <Loader2 className="animate-spin mx-auto text-brand-500" /> : 
                    activeStoreProducts.length > 0 ? activeStoreProducts.map(p => (
                      <div key={p.id} className="bg-white p-4 rounded-3xl shadow-sm border border-gray-100 flex gap-4">
                        <img src={p.image} className="w-20 h-20 rounded-2xl object-cover" />
                        <div className="flex-1 flex flex-col justify-between">
                          <h4 className="font-bold text-gray-800 text-sm">{p.name}</h4>
                          <div className="flex justify-between items-end">
                            <span className="text-lg font-black text-brand-600">{formatCurrency(p.price)}</span>
                            <div className="flex items-center gap-2">
                               {cart.find(i => i.product.id === p.id) && (
                                 <button onClick={() => removeFromCart(p.id)} className="bg-gray-100 text-gray-600 p-2 rounded-xl"><Minus className="w-4 h-4" /></button>
                               )}
                               <button onClick={() => addToCart(p)} className="bg-primary-900 text-white p-2 rounded-xl"><Plus className="w-4 h-4" /></button>
                            </div>
                          </div>
                        </div>
                      </div>
                    )) : (
                      <div className="text-center py-10 text-gray-400 font-bold">هذا المتجر لا يملك منتجات حالياً</div>
                    )
                  }
                </div>
              </div>
            )}
          </>
        ) : (
          <div className="animate-fade-in-up">
            <div className="bg-white rounded-[2.5rem] p-8 shadow-sm border border-gray-100 text-center">
               <div className="relative inline-block mb-6">
                 <div className="w-32 h-32 rounded-full border-4 border-brand-100 overflow-hidden shadow-lg">
                   <img src={userProfile?.avatar || `https://api.dicebear.com/7.x/avataaars/svg?seed=${userName}`} className="w-full h-full object-cover" />
                 </div>
                 <button onClick={() => profileImageInputRef.current?.click()} className="absolute bottom-0 right-0 bg-brand-600 text-white p-2.5 rounded-full border-2 border-white shadow-lg"><Camera className="w-5 h-5" /></button>
                 <input type="file" ref={profileImageInputRef} onChange={handleUpdateAvatar} className="hidden" accept="image/*" />
               </div>
               <div className="space-y-6">
                  <input type="text" value={newName} onChange={e => setNewName(e.target.value)} className="w-full bg-gray-50 p-4 rounded-2xl font-black text-center outline-none" placeholder="الاسم" />
                  <button onClick={handleUpdateProfile} disabled={isUpdatingProfile} className="w-full bg-primary-900 text-white py-4 rounded-2xl font-black shadow-lg">{isUpdatingProfile ? <Loader2 className="animate-spin mx-auto" /> : 'حفظ التعديلات'}</button>
                  <button onClick={onLogout} className="w-full bg-danger/10 text-danger py-4 rounded-2xl font-black flex items-center justify-center gap-2 hover:bg-danger hover:text-white transition-all"><LogOut className="w-5 h-5" /> تسجيل الخروج</button>
               </div>
            </div>
          </div>
        )}
      </div>

      {/* Bottom Nav - Dark Theme Matching Screenshot */}
      <nav className="fixed bottom-6 left-6 right-6 bg-[#2B2F3B] rounded-[2.5rem] p-2 flex justify-around items-center shadow-2xl z-50">
        <button onClick={() => setActiveTab('PROFILE')} className={`p-4 rounded-full transition-all ${activeTab === 'PROFILE' ? 'bg-white/10 text-white' : 'text-gray-500'}`}>
          <User className="w-6 h-6" />
        </button>
        <button onClick={() => setActiveTab('HOME')} className={`p-4 rounded-full transition-all ${activeTab === 'HOME' ? 'bg-brand-500 text-white scale-110 shadow-lg shadow-brand-500/30' : 'text-gray-500'}`}>
          <Home className="w-6 h-6" />
        </button>
      </nav>

      {/* Cart Button */}
      {cart.length > 0 && !showCart && activeTab === 'HOME' && (
        <button onClick={() => setShowCart(true)} className="fixed bottom-24 left-6 right-6 bg-primary-900 text-white py-4 rounded-3xl font-black shadow-2xl flex items-center justify-between px-8 z-50 animate-bounce-small">
          <div className="flex items-center gap-3"><ShoppingCart className="w-6 h-6" /> <span className="bg-brand-500 px-2 py-0.5 rounded-lg text-xs">{cart.length}</span></div>
          <span>عرض السلة</span>
          <span>{formatCurrency(cart.reduce((s,i) => s + (i.product.price * i.quantity), 0) + 200)}</span>
        </button>
      )}
    </div>
  );
};

import React, { useState, useRef, useEffect } from 'react';
import { Category, Product, Order, OrderStatus, StoreProfile } from '../types';
