                              </div>
                              {activeOrder.storePhone && (
                                <a href={`tel:${activeOrder.storePhone}`} className="w-12 h-12 bg-orange-500 text-white rounded-full flex items-center justify-center shadow-lg active:scale-90 transition-all">
