import React, { useState, useRef } from 'react';
import { Category, UserRole } from '../types';
import { auth, db } from '../services/firebase';
import { createUserWithEmailAndPassword, signInWithEmailAndPassword } from 'firebase/auth';
import { ref, set } from 'firebase/database';
import { ShoppingBag, Store, Bike, MapPin, ArrowRight, Loader2, Navigation, Camera, ChevronLeft, Sparkles, ShieldCheck } from 'lucide-react';
import { BIR_EL_ATER_CENTER } from '../utils/helpers';

interface AuthScreenProps {
  onLogin: (role: UserRole, name?: string) => void;
}

export const AuthScreen: React.FC<AuthScreenProps> = ({ onLogin }) => {
  const [selectedRole, setSelectedRole] = useState<UserRole | null>(null);
  const [authMode, setAuthMode] = useState<'LOGIN' | 'REGISTER'>('LOGIN');
  const [isLoading, setIsLoading] = useState(false);
  const [isLocating, setIsLocating] = useState(false);
  const [formData, setFormData] = useState({ 
    name: '', email: '', phone: '', password: '', storeImage: '',
    coords: null as {lat: number, lng: number} | null
  });
  const [error, setError] = useState('');

  const handleRoleSelect = (role: UserRole) => {
    setSelectedRole(role);
    setAuthMode('LOGIN');
    setError('');
  };

  const handleGetLocation = () => {
    setIsLocating(true);
    if ("geolocation" in navigator) {
      navigator.geolocation.getCurrentPosition(
        (p) => {
          setFormData(prev => ({ ...prev, coords: { lat: p.coords.latitude, lng: p.coords.longitude } }));
          setIsLocating(false);
        },
        () => { setIsLocating(false); alert("يرجى تفعيل GPS"); }
      );
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsLoading(true);
    try {
      if (authMode === 'REGISTER') {
        if (!formData.coords) throw new Error("يرجى تحديد موقعك أولاً");
        const userCredential = await createUserWithEmailAndPassword(auth, formData.email, formData.password);
        const user = userCredential.user;
        const dbPath = selectedRole === UserRole.CUSTOMER ? 'customers' : selectedRole === UserRole.STORE ? 'stores' : 'drivers';
        await set(ref(db, `${dbPath}/${user.uid}`), {
          id: user.uid, name: formData.name, email: formData.email, phone: formData.phone,
          role: selectedRole, coordinates: formData.coords, createdAt: Date.now()
        });
        onLogin(selectedRole!, formData.name);
      } else {
        await signInWithEmailAndPassword(auth, formData.email, formData.password);
        onLogin(selectedRole || UserRole.CUSTOMER);
      }
    } catch (err: any) { setError(err.message); }
    finally { setIsLoading(false); }
  };

  if (!selectedRole) {
    return (
      <div className="min-h-screen premium-gradient flex flex-col items-center justify-center p-6 relative overflow-hidden font-cairo">
        {/* Background Decor */}
        <div className="absolute top-[-10%] right-[-10%] w-96 h-96 bg-brand-500/20 rounded-full blur-[120px]"></div>
        <div className="absolute bottom-[-10%] left-[-10%] w-96 h-96 bg-blue-500/10 rounded-full blur-[120px]"></div>

        <div className="z-10 text-center mb-16 animate-float">
          <div className="brand-gradient w-28 h-28 rounded-[2.5rem] flex items-center justify-center mx-auto mb-8 shadow-[0_20px_50px_rgba(249,115,22,0.3)] rotate-6 border-4 border-white/10">
            <span className="text-white text-6xl font-black">K</span>
          </div>
          <h1 className="text-7xl font-black text-white mb-3 tracking-tighter">كيمو</h1>
          <div className="flex items-center justify-center gap-2 text-brand-400 font-bold bg-white/5 px-6 py-2 rounded-full border border-white/10">
            <Sparkles className="w-4 h-4" />
            <span>بئر العاتر بين يديك</span>
          </div>
        </div>

        <div className="grid grid-cols-1 gap-5 w-full max-w-md z-10">
          <RoleCard icon={<ShoppingBag/>} title="أنا زبون" desc="اطلب من أفضل المتاجر بضغطة واحدة" onClick={() => handleRoleSelect(UserRole.CUSTOMER)} delay="0ms" />
          <RoleCard icon={<Store/>} title="أنا متجر" desc="وسع تجارتك ووصل لكل بيت في العاتر" onClick={() => handleRoleSelect(UserRole.STORE)} delay="100ms" />
          <RoleCard icon={<Bike/>} title="أنا موصل" desc="كن شريكنا في النجاح واربح بمرونة" onClick={() => handleRoleSelect(UserRole.DRIVER)} delay="200ms" />
        </div>

        <p className="mt-12 text-slate-500 text-xs font-bold flex items-center gap-2">
          <ShieldCheck className="w-4 h-4 text-brand-500" /> تطبيق آمن ومحمي 100%
        </p>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-slate-50 flex items-center justify-center p-6 font-cairo">
      <div className="w-full max-w-md animate-scale-up">
        <button onClick={() => setSelectedRole(null)} className="flex items-center text-slate-400 font-black mb-8 text-sm group">
          <div className="bg-white p-2 rounded-xl shadow-sm border border-slate-100 mr-2 group-hover:bg-slate-100 transition-colors">
            <ChevronLeft className="w-4 h-4" />
          </div>
          العودة للرئيسية
        </button>

        <div className="bg-white rounded-[3rem] p-10 shadow-[0_30px_100px_rgba(0,0,0,0.05)] border border-white">
          <h2 className="text-4xl font-black text-slate-900 mb-2">{authMode === 'LOGIN' ? 'دخول سريع' : 'انضم إلينا'}</h2>
          <p className="text-slate-400 mb-10 font-bold text-sm">أهلاً بك في عالم كيمو المتطور</p>

          <form onSubmit={handleSubmit} className="space-y-5">
            {error && <div className="bg-red-50 text-red-500 p-4 rounded-2xl text-[10px] font-black border border-red-100 animate-shake">{error}</div>}

            {authMode === 'REGISTER' && (
              <>
                <button type="button" onClick={handleGetLocation} className={`w-full p-5 rounded-3xl border-2 border-dashed transition-all flex items-center justify-between font-black ${formData.coords ? 'border-green-500 text-green-600 bg-green-50' : 'border-brand-200 text-brand-600 bg-brand-50'}`}>
                   <span className="text-xs">{formData.coords ? 'تم تحديد موقعك بدقة ✓' : 'تحديد الموقع الجغرافي (إلزامي)'}</span>
                   {isLocating ? <Loader2 className="animate-spin w-5 h-5" /> : <Navigation className="w-5 h-5" />}
                </button>
                <input type="text" value={formData.name} onChange={e => setFormData({...formData, name: e.target.value})} className="input-premium" placeholder="الاسم الكامل" />
                <input type="tel" value={formData.phone} onChange={e => setFormData({...formData, phone: e.target.value})} className="input-premium" placeholder="رقم الهاتف" />
              </>
            )}

            <input type="email" value={formData.email} onChange={e => setFormData({...formData, email: e.target.value})} className="input-premium" placeholder="البريد الإلكتروني" />
            <input type="password" value={formData.password} onChange={e => setFormData({...formData, password: e.target.value})} className="input-premium" placeholder="كلمة المرور" />

