                  <div className="flex justify-between items-center border-t border-slate-50 pt-6">
                     <span className="text-brand-500 font-black text-xl">{formatCurrency(o.totalPrice)}</span>

                     {o.status === OrderStatus.DELIVERED ? (
                        <button 
