import React, { useState, useEffect, useRef } from 'react';
import { MapVisualizer } from '../components/MapVisualizer';
import { RatingModal } from '../components/RatingModal';
import { MapPin, Navigation, CheckCircle, Clock, ExternalLink, Loader2, Package, Bike as BikeIcon, ArrowRight, User, LogOut, Camera, Settings, Phone, RefreshCw, Save } from 'lucide-react';
import { db, auth } from '../services/firebase';
import { ref, onValue, update, get } from 'firebase/database';
import { Order, OrderStatus } from '../types';
import { calculateDistance, USER_LOCATION, formatCurrency } from '../utils/helpers';

export const DriverScreen: React.FC<{onLogout: () => void, userName: string}> = ({ onLogout, userName }) => {
  const [activeTab, setActiveTab] = useState<'AVAILABLE' | 'ACTIVE' | 'PROFILE'>('AVAILABLE');
  const [showRating, setShowRating] = useState(false);
  const [availableOrders, setAvailableOrders] = useState<Order[]>([]);
  const [activeOrder, setActiveOrder] = useState<Order | null>(null);
  const [driverProfile, setDriverProfile] = useState<any>(null);
  const [loading, setLoading] = useState(true);

  // Profile Edit State
  const [isEditing, setIsEditing] = useState(false);
  const [editData, setEditData] = useState({ name: '', phone: '' });
  const [isUpdating, setIsUpdating] = useState(false);
  const [isLocating, setIsLocating] = useState(false);

  const currentDriverId = auth.currentUser?.uid;

  useEffect(() => {
    if (!currentDriverId) return;

    onValue(ref(db, `drivers/${currentDriverId}`), (snap) => {
      if (snap.exists()) {
        const data = snap.val();
        setDriverProfile(data);
        setEditData({ name: data.name || '', phone: data.phone || '' });
      }
    });

    onValue(ref(db, 'orders'), (snapshot) => {
        const data = snapshot.val();
        const available: Order[] = [];
        let myActive: Order | null = null;
        if (data) {
            Object.keys(data).forEach(key => {
                const order = { ...data[key], id: key } as Order;
                if (order.driverId === currentDriverId && order.status !== OrderStatus.DELIVERED) myActive = order;
                if (order.status === OrderStatus.ACCEPTED_BY_STORE && !order.driverId) available.push(order);
            });
        }
        setAvailableOrders(available);
        setActiveOrder(myActive);
        setLoading(false);
    });
  }, [currentDriverId]);

  const handleUpdateProfile = async () => {
    if (!currentDriverId || !editData.name || !editData.phone) return;
    setIsUpdating(true);
    try {
      await update(ref(db, `drivers/${currentDriverId}`), {
        name: editData.name,
        phone: editData.phone
      });
      setIsEditing(false);
      alert("تم تحديث بياناتك بنجاح ✓");
    } catch (e) {
      alert("خطأ أثناء التحديث");
    } finally {
      setIsUpdating(false);
    }
  };

  const handleUpdateLocation = () => {
    setIsLocating(true);
    if ("geolocation" in navigator) {
      navigator.geolocation.getCurrentPosition(
        async (position) => {
          if (currentDriverId) {
            await update(ref(db, `drivers/${currentDriverId}`), {
              coordinates: { 
                lat: position.coords.latitude, 
                lng: position.coords.longitude 
              }
            });
            alert("تم تحديث موقعك الجغرافي بنجاح ✓");
          }
          setIsLocating(false);
        },
        () => {
          alert("يرجى تفعيل الـ GPS لتحديث الموقع");
          setIsLocating(false);
        }
      );
    }
  };

  const handleAcceptOrder = async (orderId: string) => {
      if (!currentDriverId) return;
      await update(ref(db, `orders/${orderId}`), {
          status: OrderStatus.ACCEPTED_BY_DRIVER,
          driverId: currentDriverId,
          driverName: driverProfile?.name || userName
      });
      setActiveTab('ACTIVE');
  };

  const handleCompleteOrder = async () => {
    if (!activeOrder) return;
    await update(ref(db, `orders/${activeOrder.id}`), { status: OrderStatus.DELIVERED });
    setShowRating(true);
  };

  return (
    <div className="min-h-screen bg-[#F8F9FA] pb-28 font-cairo text-right" dir="rtl">
       {showRating && activeOrder && (
         <RatingModal 
           type="CUSTOMER" 
           targetId={activeOrder.customerId} 
           targetName={activeOrder.customerName} 
           onClose={() => { setShowRating(false); setActiveTab('AVAILABLE'); }} 
         />
       )}

       <header className="bg-[#2B2F3B] text-white p-6 shadow-xl sticky top-0 z-10 rounded-b-[2.5rem]">
        <div className="flex justify-between items-center">
          <div className="flex items-center gap-3">
             <div className="w-12 h-12 rounded-2xl overflow-hidden border-2 border-orange-500 bg-white">
                <img src={driverProfile?.avatar || `https://api.dicebear.com/7.x/bottts/svg?seed=${driverProfile?.name || userName}`} className="w-full h-full object-cover" />
             </div>
             <div>
                <h1 className="font-black text-lg">{driverProfile?.name || userName}</h1>
                <p className="text-[10px] text-orange-400 font-black tracking-widest uppercase">KIMO DRIVER</p>
             </div>
          </div>
          <button onClick={() => setActiveTab('PROFILE')} className="p-3 bg-white/10 rounded-2xl"><Settings className="w-5 h-5" /></button>
        </div>
      </header>

      <div className="p-6 max-w-lg mx-auto">
        {activeTab === 'AVAILABLE' ? (
          <div className="space-y-4">
            {availableOrders.length === 0 ? (
                <div className="bg-white rounded-[2.5rem] p-12 text-center text-slate-300 border border-dashed border-slate-200">
                    <BikeIcon className="w-16 h-16 mx-auto mb-4 opacity-10" />
                    <p className="font-black text-sm text-center">لا توجد طلبات جديدة حالياً</p>
                </div>
            ) : (
                availableOrders.map(order => (
                <div key={order.id} className="bg-white p-6 rounded-[2rem] shadow-sm border-r-[10px] border-green-500 animate-fade-in-up">
                    <div className="flex justify-between items-start mb-4">
                        <h3 className="font-black text-xl text-[#2B2F3B]">{order.storeName}</h3>
