         <button onClick={() => setActiveTab('PROFILE')} className={`p-4 rounded-full transition-all ${activeTab === 'PROFILE' ? 'bg-orange-500 text-white shadow-lg' : 'text-slate-500'}`}><User className="w-6 h-6" /></button>
