  const [newProduct, setNewProduct] = useState<Partial<Product>>({
    name: '', description: '', price: 0, category: Category.FOOD, image: ''
  });

  const currentStoreId = auth.currentUser?.uid;

  useEffect(() => {
    if (!currentStoreId) return;

    onValue(ref(db, `stores/${currentStoreId}`), (snapshot) => {
      if (snapshot.exists()) {
        const data = snapshot.val();
        setStoreProfile(data);
        setNewStoreName(data.name || userName);
        setNewStorePhone(data.phone || '');
      }
    });

    onValue(ref(db, 'products'), (snapshot) => {
      const data = snapshot.val();
      const list: Product[] = [];
      if (data) {
        Object.keys(data).forEach(key => {
          if (data[key].storeId === currentStoreId) {
            list.push({ ...data[key], id: key });
          }
        });
      }
      setMyProducts(list.reverse());
    });

    onValue(ref(db, 'orders'), (snapshot) => {
      const data = snapshot.val();
      const list: Order[] = [];
      if (data) {
        Object.keys(data).forEach(key => {
          if (data[key].storeId === currentStoreId) {
            list.push({ ...data[key], id: key });
          }
        });
      }
      setOrders(list.sort((a, b) => b.timestamp - a.timestamp));
      setLoading(false);
    });
  }, [currentStoreId]);

  const handleUpdateStoreProfile = async () => {
    if (!currentStoreId) return;
    setIsUpdatingProfile(true);
    await update(ref(db, `stores/${currentStoreId}`), { 
      name: newStoreName,
      phone: newStorePhone
    });
    setIsUpdatingProfile(false);
    alert("تم تحديث بيانات المتجر ✓");
  };

  const handleUpdateLocation = () => {
    setIsLocating(true);
    if ("geolocation" in navigator) {
      navigator.geolocation.getCurrentPosition(
        async (position) => {
          if (currentStoreId) {
            await update(ref(db, `stores/${currentStoreId}`), {
              coordinates: { 
                lat: position.coords.latitude, 
                lng: position.coords.longitude 
              }
            });
            alert("تم تحديث موقع المتجر بنجاح ✓");
          }
          setIsLocating(false);
        },
        () => {
          alert("فشل تحديد الموقع، يرجى تفعيل GPS");
          setIsLocating(false);
        }
      );
    }
  };

  const handleUpdateStoreImage = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file && currentStoreId) {
      setIsUpdatingProfile(true);
      const url = await uploadImage(file);
      if (url) await update(ref(db, `stores/${currentStoreId}`), { image: url });
      setIsUpdatingProfile(false);
    }
  };

  const saveProduct = async () => {
    if (!newProduct.name || !newProduct.price || !newProduct.image || !currentStoreId) return alert("أكمل البيانات");
    setIsSaving(true);
    try {
      const newRef = push(ref(db, 'products'));
      await set(newRef, { ...newProduct, storeId: currentStoreId, id: newRef.key });
      setIsAddingProduct(false);
      setNewProduct({ name: '', description: '', price: 0, category: Category.FOOD, image: '' });
    } catch (e) { alert("خطأ في الحفظ"); }
    finally { setIsSaving(false); }
  };

  if (loading) return <div className="h-screen flex items-center justify-center"><Loader2 className="animate-spin text-brand-500" /></div>;

  return (
    <div className="min-h-screen bg-[#F8F9FA] pb-24 font-cairo text-right" dir="rtl">
      <header className="p-6 flex justify-between items-center bg-white border-b border-gray-100">
        <h1 className="text-xl font-black text-[#8E949A]">
          {activeTab === 'PRODUCTS' ? 'منتجاتي' : activeTab === 'ORDERS' ? 'الطلبات' : 'حساب المتجر'}
        </h1>
        {activeTab === 'PRODUCTS' && !isAddingProduct && (
          <button onClick={() => setIsAddingProduct(true)} className="bg-[#8E949A] text-white px-5 py-2 rounded-full font-bold text-sm flex items-center gap-1 shadow-sm"><Plus className="w-4 h-4" /> إضافة</button>
        )}
      </header>

      <main className="p-6 max-w-lg mx-auto">
        {activeTab === 'PRODUCTS' && (
          <div className="animate-fade-in-up">
            {!isAddingProduct ? (
              <div className="space-y-4">
                {myProducts.length === 0 ? (
                   <div className="text-center py-20 bg-white rounded-[2rem] border-2 border-dashed border-gray-100 text-gray-300 font-bold">لا توجد منتجات حالياً</div>
                ) : myProducts.map(p => (
                  <div key={p.id} className="bg-white p-4 rounded-[2rem] shadow-sm border border-gray-100 flex gap-4 items-center">
                    <div className="flex-1 text-right py-1">
                      <h4 className="font-bold text-[#8E949A] text-sm mb-2">{p.name}</h4>
                      <span className="text-[10px] bg-slate-100 text-slate-500 px-2 py-1 rounded-md ml-2">{p.category}</span>
                      <span className="text-lg font-black text-[#F9923B]">{formatCurrency(p.price)}</span>
                      <button onClick={() => remove(ref(db, `products/${p.id}`))} className="block mt-2 text-gray-300 hover:text-red-500 transition-colors"><Trash2 className="w-4 h-4"/></button>
                    </div>
                    <img src={p.image} className="w-24 h-24 rounded-[1.5rem] object-cover shadow-sm" />
                  </div>
                ))}
              </div>
            ) : (
              <div className="bg-white p-8 rounded-[2.5rem] shadow-sm animate-scale-up">
                <button onClick={() => setIsAddingProduct(false)} className="mb-6 flex items-center gap-2 text-gray-400 font-bold"><ArrowLeft className="w-5 h-5"/> عودة</button>
                <div className="space-y-5">
                   <div onClick={() => fileInputRef.current?.click()} className="w-full h-40 border-2 border-dashed border-gray-100 rounded-3xl flex items-center justify-center cursor-pointer overflow-hidden relative bg-gray-50">
                     {newProduct.image ? <img src={newProduct.image} className="w-full h-full object-cover" /> : <Upload className="text-gray-300" />}
                     {isUploading && <Loader2 className="animate-spin text-brand-500 absolute" />}
                     <input type="file" ref={fileInputRef} onChange={e => {
                        const file = e.target.files?.[0];
                        if (file) { setIsUploading(true); uploadImage(file).then(url => { if (url) setNewProduct({...newProduct, image: url}); setIsUploading(false); }); }
                     }} className="hidden" accept="image/*" />
                   </div>

                   <div className="space-y-2">
                     <label className="text-xs font-black text-slate-400 pr-2">اسم المنتج</label>
                     <input type="text" placeholder="مثلاً: بيتزا مارغريتا" value={newProduct.name} onChange={e => setNewProduct({...newProduct, name: e.target.value})} className="w-full p-4 bg-gray-50 rounded-2xl font-bold outline-none border border-transparent focus:border-orange-500 transition-all" />
                   </div>

                   <div className="space-y-2">
                     <label className="text-xs font-black text-slate-400 pr-2">السعر (د.ج)</label>
                     <input type="number" placeholder="500" value={newProduct.price || ''} onChange={e => setNewProduct({...newProduct, price: Number(e.target.value)})} className="w-full p-4 bg-gray-50 rounded-2xl font-bold outline-none border border-transparent focus:border-orange-500 transition-all" />
                   </div>

                   <div className="space-y-2">
                     <label className="text-xs font-black text-slate-400 pr-2">فئة المنتج</label>
                     <div className="relative">
                       <select 
                         value={newProduct.category} 
                         onChange={e => setNewProduct({...newProduct, category: e.target.value as Category})}
                         className="w-full p-4 bg-gray-50 rounded-2xl font-bold outline-none border border-transparent focus:border-orange-500 transition-all appearance-none cursor-pointer"
                       >
                         {Object.values(Category).map((cat) => (
                           <option key={cat} value={cat}>{cat}</option>
                         ))}
                       </select>
                       <Tag className="absolute left-4 top-4 text-slate-300 w-5 h-5 pointer-events-none" />
                     </div>
                   </div>

                   <button onClick={saveProduct} disabled={isSaving || isUploading} className="w-full bg-[#2B2F3B] text-white py-5 rounded-[2rem] font-black shadow-lg hover:bg-slate-800 transition-all mt-4 flex items-center justify-center gap-3">
                     {isSaving ? <Loader2 className="animate-spin" /> : 'حفظ المنتج'}
                   </button>
                </div>
              </div>
            )}
          </div>
        )}

        {activeTab === 'ORDERS' && (
          <div className="animate-fade-in-up space-y-4">
            {orders.length === 0 ? (
               <div className="text-center py-20 bg-white rounded-[2rem] border-2 border-dashed border-gray-100 text-gray-300 font-bold">لا توجد طلبات واردة حالياً</div>
            ) : orders.map(order => (
              <div key={order.id} className="bg-white p-6 rounded-[2rem] shadow-sm border border-gray-100">
                <div className="flex justify-between items-start mb-4">
                  <h3 className="font-black text-[#8E949A]">{order.customerName}</h3>
                  <span className="font-black text-brand-600">{formatCurrency(order.totalPrice)}</span>
                </div>
                {order.status === OrderStatus.PENDING ? (
                  <button onClick={() => update(ref(db, `orders/${order.id}`), { status: OrderStatus.ACCEPTED_BY_STORE })} className="w-full bg-[#2B2F3B] text-white py-3 rounded-2xl font-bold">قبول الطلب</button>
                ) : <div className="text-center text-green-500 font-bold py-2 bg-green-50 rounded-xl">{order.status}</div>}
              </div>
            ))}
          </div>
        )}

        {activeTab === 'PROFILE' && (
          <div className="animate-fade-in-up">
            <div className="bg-white p-8 rounded-[2.5rem] shadow-sm border border-gray-100 text-center">
              <div className="relative inline-block mb-8">
                <div className="w-32 h-32 rounded-[2rem] overflow-hidden border-4 border-gray-50 shadow-md relative bg-gray-50">
                  <img src={storeProfile?.image || `https://api.dicebear.com/7.x/initials/svg?seed=${userName}`} className="w-full h-full object-cover" />
                  {isUpdatingProfile && <div className="absolute inset-0 bg-black/40 flex items-center justify-center"><Loader2 className="w-8 h-8 text-white animate-spin" /></div>}
                </div>
                <button onClick={() => profileImageInputRef.current?.click()} className="absolute -bottom-2 -right-2 bg-brand-600 text-white p-3 rounded-2xl shadow-lg border-2 border-white"><Camera className="w-5 h-5" /></button>
                <input type="file" ref={profileImageInputRef} onChange={handleUpdateStoreImage} className="hidden" accept="image/*" />
              </div>

              <div className="space-y-4 text-right">
                <label className="text-xs font-black text-slate-400 pr-2">اسم المتجر</label>
                <input 
                  type="text" 
                  value={newStoreName} 
                  onChange={e => setNewStoreName(e.target.value)} 
                  className="w-full p-4 bg-gray-50 rounded-2xl font-black outline-none focus:border-orange-500 border border-transparent" 
                />

                <label className="text-xs font-black text-slate-400 pr-2">رقم هاتف المتجر</label>
                <input 
                  type="tel" 
                  value={newStorePhone} 
                  onChange={e => setNewStorePhone(e.target.value)} 
                  className="w-full p-4 bg-gray-50 rounded-2xl font-black outline-none focus:border-orange-500 border border-transparent" 
                  placeholder="06XXXXXXXX"
                />

                <button 
                  onClick={handleUpdateLocation}
                  disabled={isLocating}
                  className="w-full py-4 border-2 border-dashed border-orange-200 text-orange-500 rounded-2xl font-black text-xs flex items-center justify-center gap-2"
                >
                  {isLocating ? <Loader2 className="animate-spin w-4 h-4" /> : <RefreshCw className="w-4 h-4" />}
                  تحديث موقع المتجر (GPS)
                </button>

                <div className="pt-4 space-y-3">
                  <button 
                    onClick={handleUpdateStoreProfile} 
                    disabled={isUpdatingProfile} 
                    className="w-full bg-[#2B2F3B] text-white py-4 rounded-2xl font-black shadow-lg"
                  >
                    حفظ التعديلات
                  </button>
                  <button 
                    onClick={onLogout} 
                    className="w-full bg-red-50 text-red-500 py-4 rounded-2xl font-black flex items-center justify-center gap-2 hover:bg-red-500 hover:text-white transition-all"
                  >
                    <LogOut className="w-5 h-5" /> تسجيل الخروج
                  </button>
                </div>
              </div>
            </div>
          </div>
        )}
      </main>

      <nav className="fixed bottom-6 left-6 right-6 bg-[#2B2F3B] rounded-[2.2rem] p-2 flex justify-around items-center shadow-2xl z-50">
         <button onClick={() => setActiveTab('PRODUCTS')} className={`p-4 rounded-full transition-all ${activeTab === 'PRODUCTS' ? 'bg-orange-500 text-white shadow-lg' : 'text-slate-500'}`}><Package className="w-6 h-6" /></button>
         <button onClick={() => setActiveTab('ORDERS')} className={`p-4 rounded-full transition-all ${activeTab === 'ORDERS' ? 'bg-orange-500 text-white shadow-lg' : 'text-slate-500'}`}><ClipboardList className="w-6 h-6" /></button>
         <button onClick={() => setActiveTab('PROFILE')} className={`p-4 rounded-full transition-all ${activeTab === 'PROFILE' ? 'bg-orange-500 text-white shadow-lg' : 'text-slate-500'}`}><User className="w-6 h-6" /></button>
      </nav>
    </div>
  );
};

export enum UserRole {
  GUEST = 'GUEST',
  CUSTOMER = 'CUSTOMER',
  STORE = 'STORE',
  DRIVER = 'DRIVER'
}

export enum OrderStatus {
  PENDING = 'PENDING',               // Customer placed it, waiting for store
  ACCEPTED_BY_STORE = 'ACCEPTED_BY_STORE', // Store accepted, waiting for driver
  ACCEPTED_BY_DRIVER = 'ACCEPTED_BY_DRIVER', // Driver accepted, on the way
  DELIVERED = 'DELIVERED',           // Complete
  CANCELLED = 'CANCELLED'
}

export enum Category {
  FOOD = 'مطاعم',
  CLOTHES = 'ملابس',
  PHONES = 'هواتف وفليكسي',
  SERVICES = 'خدمات',
  KIDS = 'أطفال'
}

export interface Coordinates {
  lat: number;
  lng: number;
}

export interface Product {
  id: string;
  name: string;
  description: string;
  price: number;
  image: string;
  category: Category;
  storeId: string;
}

export interface StoreProfile {
  id: string;
  name: string;
  rating: number;
  reviewCount: number;
  isVerified: boolean;
  category: Category;
  location: string;
  coordinates: Coordinates;
  image: string;
  phone?: string; 
}

export interface Order {
  id: string;
  customerId: string;
  customerName: string;
  customerPhone?: string; 
  storeId: string;
  storeName: string;
  storePhone?: string; 
  driverId?: string;
  driverName?: string;
  driverPhone?: string; // أضفنا رقم هاتف الموصل هنا
  products: {product: Product, quantity: number}[];
  totalPrice: number;
  deliveryFee: number;
  status: OrderStatus;
  timestamp: number;
  address: string;
  coordinates?: Coordinates;
  storeCoordinates?: Coordinates;
}

export interface User {
  id: string;
  name: string;
  role: UserRole;
  avatar?: string;
}

import React, { useState, useEffect, useRef } from 'react';
import { MapVisualizer } from '../components/MapVisualizer';
import { RatingModal } from '../components/RatingModal';
import { MapPin, Navigation, CheckCircle, Clock, ExternalLink, Loader2, Package, Bike as BikeIcon, ArrowRight, User, LogOut, Camera, Settings, Phone, RefreshCw, Save } from 'lucide-react';
import { db, auth } from '../services/firebase';
import { ref, onValue, update, get } from 'firebase/database';
import { Order, OrderStatus } from '../types';
import { calculateDistance, USER_LOCATION, formatCurrency } from '../utils/helpers';

export const DriverScreen: React.FC<{onLogout: () => void, userName: string}> = ({ onLogout, userName }) => {
  const [activeTab, setActiveTab] = useState<'AVAILABLE' | 'ACTIVE' | 'PROFILE'>('AVAILABLE');
  const [showRating, setShowRating] = useState(false);
  const [availableOrders, setAvailableOrders] = useState<Order[]>([]);
  const [activeOrder, setActiveOrder] = useState<Order | null>(null);
  const [driverProfile, setDriverProfile] = useState<any>(null);
  const [loading, setLoading] = useState(true);

  // Profile Edit State
  const [isEditing, setIsEditing] = useState(false);
  const [editData, setEditData] = useState({ name: '', phone: '' });
  const [isUpdating, setIsUpdating] = useState(false);
  const [isLocating, setIsLocating] = useState(false);

  const currentDriverId = auth.currentUser?.uid;

  useEffect(() => {
    if (!currentDriverId) return;

    onValue(ref(db, `drivers/${currentDriverId}`), (snap) => {
      if (snap.exists()) {
        const data = snap.val();
        setDriverProfile(data);
        setEditData({ name: data.name || '', phone: data.phone || '' });
      }
    });

    onValue(ref(db, 'orders'), (snapshot) => {
        const data = snapshot.val();
        const available: Order[] = [];
        let myActive: Order | null = null;
        if (data) {
            Object.keys(data).forEach(key => {
                const order = { ...data[key], id: key } as Order;
                if (order.driverId === currentDriverId && order.status !== OrderStatus.DELIVERED) myActive = order;
                if (order.status === OrderStatus.ACCEPTED_BY_STORE && !order.driverId) available.push(order);
            });
        }
        setAvailableOrders(available);
        setActiveOrder(myActive);
        setLoading(false);
    });
  }, [currentDriverId]);

  const handleUpdateProfile = async () => {
    if (!currentDriverId || !editData.name || !editData.phone) return;
    setIsUpdating(true);
    try {
      await update(ref(db, `drivers/${currentDriverId}`), {
        name: editData.name,
        phone: editData.phone
      });
      setIsEditing(false);
      alert("تم تحديث بياناتك بنجاح ✓");
    } catch (e) {
      alert("خطأ أثناء التحديث");
    } finally {
      setIsUpdating(false);
    }
  };

  const handleUpdateLocation = () => {
    setIsLocating(true);
    if ("geolocation" in navigator) {
      navigator.geolocation.getCurrentPosition(
        async (position) => {
          if (currentDriverId) {
            await update(ref(db, `drivers/${currentDriverId}`), {
              coordinates: { 
                lat: position.coords.latitude, 
                lng: position.coords.longitude 
              }
            });
            alert("تم تحديث موقعك الجغرافي بنجاح ✓");
          }
          setIsLocating(false);
        },
        () => {
          alert("يرجى تفعيل الـ GPS لتحديث الموقع");
          setIsLocating(false);
        }
      );
    }
  };

  const handleAcceptOrder = async (orderId: string) => {
      if (!currentDriverId) return;
      await update(ref(db, `orders/${orderId}`), {
          status: OrderStatus.ACCEPTED_BY_DRIVER,
          driverId: currentDriverId,
          driverName: driverProfile?.name || userName,
          driverPhone: driverProfile?.phone || '' // إرسال رقم هاتف السائق مع الطلبية
      });
      setActiveTab('ACTIVE');
  };

  const handleCompleteOrder = async () => {
    if (!activeOrder) return;
    await update(ref(db, `orders/${activeOrder.id}`), { status: OrderStatus.DELIVERED });
    setShowRating(true);
  };

  return (
    <div className="min-h-screen bg-[#F8F9FA] pb-28 font-cairo text-right" dir="rtl">
       {showRating && activeOrder && (
         <RatingModal 
           type="CUSTOMER" 
           targetId={activeOrder.customerId} 
           targetName={activeOrder.customerName} 
           onClose={() => { setShowRating(false); setActiveTab('AVAILABLE'); }} 
         />
       )}

       <header className="bg-[#2B2F3B] text-white p-6 shadow-xl sticky top-0 z-10 rounded-b-[2.5rem]">
        <div className="flex justify-between items-center">
          <div className="flex items-center gap-3">
             <div className="w-12 h-12 rounded-2xl overflow-hidden border-2 border-orange-500 bg-white">
                <img src={driverProfile?.avatar || `https://api.dicebear.com/7.x/bottts/svg?seed=${driverProfile?.name || userName}`} className="w-full h-full object-cover" />
             </div>
             <div>
                <h1 className="font-black text-lg">{driverProfile?.name || userName}</h1>
                <p className="text-[10px] text-orange-400 font-black tracking-widest uppercase">KIMO DRIVER</p>
             </div>
          </div>
          <button onClick={() => setActiveTab('PROFILE')} className="p-3 bg-white/10 rounded-2xl"><Settings className="w-5 h-5" /></button>
        </div>
      </header>

      <div className="p-6 max-w-lg mx-auto">
        {activeTab === 'AVAILABLE' ? (
          <div className="space-y-4">
            {availableOrders.length === 0 ? (
                <div className="bg-white rounded-[2.5rem] p-12 text-center text-slate-300 border border-dashed border-slate-200">
                    <BikeIcon className="w-16 h-16 mx-auto mb-4 opacity-10" />
                    <p className="font-black text-sm text-center">لا توجد طلبات جديدة حالياً</p>
                </div>
            ) : (
                availableOrders.map(order => (
                <div key={order.id} className="bg-white p-6 rounded-[2rem] shadow-sm border-r-[10px] border-green-500 animate-fade-in-up">
                    <div className="flex justify-between items-start mb-4">
                        <h3 className="font-black text-xl text-[#2B2F3B]">{order.storeName}</h3>
                        <span className="bg-green-500 text-white text-[10px] px-3 py-1.5 rounded-full font-black shadow-sm">{formatCurrency(order.deliveryFee)} ربح</span>
                    </div>
                    <p className="text-[11px] text-slate-400 font-bold flex items-center gap-1.5 mb-5"><MapPin className="w-3.5 h-3.5 text-orange-500" /> الوجهة: {order.address}</p>
                    <button onClick={() => handleAcceptOrder(order.id)} className="w-full bg-[#2B2F3B] text-white py-3.5 rounded-2xl text-xs font-black shadow-lg">قبول الطلبية ✓</button>
                </div>
                ))
            )}
          </div>
        ) : activeTab === 'ACTIVE' ? (
          <div className="space-y-6 animate-fade-in-up">
            {activeOrder && (
                <>
                    <div className="bg-white p-4 rounded-[2.5rem] shadow-xl border border-white">
                        <div className="h-64 rounded-3xl overflow-hidden mb-6 border border-slate-100">
                           <MapVisualizer 
                              storeLocation={activeOrder.storeCoordinates} 
                              customerLocation={activeOrder.coordinates} 
                              height="h-full" 
                              zoom={15}
                           />
                        </div>

                        <div className="space-y-4">
                           <div className="p-5 bg-slate-50 rounded-[1.8rem] border border-slate-100 flex justify-between items-center">
                              <div>
                                <p className="text-[10px] font-black text-orange-600 mb-1 uppercase">1. نقطة الاستلام</p>
                                <p className="font-black text-[#2B2F3B] text-lg">{activeOrder.storeName}</p>
                              </div>
                              <a href={`tel:${activeOrder.storePhone}`} className="w-12 h-12 bg-orange-500 text-white rounded-full flex items-center justify-center shadow-lg active:scale-90 transition-all">
                                <Phone className="w-5 h-5" />
                              </a>
                           </div>
                           <div className="p-5 bg-green-50 rounded-[1.8rem] border border-green-100 flex justify-between items-center">
                              <div>
                                <p className="text-[10px] font-black text-green-600 mb-1 uppercase">2. نقطة التسليم</p>
                                <p className="font-black text-[#2B2F3B] text-lg">{activeOrder.customerName}</p>
                                <p className="text-xs text-slate-400 font-bold">{activeOrder.address}</p>
                              </div>
                              <a href={`tel:${activeOrder.customerPhone}`} className="w-12 h-12 bg-green-500 text-white rounded-full flex items-center justify-center shadow-lg active:scale-90 transition-all">
                                <Phone className="w-5 h-5" />
                              </a>
                           </div>
                        </div>

                        <button onClick={() => window.open(`https://www.google.com/maps/dir/?api=1&destination=${activeOrder.coordinates?.lat},${activeOrder.coordinates?.lng}`, '_blank')} className="w-full mt-8 bg-blue-600 text-white py-4 rounded-3xl font-black text-lg shadow-xl flex items-center justify-center gap-3 active:scale-95 transition-all">
                           <Navigation className="w-6 h-6" /> تشغيل GPS المباشر
                        </button>
                    </div>

                    <button onClick={handleCompleteOrder} className="w-full bg-green-500 text-white py-5 rounded-[2rem] font-black text-xl shadow-2xl hover:scale-105 transition-all">
                        تأكيد تسليم الطلب للزبون
                    </button>
                </>
            )}
          </div>
        ) : (
          <div className="animate-fade-in-up">
             <div className="bg-white p-8 rounded-[2.5rem] shadow-sm border border-gray-100 text-center">
                <div className="w-32 h-32 rounded-[2rem] border-4 border-slate-50 overflow-hidden shadow-lg mx-auto mb-8 bg-slate-50">
                   <img src={driverProfile?.avatar || `https://api.dicebear.com/7.x/bottts/svg?seed=${driverProfile?.name || userName}`} className="w-full h-full object-cover" />
                </div>

                {!isEditing ? (
                  <>
                    <h3 className="text-2xl font-black mb-1 text-center">{driverProfile?.name || userName}</h3>
                    <p className="text-slate-400 font-bold mb-10 text-center">{driverProfile?.phone}</p>

                    <div className="space-y-4">
                       <button onClick={() => setIsEditing(true)} className="w-full bg-slate-50 text-slate-600 py-4 rounded-2xl font-black flex items-center justify-center gap-2 transition-all">
                         تعديل البروفيل
                       </button>
                       <button onClick={onLogout} className="w-full bg-red-50 text-red-500 py-4 rounded-2xl font-black flex items-center justify-center gap-2 hover:bg-red-500 hover:text-white transition-all">
                         <LogOut className="w-5 h-5" /> تسجيل الخروج
                       </button>
                    </div>
                  </>
                ) : (
                  <div className="space-y-4 text-right">
                    <label className="text-xs font-black text-slate-400 pr-2">الاسم</label>
                    <input 
                      type="text" 
                      value={editData.name} 
                      onChange={e => setEditData({...editData, name: e.target.value})}
                      className="w-full p-4 bg-slate-50 border border-slate-100 rounded-2xl font-bold outline-none focus:border-orange-500"
                    />

                    <label className="text-xs font-black text-slate-400 pr-2">رقم الهاتف</label>
                    <input 
                      type="tel" 
                      value={editData.phone} 
                      onChange={e => setEditData({...editData, phone: e.target.value})}
                      className="w-full p-4 bg-slate-50 border border-slate-100 rounded-2xl font-bold outline-none focus:border-orange-500"
                    />

                    <button 
                      onClick={handleUpdateLocation}
                      disabled={isLocating}
                      className="w-full py-4 border-2 border-dashed border-orange-200 text-orange-500 rounded-2xl font-black text-xs flex items-center justify-center gap-2"
                    >
                      {isLocating ? <Loader2 className="animate-spin w-4 h-4" /> : <RefreshCw className="w-4 h-4" />}
                      تحديث موقع العمل (GPS)
                    </button>

                    <div className="flex gap-3 pt-6">
                       <button 
                         onClick={handleUpdateProfile}
                         disabled={isUpdating}
                         className="flex-1 bg-[#2B2F3B] text-white py-4 rounded-2xl font-black shadow-xl flex items-center justify-center gap-2"
                       >
                         {isUpdating ? <Loader2 className="animate-spin" /> : <Save className="w-5 h-5" />}
                         حفظ التغييرات
                       </button>
                       <button 
                         onClick={() => setIsEditing(false)}
                         className="px-6 bg-slate-100 text-slate-400 py-4 rounded-2xl font-black"
                       >
                         إلغاء
                       </button>
                    </div>
                  </div>
                )}
             </div>
          </div>
        )}
      </div>

      <nav className="fixed bottom-6 left-6 right-6 bg-[#2B2F3B] rounded-[2.2rem] p-2 flex justify-around items-center shadow-2xl z-50">
         <button onClick={() => setActiveTab('AVAILABLE')} className={`p-4 rounded-full transition-all ${activeTab === 'AVAILABLE' ? 'bg-orange-500 text-white shadow-lg' : 'text-slate-500'}`}><Package className="w-6 h-6" /></button>
         <button onClick={() => setActiveTab('ACTIVE')} disabled={!activeOrder} className={`p-4 rounded-full transition-all ${activeTab === 'ACTIVE' ? 'bg-orange-500 text-white shadow-lg' : 'text-slate-500'} disabled:opacity-20`}><BikeIcon className="w-6 h-6" /></button>
         <button onClick={() => setActiveTab('PROFILE')} className={`p-4 rounded-full transition-all ${activeTab === 'PROFILE' ? 'bg-orange-500 text-white shadow-lg' : 'text-slate-500'}`}><User className="w-6 h-6" /></button>
      </nav>
    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { Category, Product, StoreProfile, OrderStatus, Order } from '../types';
import { formatCurrency } from '../utils/helpers';
import { db, auth } from '../services/firebase';
import { ref, onValue, push, set, update } from 'firebase/database';
import { 
  Search, Plus, Minus, ShoppingCart, MapPin, Loader2, Home, User, 
  Camera, LogOut, ClipboardList, Trash2, Star, ShieldCheck, Award,
  Utensils, Shirt, Smartphone, Briefcase, Baby, LayoutGrid, Save, RefreshCw,
  Phone, Bike
} from 'lucide-react';
import { RatingModal } from '../components/RatingModal';

export const CustomerScreen: React.FC<{onLogout: () => void, userName: string}> = ({ onLogout, userName }) => {
  const [activeTab, setActiveTab] = useState<'HOME' | 'ORDERS' | 'PROFILE'>('HOME');
  const [activeStore, setActiveStore] = useState<StoreProfile | null>(null);
  const [activeStoreProducts, setActiveStoreProducts] = useState<Product[]>([]);
  const [cart, setCart] = useState<{product: Product; quantity: number}[]>([]);
  const [isOrdering, setIsOrdering] = useState(false);
  const [stores, setStores] = useState<StoreProfile[]>([]);
  const [myOrders, setMyOrders] = useState<Order[]>([]);
  const [loading, setLoading] = useState(true);
  const [searchQuery, setSearchQuery] = useState('');
  const [selectedCategory, setSelectedCategory] = useState<string | null>(null);

  // Profile Editing State
  const [isEditingProfile, setIsEditingProfile] = useState(false);
  const [profileData, setProfileData] = useState({ name: '', phone: '' });
  const [isUpdating, setIsUpdating] = useState(false);
  const [isLocating, setIsLocating] = useState(false);

  // Rating State
  const [ratingOrder, setRatingOrder] = useState<Order | null>(null);

  const user = auth.currentUser;

  useEffect(() => {
    if (!user) return;
    onValue(ref(db, 'stores'), (snap) => {
      const data = snap.val();
      if (data) setStores(Object.keys(data).map(k => ({ id: k, ...data[k] })));
      setLoading(false);
    });
    onValue(ref(db, 'orders'), (snap) => {
      const data = snap.val();
      const list: Order[] = [];
      if (data) Object.keys(data).forEach(k => { if (data[k].customerId === user.uid) list.push({ id: k, ...data[k] }); });
      setMyOrders(list.sort((a, b) => b.timestamp - a.timestamp));
    });
    // Fetch customer profile
    onValue(ref(db, `customers/${user.uid}`), (snap) => {
      if (snap.exists()) {
        const data = snap.val();
        setProfileData({ name: data.name || '', phone: data.phone || '' });
      }
    });
  }, [user]);

  useEffect(() => {
    if (activeStore) {
      onValue(ref(db, 'products'), (snap) => {
        const data = snap.val();
        const list: Product[] = [];
        if (data) Object.keys(data).forEach(k => { if (data[k].storeId === activeStore.id) list.push({ id: k, ...data[k] }); });
        setActiveStoreProducts(list);
      });
    }
  }, [activeStore]);

  const handleUpdateProfile = async () => {
    if (!user || !profileData.name || !profileData.phone) return;
    setIsUpdating(true);
    try {
      await update(ref(db, `customers/${user.uid}`), {
        name: profileData.name,
        phone: profileData.phone
      });
      setIsEditingProfile(false);
      alert('تم تحديث بياناتك بنجاح ✓');
    } catch (e) {
      alert('فشل التحديث، يرجى المحاولة لاحقاً');
    } finally {
      setIsUpdating(false);
    }
  };

  const handleUpdateLocation = () => {
    setIsLocating(true);
    if ("geolocation" in navigator) {
      navigator.geolocation.getCurrentPosition(
        async (position) => {
          if (user) {
            await update(ref(db, `customers/${user.uid}`), {
              coordinates: { 
                lat: position.coords.latitude, 
                lng: position.coords.longitude 
              }
            });
            alert("تم تحديث موقعك الجغرافي بنجاح ✓");
          }
          setIsLocating(false);
        },
        () => {
          alert("يرجى تفعيل الـ GPS لتحديث الموقع");
          setIsLocating(false);
        }
      );
    }
  };

  const addToCart = (p: Product) => {
    setCart(prev => {
      const ex = prev.find(i => i.product.id === p.id);
      if (ex) return prev.map(i => i.product.id === p.id ? {...i, quantity: i.quantity + 1} : i);
      return [...prev, { product: p, quantity: 1 }];
    });
  };

  const removeFromCart = (id: string) => {
    setCart(prev => prev.map(i => i.product.id === id ? {...i, quantity: i.quantity - 1} : i).filter(i => i.quantity > 0));
  };

  const grandTotal = cart.reduce((s, i) => s + (i.product.price * i.quantity), 0) + 200;

  const handleCheckout = async () => {
    if (!activeStore) return;
    setIsOrdering(true);
    const orderData = {
      customerId: user!.uid, customerName: profileData.name || userName,
      storeId: activeStore.id, storeName: activeStore.name,
      products: cart, totalPrice: grandTotal, deliveryFee: 200,
      status: OrderStatus.PENDING, timestamp: Date.now(),
      address: "بئر العاتر، حي السلام",
      customerPhone: profileData.phone || '',
      storePhone: activeStore.phone || '',
      storeCoordinates: activeStore.coordinates
    };
    try {
      await set(push(ref(db, 'orders')), orderData);
      setCart([]); setActiveStore(null); setActiveTab('ORDERS');
    } finally { setIsOrdering(false); }
  };

  const categories = [
    { id: null, name: 'الكل', icon: <LayoutGrid className="w-5 h-5" /> },
    { id: Category.FOOD, name: 'مطاعم', icon: <Utensils className="w-5 h-5" /> },
    { id: Category.CLOTHES, name: 'ملابس', icon: <Shirt className="w-5 h-5" /> },
    { id: Category.PHONES, name: 'هواتف', icon: <Smartphone className="w-5 h-5" /> },
    { id: Category.SERVICES, name: 'خدمات', icon: <Briefcase className="w-5 h-5" /> },
    { id: Category.KIDS, name: 'أطفال', icon: <Baby className="w-5 h-5" /> },
  ];

  const filteredStores = stores.filter(s => {
    const matchesSearch = s.name.toLowerCase().includes(searchQuery.toLowerCase());
    const matchesCategory = !selectedCategory || s.category === selectedCategory;
    return matchesSearch && matchesCategory;
  });

  return (
    <div className="bg-[#F8FAFC] min-h-screen pb-32 font-cairo">
      {/* Modals */}
      {ratingOrder && (
        <RatingModal 
          type="STORE" 
          targetId={ratingOrder.storeId} 
          targetName={ratingOrder.storeName} 
          onClose={() => setRatingOrder(null)} 
        />
      )}

      {/* Immersive Header */}
      <header className="sticky top-0 z-[100] bg-white/80 backdrop-blur-2xl border-b border-slate-100 p-6 flex justify-between items-center shadow-sm">
        <div className="flex items-center gap-4">
          <div className="w-12 h-12 brand-gradient rounded-2xl flex items-center justify-center shadow-lg shadow-brand-200">
            <span className="text-white font-black text-2xl">K</span>
          </div>
          <div>
            <h2 className="text-lg font-black text-slate-900 leading-none">أهلاً، {profileData.name || userName}</h2>
            <div className="flex items-center gap-1 mt-1">
               <MapPin className="w-3 h-3 text-brand-500" />
               <span className="text-[10px] font-bold text-slate-400 uppercase tracking-wider">بئر العاتر • حي السلام</span>
            </div>
          </div>
        </div>
        {activeStore && (
          <button onClick={() => setActiveStore(null)} className="bg-slate-50 text-slate-400 p-3 rounded-2xl hover:bg-slate-100 transition-colors">
            <LogOut className="w-5 h-5" />
          </button>
        )}
      </header>

      <main className="p-6 max-w-lg mx-auto">
        {activeTab === 'HOME' ? (
          <>
            {!activeStore ? (
              <div className="space-y-8 animate-fade-in-up">
                {/* Search Bar */}
                <div className="relative group">
                  <input 
                    type="text" 
                    placeholder="ماذا تريد أن تطلب اليوم؟" 
                    value={searchQuery} 
                    onChange={(e) => setSearchQuery(e.target.value)} 
                    className="w-full bg-white border border-slate-200 rounded-[2rem] py-5 pr-14 shadow-sm font-bold outline-none focus:ring-4 focus:ring-brand-500/10 focus:border-brand-500 transition-all" 
                  />
                  <Search className="absolute right-5 top-5 w-6 h-6 text-slate-300 group-focus-within:text-brand-500 transition-colors" />
                </div>

                {/* Categories Scrollable Bar */}
                <div className="space-y-4">
                  <div className="flex items-center justify-between px-2">
                    <h3 className="text-xl font-black text-slate-900">الأقسام</h3>
                  </div>
                  <div className="flex gap-4 overflow-x-auto pb-4 no-scrollbar">
                    {categories.map((cat) => (
                      <button
                        key={cat.name}
                        onClick={() => setSelectedCategory(cat.id)}
                        className={`flex flex-col items-center gap-2 shrink-0 transition-all ${
                          selectedCategory === cat.id 
                            ? 'scale-105' 
                            : 'opacity-60 grayscale hover:grayscale-0 hover:opacity-100'
                        }`}
                      >
                        <div className={`w-16 h-16 rounded-[1.5rem] flex items-center justify-center transition-all shadow-md ${
                          selectedCategory === cat.id 
                            ? 'brand-gradient text-white shadow-brand-200' 
                            : 'bg-white text-slate-500'
                        }`}>
                          {cat.icon}
                        </div>
                        <span className={`text-xs font-black ${selectedCategory === cat.id ? 'text-brand-600' : 'text-slate-500'}`}>
                          {cat.name}
                        </span>
                      </button>
                    ))}
                  </div>
                </div>

                <div className="flex items-center justify-between px-2">
                   <h3 className="text-2xl font-black text-slate-900">
                     {selectedCategory ? `متاجر ${categories.find(c => c.id === selectedCategory)?.name}` : 'أبرز المتاجر'}
                   </h3>
                   <button onClick={() => setSelectedCategory(null)} className="text-brand-500 font-bold text-sm">عرض الكل</button>
                </div>

                {/* Stores Grid */}
                <div className="grid grid-cols-1 gap-6">
                  {loading ? (
                    <div className="flex justify-center py-20">
                      <Loader2 className="animate-spin text-brand-500 w-10 h-10" />
                    </div>
                  ) : filteredStores.length > 0 ? (
                    filteredStores.map(s => (
                      <div key={s.id} onClick={() => setActiveStore(s)} className="group bg-white rounded-[2.5rem] overflow-hidden shadow-[0_15px_40px_rgba(0,0,0,0.03)] border border-white hover:shadow-xl transition-all cursor-pointer">
                         <div className="h-56 relative overflow-hidden">
                            <img src={s.image} className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-700" />
                            <div className="absolute inset-0 bg-gradient-to-t from-black/80 via-black/20 to-transparent"></div>

                            {/* Live Rating Badge */}
                            <div className="absolute top-4 left-4 bg-white/20 backdrop-blur-md px-4 py-1.5 rounded-full text-white text-[10px] font-black flex items-center gap-1.5 border border-white/10">
                               <Star className={`w-3.5 h-3.5 ${s.rating ? 'fill-yellow-400 text-yellow-400' : 'text-white/50'}`} />
                               <span>{s.rating ? s.rating.toFixed(1) : 'جديد'}</span>
                               {s.reviewCount && <span className="text-white/50 text-[8px]">({s.reviewCount})</span>}
                            </div>

                            <div className="absolute bottom-6 right-6 text-white text-right">
                               <h4 className="text-2xl font-black mb-1">{s.name}</h4>
                               <p className="text-xs opacity-80 font-bold flex items-center justify-end gap-1">
                                 <ShieldCheck className="w-3.5 h-3.5 text-blue-400" /> متجر موثوق في العاتر
                               </p>
                            </div>
                         </div>
                      </div>
                    ))
                  ) : (
                    <div className="text-center py-20 bg-slate-100/50 rounded-[3rem] border border-dashed border-slate-200">
                       <p className="font-bold text-slate-400">لا توجد متاجر في هذا القسم حالياً</p>
                    </div>
                  )}
                </div>
              </div>
            ) : (
              <div className="animate-fade-in-up">
                {/* Store View */}
                <div className="relative h-64 rounded-[3rem] overflow-hidden mb-8 shadow-2xl">
                  <img src={activeStore.image} className="w-full h-full object-cover" />
                  <div className="absolute inset-0 bg-black/40"></div>
                  <div className="absolute inset-0 flex flex-col items-center justify-center text-white text-center p-6">
                    <h2 className="text-4xl font-black mb-2">{activeStore.name}</h2>
                    <div className="flex items-center gap-2">
                      <span className="bg-white/20 backdrop-blur-md px-6 py-2 rounded-full font-bold text-sm">{activeStore.category}</span>
                      <div className="flex items-center gap-1 bg-yellow-400 text-slate-900 px-4 py-2 rounded-full font-black text-xs shadow-lg">
                        <Star className="w-3 h-3 fill-slate-900" /> {activeStore.rating?.toFixed(1) || '0.0'}
                      </div>
                    </div>
                  </div>
                </div>

                <div className="space-y-4">
                  {activeStoreProducts.map(p => {
                    const item = cart.find(i => i.product.id === p.id);
                    return (
                      <div key={p.id} className="bg-white p-4 rounded-[2.2rem] shadow-sm border border-slate-100 flex gap-5 items-center">
                        <img src={p.image} className="w-24 h-24 rounded-[1.8rem] object-cover shadow-sm" />
                        <div className="flex-1 text-right">
                          <h4 className="font-black text-slate-800 text-lg mb-1">{p.name}</h4>
                          <span className="text-brand-500 font-black text-xl">{formatCurrency(p.price)}</span>
                        </div>
                        <div className="flex flex-col items-center gap-2">
                           <button onClick={() => addToCart(p)} className="w-12 h-12 brand-gradient text-white rounded-2xl flex items-center justify-center shadow-lg active:scale-90 transition-all"><Plus /></button>
                           {item && <span className="font-black text-slate-700">{item.quantity}</span>}
                           {item && <button onClick={() => removeFromCart(p.id)} className="w-12 h-12 bg-slate-100 text-slate-400 rounded-2xl flex items-center justify-center active:scale-90 transition-all"><Minus /></button>}
                        </div>
                      </div>
                    );
                  })}
                </div>
              </div>
            )}
          </>
        ) : activeTab === 'ORDERS' ? (
          <div className="animate-fade-in-up space-y-6">
             <h2 className="text-3xl font-black text-slate-900 mb-2">تتبع طلباتك</h2>
             {myOrders.length === 0 ? <div className="text-center py-20 text-slate-300 font-bold">لا توجد طلبات سابقة</div> : myOrders.map(o => (
               <div key={o.id} className="bg-white p-6 rounded-[2.5rem] shadow-sm border border-slate-50 relative overflow-hidden group">
                  <div className="absolute top-0 right-0 w-2 h-full brand-gradient"></div>
                  <div className="flex justify-between items-start mb-4">
                     <div>
                        <h3 className="font-black text-xl text-slate-900">{o.storeName}</h3>
                        <p className="text-[10px] text-slate-400 font-bold">{new Date(o.timestamp).toLocaleString('ar-DZ')}</p>
                     </div>
                     <span className={`px-4 py-2 rounded-2xl text-[10px] font-black ${o.status === OrderStatus.DELIVERED ? 'bg-green-50 text-green-500' : 'bg-orange-50 text-orange-500'}`}>
                        {o.status === OrderStatus.PENDING ? 'قيد الانتظار' : 
                         o.status === OrderStatus.ACCEPTED_BY_STORE ? 'جاري التحضير' :
                         o.status === OrderStatus.ACCEPTED_BY_DRIVER ? 'في الطريق' : 'تم التوصيل'}
                     </span>
                  </div>

                  {o.status === OrderStatus.ACCEPTED_BY_DRIVER && o.driverId && (
                    <div className="mb-6 p-4 bg-brand-50 rounded-2xl border border-brand-100 flex items-center justify-between animate-scale-up">
                      <div className="flex items-center gap-3">
                        <div className="w-10 h-10 bg-brand-500 rounded-full flex items-center justify-center text-white">
                          <Bike className="w-5 h-5" />
                        </div>
                        <div>
                          <p className="text-[10px] font-black text-brand-600 uppercase">الموصل في الطريق</p>
                          <p className="font-black text-slate-800">{o.driverName}</p>
                        </div>
                      </div>
                      <div className="flex items-center gap-3">
                        <div className="text-left">
                          <p className="text-[8px] text-slate-400 font-bold">سعر التوصيل</p>
                          <p className="text-xs font-black text-brand-600">{formatCurrency(o.deliveryFee)}</p>
                        </div>
                        <a href={`tel:${o.driverPhone}`} className="w-10 h-10 bg-white text-brand-500 rounded-full flex items-center justify-center shadow-sm border border-brand-100 active:scale-90 transition-all">
                          <Phone className="w-4 h-4" />
                        </a>
                      </div>
                    </div>
                  )}

                  <div className="flex justify-between items-center border-t border-slate-50 pt-6">
                     <span className="text-brand-500 font-black text-xl">{formatCurrency(o.totalPrice)}</span>

                     {o.status === OrderStatus.DELIVERED ? (
                        <button 
                          onClick={() => setRatingOrder(o)}
                          className="flex items-center gap-2 bg-yellow-400 text-slate-900 px-6 py-2.5 rounded-2xl font-black text-xs shadow-lg shadow-yellow-200 active:scale-95 transition-all"
                        >
                          <Star className="w-4 h-4 fill-slate-900" /> قيّم التجربة
                        </button>
                     ) : (
                        <div className="flex -space-x-3 rtl:space-x-reverse">
                           {o.products.slice(0, 3).map((item, i) => (
                              <img key={i} src={item.product.image} className="w-10 h-10 rounded-full border-2 border-white object-cover shadow-sm" />
                           ))}
                        </div>
                     )}
                  </div>
               </div>
             ))}
          </div>
        ) : (
          <div className="animate-fade-in-up">
            <div className="bg-white rounded-[3rem] p-8 shadow-sm border border-slate-50 text-center">
               <div className="relative inline-block mb-8">
                 <div className="w-32 h-32 rounded-full border-8 border-slate-50 shadow-2xl p-2 bg-white mx-auto">
                   <img src={`https://api.dicebear.com/7.x/avataaars/svg?seed=${profileData.name || userName}`} className="w-full h-full object-cover rounded-full" />
                 </div>
                 <button className="absolute bottom-0 right-0 brand-gradient text-white p-2 rounded-xl border-4 border-white shadow-xl"><Camera className="w-5 h-5" /></button>
               </div>

               {!isEditingProfile ? (
                 <>
                   <h3 className="text-3xl font-black text-slate-900 mb-2">{profileData.name || userName}</h3>
                   <div className="flex items-center justify-center gap-2 text-slate-400 font-bold mb-8">
                      <Award className="w-4 h-4 text-brand-500" />
                      <span>زبون ذهبي في كيمو</span>
                   </div>

                   <div className="space-y-3">
                      <button onClick={() => setIsEditingProfile(true)} className="w-full bg-slate-50 text-slate-600 py-4 rounded-[1.8rem] font-black flex items-center justify-center gap-3 hover:bg-slate-100 transition-all">
                        تعديل بيانات الحساب
                      </button>
                      <button onClick={onLogout} className="w-full bg-red-50 text-red-500 py-4 rounded-[1.8rem] font-black flex items-center justify-center gap-3 hover:bg-red-500 hover:text-white transition-all">
                        <LogOut className="w-5 h-5" /> تسجيل الخروج
                      </button>
                   </div>
                 </>
               ) : (
                 <div className="space-y-4 animate-scale-up text-right">
                    <label className="text-xs font-black text-slate-400 pr-2">الاسم الكامل</label>
                    <input 
                      type="text" 
                      value={profileData.name} 
                      onChange={e => setProfileData({...profileData, name: e.target.value})}
                      className="w-full p-4 bg-slate-50 border border-slate-100 rounded-2xl font-bold outline-none focus:border-brand-500 transition-all"
                    />

                    <label className="text-xs font-black text-slate-400 pr-2">رقم الهاتف</label>
                    <input 
                      type="tel" 
                      value={profileData.phone} 
                      onChange={e => setProfileData({...profileData, phone: e.target.value})}
                      className="w-full p-4 bg-slate-50 border border-slate-100 rounded-2xl font-bold outline-none focus:border-brand-500 transition-all"
                    />

                    <button 
                      onClick={handleUpdateLocation}
                      disabled={isLocating}
                      className="w-full py-4 border-2 border-dashed border-brand-200 text-brand-500 rounded-2xl font-black text-xs flex items-center justify-center gap-2 hover:bg-brand-50 transition-all"
                    >
                      {isLocating ? <Loader2 className="animate-spin w-4 h-4" /> : <RefreshCw className="w-4 h-4" />}
                      تحديث موقعي (GPS)
                    </button>

                    <div className="flex gap-3 pt-4">
                       <button 
                         onClick={handleUpdateProfile}
                         disabled={isUpdating}
                         className="flex-1 brand-gradient text-white py-4 rounded-2xl font-black shadow-xl flex items-center justify-center gap-2"
                       >
                         {isUpdating ? <Loader2 className="animate-spin" /> : <Save className="w-5 h-5" />}
                         حفظ التعديلات
                       </button>
                       <button 
                         onClick={() => setIsEditingProfile(false)}
                         className="px-6 bg-slate-100 text-slate-400 py-4 rounded-2xl font-black"
                       >
                         إلغاء
                       </button>
                    </div>
                 </div>
               )}
            </div>
          </div>
        )}
      </main>

      {/* Floating Bottom Navigation */}
      <nav className="fixed bottom-8 left-8 right-8 bg-slate-900/95 backdrop-blur-xl rounded-[2.5rem] p-3 flex justify-around items-center floating-nav z-[200] border border-white/10">
        <NavBtn act={activeTab === 'PROFILE'} onClick={() => setActiveTab('PROFILE')} icon={<User />} />
        <NavBtn act={activeTab === 'ORDERS'} onClick={() => setActiveTab('ORDERS')} icon={<ClipboardList />} />
        <NavBtn act={activeTab === 'HOME'} onClick={() => setActiveTab('HOME')} icon={<Home />} />
      </nav>

      {/* Cart Drawer */}
      {cart.length > 0 && activeTab === 'HOME' && activeStore && (
        <div className="fixed bottom-32 left-8 right-8 bg-white rounded-[2.8rem] shadow-[0_-20px_80px_rgba(0,0,0,0.15)] p-8 z-[150] animate-slide-up border border-slate-100">
           <div className="flex justify-between items-center mb-6">
              <h3 className="font-black text-2xl text-slate-900">سلتك الحالية</h3>
              <button onClick={() => setCart([])} className="text-slate-300 hover:text-red-500 transition-colors"><Trash2 className="w-6 h-6" /></button>
           </div>
           <div className="flex justify-between items-center bg-slate-50 p-6 rounded-[2rem] mb-6">
              <div>
                 <p className="text-xs text-slate-400 font-bold">المجموع الكلي</p>
                 <p className="text-3xl font-black text-brand-500">{formatCurrency(grandTotal)}</p>
              </div>
              <button onClick={handleCheckout} disabled={isOrdering} className="brand-gradient text-white px-10 py-4 rounded-[1.8rem] font-black shadow-xl flex items-center gap-3 active:scale-95 transition-all">
                {isOrdering ? <Loader2 className="animate-spin" /> : <><ShoppingCart /> اطلب الآن</>}
              </button>
           </div>
        </div>
      )}

      <style>{`
        .no-scrollbar::-webkit-scrollbar {
          display: none;
        }
        .no-scrollbar {
          -ms-overflow-style: none;
          scrollbar-width: none;
        }
      `}</style>
    </div>
  );
};

const NavBtn = ({ act, onClick, icon }: any) => (
  <button onClick={onClick} className={`p-5 rounded-full transition-all duration-500 ${act ? 'bg-brand-500 text-white scale-125 shadow-[0_10px_25px_rgba(249,115,22,0.4)]' : 'text-slate-500 hover:text-slate-300'}`}>
    {React.cloneElement(icon, { size: 28 })}
  </button>
);

import React, { useState, useEffect, useRef } from 'react';
import { Category, Product, StoreProfile, OrderStatus, Order } from '../types';
import { formatCurrency } from '../utils/helpers';
import { db, auth } from '../services/firebase';
import { ref, onValue, push, set, update } from 'firebase/database';
import { 
  Search, Plus, Minus, ShoppingCart, MapPin, Loader2, Home, User, 
  Camera, LogOut, ClipboardList, Trash2, Star, ShieldCheck, Award,
  Utensils, Shirt, Smartphone, Briefcase, Baby, LayoutGrid, Save, RefreshCw,
  Phone, Bike
} from 'lucide-react';
import { RatingModal } from '../components/RatingModal';

export const CustomerScreen: React.FC<{onLogout: () => void, userName: string}> = ({ onLogout, userName }) => {
  const [activeTab, setActiveTab] = useState<'HOME' | 'ORDERS' | 'PROFILE'>('HOME');
  const [activeStore, setActiveStore] = useState<StoreProfile | null>(null);
  const [activeStoreProducts, setActiveStoreProducts] = useState<Product[]>([]);
  const [cart, setCart] = useState<{product: Product; quantity: number}[]>([]);
  const [isOrdering, setIsOrdering] = useState(false);
  const [stores, setStores] = useState<StoreProfile[]>([]);
  const [myOrders, setMyOrders] = useState<Order[]>([]);
  const [loading, setLoading] = useState(true);
  const [searchQuery, setSearchQuery] = useState('');
  const [selectedCategory, setSelectedCategory] = useState<string | null>(null);

  // Profile Editing State
  const [isEditingProfile, setIsEditingProfile] = useState(false);
  const [profileData, setProfileData] = useState({ name: '', phone: '' });
  const [isUpdating, setIsUpdating] = useState(false);
  const [isLocating, setIsLocating] = useState(false);

  // Rating State
  const [ratingOrder, setRatingOrder] = useState<Order | null>(null);

  const user = auth.currentUser;

  useEffect(() => {
    if (!user) return;
    onValue(ref(db, 'stores'), (snap) => {
      const data = snap.val();
      if (data) setStores(Object.keys(data).map(k => ({ id: k, ...data[k] })));
      setLoading(false);
    });
    onValue(ref(db, 'orders'), (snap) => {
      const data = snap.val();
      const list: Order[] = [];
      if (data) Object.keys(data).forEach(k => { if (data[k].customerId === user.uid) list.push({ id: k, ...data[k] }); });
      setMyOrders(list.sort((a, b) => b.timestamp - a.timestamp));
    });
    // Fetch customer profile
    onValue(ref(db, `customers/${user.uid}`), (snap) => {
      if (snap.exists()) {
        const data = snap.val();
        setProfileData({ name: data.name || '', phone: data.phone || '' });
      }
    });
  }, [user]);

  useEffect(() => {
    if (activeStore) {
      onValue(ref(db, 'products'), (snap) => {
        const data = snap.val();
        const list: Product[] = [];
        if (data) Object.keys(data).forEach(k => { if (data[k].storeId === activeStore.id) list.push({ id: k, ...data[k] }); });
        setActiveStoreProducts(list);
      });
    }
  }, [activeStore]);

  const handleUpdateProfile = async () => {
    if (!user || !profileData.name || !profileData.phone) return;
    setIsUpdating(true);
    try {
      await update(ref(db, `customers/${user.uid}`), {
        name: profileData.name,
        phone: profileData.phone
      });
      setIsEditingProfile(false);
      alert('تم تحديث بياناتك بنجاح ✓');
    } catch (e) {
      alert('فشل التحديث، يرجى المحاولة لاحقاً');
    } finally {
      setIsUpdating(false);
    }
  };

  const handleUpdateLocation = () => {
    setIsLocating(true);
    if ("geolocation" in navigator) {
      navigator.geolocation.getCurrentPosition(
        async (position) => {
          if (user) {
            await update(ref(db, `customers/${user.uid}`), {
              coordinates: { 
                lat: position.coords.latitude, 
                lng: position.coords.longitude 
              }
            });
            alert("تم تحديث موقعك الجغرافي بنجاح ✓");
          }
          setIsLocating(false);
        },
        () => {
          alert("يرجى تفعيل الـ GPS لتحديث الموقع");
          setIsLocating(false);
        }
      );
    }
  };

  const addToCart = (p: Product) => {
    setCart(prev => {
      const ex = prev.find(i => i.product.id === p.id);
      if (ex) return prev.map(i => i.product.id === p.id ? {...i, quantity: i.quantity + 1} : i);
      return [...prev, { product: p, quantity: 1 }];
    });
  };

  const removeFromCart = (id: string) => {
    setCart(prev => prev.map(i => i.product.id === id ? {...i, quantity: i.quantity - 1} : i).filter(i => i.quantity > 0));
  };

  const grandTotal = cart.reduce((s, i) => s + (i.product.price * i.quantity), 0) + 200;

  const handleCheckout = async () => {
    if (!activeStore) return;
    setIsOrdering(true);
    const orderData = {
      customerId: user!.uid, customerName: profileData.name || userName,
      storeId: activeStore.id, storeName: activeStore.name,
      products: cart, totalPrice: grandTotal, deliveryFee: 200,
      status: OrderStatus.PENDING, timestamp: Date.now(),
      address: "بئر العاتر، حي السلام",
      customerPhone: profileData.phone || '',
      storePhone: activeStore.phone || '',
      storeCoordinates: activeStore.coordinates
    };
    try {
      await set(push(ref(db, 'orders')), orderData);
      setCart([]); setActiveStore(null); setActiveTab('ORDERS');
    } finally { setIsOrdering(false); }
  };

  const categories = [
    { id: null, name: 'الكل', icon: <LayoutGrid className="w-5 h-5" /> },
    { id: Category.FOOD, name: 'مطاعم', icon: <Utensils className="w-5 h-5" /> },
    { id: Category.CLOTHES, name: 'ملابس', icon: <Shirt className="w-5 h-5" /> },
    { id: Category.PHONES, name: 'هواتف', icon: <Smartphone className="w-5 h-5" /> },
    { id: Category.SERVICES, name: 'خدمات', icon: <Briefcase className="w-5 h-5" /> },
    { id: Category.KIDS, name: 'أطفال', icon: <Baby className="w-5 h-5" /> },
  ];

  const filteredStores = stores.filter(s => {
    const matchesSearch = s.name.toLowerCase().includes(searchQuery.toLowerCase());
    const matchesCategory = !selectedCategory || s.category === selectedCategory;
    return matchesSearch && matchesCategory;
  });

  return (
    <div className="bg-[#F8FAFC] min-h-screen pb-32 font-cairo">
      {/* Modals */}
      {ratingOrder && (
        <RatingModal 
          type="STORE" 
          targetId={ratingOrder.storeId} 
          targetName={ratingOrder.storeName} 
          onClose={() => setRatingOrder(null)} 
        />
      )}

      {/* Immersive Header */}
      <header className="sticky top-0 z-[100] bg-white/80 backdrop-blur-2xl border-b border-slate-100 p-6 flex justify-between items-center shadow-sm">
        <div className="flex items-center gap-4 flex-1 min-w-0">
          <div className="w-12 h-12 brand-gradient rounded-2xl flex items-center justify-center shadow-lg shadow-brand-200 shrink-0">
            <span className="text-white font-black text-2xl">K</span>
          </div>
          <div className="flex-1 min-w-0">
            <h2 className="text-lg font-black text-slate-900 leading-none truncate">أهلاً، {profileData.name || userName}</h2>
            <div className="flex items-center gap-1 mt-1">
               <MapPin className="w-3 h-3 text-brand-500 shrink-0" />
               <span className="text-[10px] font-bold text-slate-400 uppercase tracking-wider truncate">بئر العاتر • حي السلام</span>
            </div>
          </div>
        </div>
        {activeStore && (
          <button onClick={() => setActiveStore(null)} className="bg-slate-50 text-slate-400 p-3 rounded-2xl hover:bg-slate-100 transition-colors mr-2">
            <LogOut className="w-5 h-5" />
          </button>
        )}
      </header>

      <main className="p-6 max-w-lg mx-auto">
        {activeTab === 'HOME' ? (
          <>
            {!activeStore ? (
              <div className="space-y-8 animate-fade-in-up">
                {/* Search Bar */}
                <div className="relative group">
                  <input 
                    type="text" 
                    placeholder="ماذا تريد أن تطلب اليوم؟" 
                    value={searchQuery} 
                    onChange={(e) => setSearchQuery(e.target.value)} 
                    className="w-full bg-white border border-slate-200 rounded-[2rem] py-5 pr-14 shadow-sm font-bold outline-none focus:ring-4 focus:ring-brand-500/10 focus:border-brand-500 transition-all" 
                  />
                  <Search className="absolute right-5 top-5 w-6 h-6 text-slate-300 group-focus-within:text-brand-500 transition-colors" />
                </div>

                {/* Categories Scrollable Bar */}
                <div className="space-y-4">
                  <div className="flex items-center justify-between px-2">
                    <h3 className="text-xl font-black text-slate-900">الأقسام</h3>
                  </div>
                  <div className="flex gap-4 overflow-x-auto pb-4 no-scrollbar">
                    {categories.map((cat) => (
                      <button
                        key={cat.name}
                        onClick={() => setSelectedCategory(cat.id)}
                        className={`flex flex-col items-center gap-2 shrink-0 transition-all ${
                          selectedCategory === cat.id 
                            ? 'scale-105' 
                            : 'opacity-60 grayscale hover:grayscale-0 hover:opacity-100'
                        }`}
                      >
                        <div className={`w-16 h-16 rounded-[1.5rem] flex items-center justify-center transition-all shadow-md ${
                          selectedCategory === cat.id 
                            ? 'brand-gradient text-white shadow-brand-200' 
                            : 'bg-white text-slate-500'
                        }`}>
                          {cat.icon}
                        </div>
                        <span className={`text-xs font-black ${selectedCategory === cat.id ? 'text-brand-600' : 'text-slate-500'}`}>
                          {cat.name}
                        </span>
                      </button>
                    ))}
                  </div>
                </div>

                <div className="flex items-center justify-between px-2">
                   <h3 className="text-2xl font-black text-slate-900">
                     {selectedCategory ? `متاجر ${categories.find(c => c.id === selectedCategory)?.name}` : 'أبرز المتاجر'}
                   </h3>
                   <button onClick={() => setSelectedCategory(null)} className="text-brand-500 font-bold text-sm">عرض الكل</button>
                </div>

                {/* Stores Grid */}
                <div className="grid grid-cols-1 gap-6">
                  {loading ? (
                    <div className="flex justify-center py-20">
                      <Loader2 className="animate-spin text-brand-500 w-10 h-10" />
                    </div>
                  ) : filteredStores.length > 0 ? (
                    filteredStores.map(s => (
                      <div key={s.id} onClick={() => setActiveStore(s)} className="group bg-white rounded-[2.5rem] overflow-hidden shadow-[0_15px_40px_rgba(0,0,0,0.03)] border border-white hover:shadow-xl transition-all cursor-pointer">
                         <div className="h-56 relative overflow-hidden">
                            <img src={s.image} className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-700" />
                            <div className="absolute inset-0 bg-gradient-to-t from-black/80 via-black/20 to-transparent"></div>

                            {/* Live Rating Badge */}
                            <div className="absolute top-4 left-4 bg-white/20 backdrop-blur-md px-4 py-1.5 rounded-full text-white text-[10px] font-black flex items-center gap-1.5 border border-white/10">
                               <Star className={`w-3.5 h-3.5 ${s.rating ? 'fill-yellow-400 text-yellow-400' : 'text-white/50'}`} />
                               <span>{s.rating ? s.rating.toFixed(1) : 'جديد'}</span>
                               {s.reviewCount && <span className="text-white/50 text-[8px]">({s.reviewCount})</span>}
                            </div>

                            <div className="absolute bottom-6 right-6 text-white text-right max-w-[80%]">
                               <h4 className="text-2xl font-black mb-1 truncate">{s.name}</h4>
                               <p className="text-xs opacity-80 font-bold flex items-center justify-end gap-1">
                                 <ShieldCheck className="w-3.5 h-3.5 text-blue-400" /> متجر موثوق في العاتر
                               </p>
                            </div>
                         </div>
                      </div>
                    ))
                  ) : (
                    <div className="text-center py-20 bg-slate-100/50 rounded-[3rem] border border-dashed border-slate-200">
                       <p className="font-bold text-slate-400">لا توجد متاجر في هذا القسم حالياً</p>
                    </div>
                  )}
                </div>
              </div>
            ) : (
              <div className="animate-fade-in-up">
                {/* Store View */}
                <div className="relative h-64 rounded-[3rem] overflow-hidden mb-8 shadow-2xl">
                  <img src={activeStore.image} className="w-full h-full object-cover" />
                  <div className="absolute inset-0 bg-black/40"></div>
                  <div className="absolute inset-0 flex flex-col items-center justify-center text-white text-center p-6">
                    <h2 className="text-4xl font-black mb-2 break-words max-w-full">{activeStore.name}</h2>
                    <div className="flex items-center gap-2">
                      <span className="bg-white/20 backdrop-blur-md px-6 py-2 rounded-full font-bold text-sm">{activeStore.category}</span>
                      <div className="flex items-center gap-1 bg-yellow-400 text-slate-900 px-4 py-2 rounded-full font-black text-xs shadow-lg">
                        <Star className="w-3 h-3 fill-slate-900" /> {activeStore.rating?.toFixed(1) || '0.0'}
                      </div>
                    </div>
                  </div>
                </div>

                <div className="space-y-4">
                  {activeStoreProducts.map(p => {
                    const item = cart.find(i => i.product.id === p.id);
                    return (
                      <div key={p.id} className="bg-white p-4 rounded-[2.2rem] shadow-sm border border-slate-100 flex gap-5 items-center">
                        <img src={p.image} className="w-24 h-24 rounded-[1.8rem] object-cover shadow-sm shrink-0" />
                        <div className="flex-1 text-right min-w-0">
                          <h4 className="font-black text-slate-800 text-lg mb-1 truncate">{p.name}</h4>
                          <span className="text-brand-500 font-black text-xl">{formatCurrency(p.price)}</span>
                        </div>
                        <div className="flex flex-col items-center gap-2 shrink-0">
                           <button onClick={() => addToCart(p)} className="w-12 h-12 brand-gradient text-white rounded-2xl flex items-center justify-center shadow-lg active:scale-90 transition-all"><Plus /></button>
                           {item && <span className="font-black text-slate-700">{item.quantity}</span>}
                           {item && <button onClick={() => removeFromCart(p.id)} className="w-12 h-12 bg-slate-100 text-slate-400 rounded-2xl flex items-center justify-center active:scale-90 transition-all"><Minus /></button>}
                        </div>
                      </div>
                    );
                  })}
                </div>
              </div>
            )}
          </>
        ) : activeTab === 'ORDERS' ? (
          <div className="animate-fade-in-up space-y-6">
             <h2 className="text-3xl font-black text-slate-900 mb-2">تتبع طلباتك</h2>
             {myOrders.length === 0 ? <div className="text-center py-20 text-slate-300 font-bold">لا توجد طلبات سابقة</div> : myOrders.map(o => (
               <div key={o.id} className="bg-white p-6 rounded-[2.5rem] shadow-sm border border-slate-50 relative overflow-hidden group">
                  <div className="absolute top-0 right-0 w-2 h-full brand-gradient"></div>
                  <div className="flex justify-between items-start mb-4">
                     <div className="flex-1 min-w-0">
                        <h3 className="font-black text-xl text-slate-900 truncate">{o.storeName}</h3>
                        <p className="text-[10px] text-slate-400 font-bold">{new Date(o.timestamp).toLocaleString('ar-DZ')}</p>
                     </div>
                     <span className={`px-4 py-2 rounded-2xl text-[10px] font-black shrink-0 ml-2 ${o.status === OrderStatus.DELIVERED ? 'bg-green-50 text-green-500' : 'bg-orange-50 text-orange-500'}`}>
                        {o.status === OrderStatus.PENDING ? 'قيد الانتظار' : 
                         o.status === OrderStatus.ACCEPTED_BY_STORE ? 'جاري التحضير' :
                         o.status === OrderStatus.ACCEPTED_BY_DRIVER ? 'في الطريق' : 'تم التوصيل'}
                     </span>
                  </div>

                  {o.status === OrderStatus.ACCEPTED_BY_DRIVER && o.driverId && (
                    <div className="mb-6 p-4 bg-brand-50 rounded-2xl border border-brand-100 flex items-center justify-between animate-scale-up">
                      <div className="flex items-center gap-3 min-w-0 flex-1">
                        <div className="w-10 h-10 bg-brand-500 rounded-full flex items-center justify-center text-white shrink-0">
                          <Bike className="w-5 h-5" />
                        </div>
                        <div className="min-w-0">
                          <p className="text-[10px] font-black text-brand-600 uppercase">الموصل في الطريق</p>
                          <p className="font-black text-slate-800 truncate">{o.driverName}</p>
                        </div>
                      </div>
                      <div className="flex items-center gap-3 shrink-0">
                        <div className="text-left">
                          <p className="text-[8px] text-slate-400 font-bold">سعر التوصيل</p>
                          <p className="text-xs font-black text-brand-600">{formatCurrency(o.deliveryFee)}</p>
                        </div>
                        <a href={`tel:${o.driverPhone}`} className="w-10 h-10 bg-white text-brand-500 rounded-full flex items-center justify-center shadow-sm border border-brand-100 active:scale-90 transition-all">
                          <Phone className="w-4 h-4" />
                        </a>
                      </div>
                    </div>
                  )}

                  <div className="flex justify-between items-center border-t border-slate-50 pt-6">
                     <span className="text-brand-500 font-black text-xl">{formatCurrency(o.totalPrice)}</span>

                     {o.status === OrderStatus.DELIVERED ? (
                        <button 
                          onClick={() => setRatingOrder(o)}
                          className="flex items-center gap-2 bg-yellow-400 text-slate-900 px-6 py-2.5 rounded-2xl font-black text-xs shadow-lg shadow-yellow-200 active:scale-95 transition-all"
                        >
                          <Star className="w-4 h-4 fill-slate-900" /> قيّم التجربة
                        </button>
                     ) : (
                        <div className="flex -space-x-3 rtl:space-x-reverse">
                           {o.products.slice(0, 3).map((item, i) => (
                              <img key={i} src={item.product.image} className="w-10 h-10 rounded-full border-2 border-white object-cover shadow-sm shrink-0" />
                           ))}
                        </div>
                     )}
                  </div>
               </div>
             ))}
          </div>
        ) : (
          <div className="animate-fade-in-up">
            <div className="bg-white rounded-[3rem] p-8 shadow-sm border border-slate-50 text-center overflow-hidden">
               <div className="relative inline-block mb-8">
