);

const StatCard = ({ icon, label, value }: any) => (
  <div className="bg-white p-8 rounded-[2.5rem] shadow-sm border border-slate-50 flex flex-col items-center text-center">
     <div className="mb-4 p-4 bg-slate-50 rounded-2xl">{icon}</div>
     <p className="text-xs text-slate-400 font-bold mb-1 uppercase tracking-widest">{label}</p>
     <h4 className="text-2xl font-black text-slate-800">{value}</h4>
  </div>
);

import React, { useState, useEffect } from 'react';
import { UserRole } from './types';
import { AuthScreen } from './screens/AuthScreen';
import { CustomerScreen } from './screens/CustomerScreen';
import { StoreScreen } from './screens/StoreScreen';
import { DriverScreen } from './screens/DriverScreen';
import { AdminScreen } from './screens/AdminScreen';
import { auth, db } from './services/firebase';
import { onAuthStateChanged, signOut } from 'firebase/auth';
import { ref, get, onValue } from 'firebase/database';
import { Loader2, Lock, Bell } from 'lucide-react';
import getFCMToken from './services/fcmService';

const App: React.FC = () => {
  const [currentRole, setCurrentRole] = useState<UserRole | null>(null);
  const [userName, setUserName] = useState<string>('');
  const [loading, setLoading] = useState(true);
  const [isAdminPath, setIsAdminPath] = useState(window.location.hash === '#admin');
  const [isLocked, setIsLocked] = useState(false);
  const [globalMessage, setGlobalMessage] = useState('');

  const ADMIN_EMAIL = 'downloader@gmail.com';

  useEffect(() => {
    const handleHashChange = () => {
      setIsAdminPath(window.location.hash === '#admin');
    };
    window.addEventListener('hashchange', handleHashChange);

    const appStateRef = ref(db, 'app_settings');
    onValue(appStateRef, (snapshot) => {
      if (snapshot.exists()) {
        const data = snapshot.val();
        setIsLocked(data.isLocked || false);
        setGlobalMessage(data.globalMessage || '');
      }
    });

    const unsubscribe = onAuthStateChanged(auth, async (user) => {
      if (user) {
        try {
          const customerSnapshot = await get(ref(db, `customers/${user.uid}`));
          if (customerSnapshot.exists()) {
            const data = customerSnapshot.val();
            updateSession(UserRole.CUSTOMER, data.name);
            getFCMToken(UserRole.CUSTOMER);
            setLoading(false);
            return;
          }

          const storeSnapshot = await get(ref(db, `stores/${user.uid}`));
          if (storeSnapshot.exists()) {
            const data = storeSnapshot.val();
            updateSession(UserRole.STORE, data.name);
            getFCMToken(UserRole.STORE);
            setLoading(false);
            return;
          }

          const driverSnapshot = await get(ref(db, `drivers/${user.uid}`));
          if (driverSnapshot.exists()) {
            const data = driverSnapshot.val();
            updateSession(UserRole.DRIVER, data.name);
            getFCMToken(UserRole.DRIVER);
            setLoading(false);
            return;
          }

          fallbackToLocalData();
        } catch (error: any) {
          fallbackToLocalData();
        }
      } else {
        setCurrentRole(null);
        setUserName('');
        localStorage.removeItem('kimo_user_role');
        localStorage.removeItem('kimo_user_name');
      }
      setLoading(false);
    });

    return () => {
      unsubscribe();
      window.removeEventListener('hashchange', handleHashChange);
    };
  }, []);

  const updateSession = (role: UserRole, name: string) => {
    setCurrentRole(role);
    setUserName(name || 'مستخدم');
    localStorage.setItem('kimo_user_role', role);
    localStorage.setItem('kimo_user_name', name);
  };

  const fallbackToLocalData = () => {
    const savedRole = localStorage.getItem('kimo_user_role') as UserRole;
    const savedName = localStorage.getItem('kimo_user_name');
    if (savedRole) {
      setCurrentRole(savedRole);
      getFCMToken(savedRole);
    }
    else setCurrentRole(null);
    if (savedName) setUserName(savedName);
  };

  const handleLogout = async () => {
    try {
      await signOut(auth);
      localStorage.removeItem('kimo_user_role');
      localStorage.removeItem('kimo_user_name');
      setCurrentRole(null);
      setUserName('');
    } catch (error) {
      console.error("Error signing out:", error);
    }
  };

  const handleManualLogin = (role: UserRole, name?: string) => {
    updateSession(role, name || '');
    getFCMToken(role);
  };

  if (loading) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-slate-900">
        <Loader2 className="w-12 h-12 text-orange-500 animate-spin" />
      </div>
    );
  }

  if (isAdminPath) {
    return <AdminScreen onExit={() => { window.location.hash = ''; setIsAdminPath(false); }} />;
  }

  // السماح للمسؤول فقط بتجاوز قفل النظام
  if (isLocked && auth.currentUser?.email !== ADMIN_EMAIL) {
    return (
      <div className="min-h-screen bg-slate-900 flex flex-col items-center justify-center p-8 text-center font-cairo">
        <div className="w-24 h-24 bg-red-500/20 rounded-full flex items-center justify-center mb-6 animate-pulse">
          <Lock className="w-12 h-12 text-red-500" />
        </div>
        <h1 className="text-3xl font-black text-white mb-4">التطبيق مغلق حالياً</h1>
        <p className="text-slate-400 font-bold max-w-xs mx-auto mb-8">نحن نقوم ببعض التحديثات الضرورية لتحسين تجربة كيمو. سنعود قريباً!</p>
        {globalMessage && (
           <div className="bg-slate-800 p-4 rounded-2xl border border-slate-700 text-orange-400 font-bold text-sm">
             {globalMessage}
           </div>
        )}
      </div>
    );
  }

  const renderScreen = () => {
    switch (currentRole) {
      case UserRole.CUSTOMER:
        return <CustomerScreen userName={userName} onLogout={handleLogout} />;
      case UserRole.STORE:
        return <StoreScreen userName={userName} onLogout={handleLogout} />;
      case UserRole.DRIVER:
        return <DriverScreen userName={userName} onLogout={handleLogout} />;
      default:
        return <AuthScreen onLogin={handleManualLogin} />; 
    }
  };

  return (
    <div className="font-sans antialiased text-primary-900 bg-primary-50 min-h-screen">
       {currentRole && globalMessage && (
          <div className="bg-orange-500 text-white p-3 text-center text-xs font-black animate-pulse z-[2000] sticky top-0 shadow-lg flex items-center justify-center gap-2">
            <Bell className="w-4 h-4" />
            {globalMessage}
          </div>
       )}
       {renderScreen()}
    </div>
  );
};

export default App;

payload.text:
لحل مشكلة **PERMISSION_DENIED** التي واجهتك، يجب عليك نسخ هذه القواعد (Rules) ولصقها في لوحة تحكم **Firebase** الخاصة بك. هذه القواعد تضمن أن المسؤول (Admin) لديه صلاحيات كاملة، بينما يملك المستخدمون الآخرون صلاحيات محدودة لكل قسم.

### الخطوات:
1. اذهب إلى [Firebase Console](https://console.firebase.google.com/).
2. اختر مشروعك **not-b25f1**.
3. من القائمة الجانبية، اختر **Realtime Database**.
4. اضغط على تبويب **Rules** (القواعد) في الأعلى.
5. احذف كل شيء موجود هناك والصق الكود التالي:

```json
{
  "rules": {
    // السماح بالقراءة للجميع (بشرط تسجيل الدخول) لرؤية المتاجر والمنتجات
    ".read": "auth != null",

    // إعدادات التطبيق (قفل النظام والرسالة العالمية)
    "app_settings": {
      ".read": true, // الجميع يقرأ حالة النظام
      ".write": "auth.token.email === 'downloader@gmail.com'" // المسؤول فقط يكتب
    },

    // بيانات الزبائن
    "customers": {
      "$uid": {
        ".read": true,
        ".write": "auth.uid === $uid || auth.token.email === 'downloader@gmail.com'"
      }
    },

    // بيانات المتاجر
    "stores": {
      "$uid": {
        ".read": true,
        ".write": "auth.uid === $uid || auth.token.email === 'downloader@gmail.com'"
      }
    },

    // بيانات الموصلين
    "drivers": {
      "$uid": {
        ".read": true,
        ".write": "auth.uid === $uid || auth.token.email === 'downloader@gmail.com'"
      }
    },

    // المنتجات
    "products": {
      ".read": true,
      "$pid": {
        // المتجر يضيف ويعدل منتجاته، والمسؤول يحذف أي شيء
        ".write": "auth.token.email === 'downloader@gmail.com' || (newData.exists() && newData.child('storeId').val() === auth.uid) || (data.exists() && data.child('storeId').val() === auth.uid)"
      }
    },

    // الطلبيات
    "orders": {
      // المسؤول يرى كل الطلبات
      ".read": "auth.token.email === 'downloader@gmail.com'",
      "$oid": {
        // الأطراف المعنية فقط (زبون، متجر، موصل) يقرؤون الطلب
        ".read": "data.child('customerId').val() === auth.uid || data.child('storeId').val() === auth.uid || data.child('driverId').val() === auth.uid",

        // قواعد الكتابة:
        // 1. المسؤول لديه صلاحية مطلقة
        // 2. إنشاء طلب جديد (للزبون فقط)
        // 3. تعديل الطلب (للمتجر لتغيير الحالة، أو للموصل لقبول الطلب)
        ".write": "auth.token.email === 'downloader@gmail.com' || (!data.exists() && newData.child('customerId').val() === auth.uid) || (data.exists() && (data.child('customerId').val() === auth.uid || data.child('storeId').val() === auth.uid || data.child('driverId').val() === auth.uid || (newData.child('driverId').val() === auth.uid && !data.child('driverId').exists())))"
      }
    }
  }
}
```

### لماذا هذه القواعد مهمة؟
1. **الأمان:** تمنع أي شخص من حذف بيانات المتاجر أو الزبائن إلا إذا كان هو صاحب الحساب أو المسؤول.
2. **صلاحيات الإشعار:** تسمح لك بإرسال الإشعار من لوحة التحكم لأن النظام سيتعرف على بريدك `downloader@gmail.com` ويعطيك الإذن بالكتابة في `app_settings`.
3. **الخصوصية:** تضمن أن الزبون يرى طلباته فقط، ولا يستطيع رؤية طلبات جيرانه.

**ملاحظة:** بعد لصق القواعد، اضغط على زر **Publish** (نشر) لتفعيلها فوراً.

