interface MapVisualizerProps {
  userLocation?: Coordinates;
  storeLocation?: Coordinates;
  customerLocation?: Coordinates;
  driverLocation?: Coordinates;
  height?: string;
  zoom?: number;
}

const createCustomIcon = (iconHtml: string, colorClass: string, size = 32) => {
  return L.divIcon({
    html: `<div class="relative flex items-center justify-center p-1 rounded-full ${colorClass} shadow-md border-2 border-white/80"><div class="text-white w-4 h-4">${iconHtml}</div></div>`,
    className: 'bg-transparent flex items-center justify-center',
    iconSize: [size, size],
    iconAnchor: [size/2, size],
    popupAnchor: [0, -size]
  });
};

const userIcon = createCustomIcon('<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M19 21v-2a4 4 0 0 0-4-4H9a4 4 0 0 0-4 4v2"/><circle cx="12" cy="7" r="4"/></svg>', 'bg-blue-600', 32);
const storeIcon = createCustomIcon('<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="m2 7 4.41-4.41A2 2 0 0 1 7.41 2h9.18a2 2 0 0 1 1.4.59L22 7"/><path d="M4 12v8a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2v-8"/><path d="M15 22v-4a2 2 0 0 0-2-2h-2a2 2 0 0 0-2 2v4"/><path d="M2 7h20"/><path d="M12 12v8"/></svg>', 'bg-orange-600', 36);
const customerIcon = createCustomIcon('<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M12 22s-8-4.5-8-11.8A8 8 0 0 1 12 2a8 8 0 0 1 8 8.2c0 7.3-8 11.8-8 11.8z"/><circle cx="12" cy="10" r="3"/></svg>', 'bg-brand-500', 34);
const driverIcon = createCustomIcon('<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="18.5" cy="17.5" r="2.5"/><circle cx="5.5" cy="17.5" r="2.5"/><circle cx="15" cy="5" r="1"/><path d="M12 9H5.5L3 13.35c-.4.7-.1 1.65.65 2.05L7 17.5"/><path d="M17 17.5l-1.5-3l1.5-4.5L15 5h-2.5"/></svg>', 'bg-slate-900', 38);

const RecenterMap = ({ coords }: { coords: Coordinates }) => {
  const map = useMap();
  useEffect(() => {
    if (coords && coords.lat && coords.lng) {
      map.setView([coords.lat, coords.lng], map.getZoom());
    }
  }, [coords, map]);
  return null;
};

export const MapVisualizer: React.FC<MapVisualizerProps> = ({ 
  userLocation, 
  storeLocation, 
  customerLocation, 
  driverLocation,
  height = 'h-64',
  zoom = 14
}) => {
  const defaultCenter = driverLocation || userLocation || storeLocation || customerLocation || BIR_EL_ATER_CENTER;

  return (
    <div className={`relative w-full ${height} overflow-hidden z-0`}>
      <MapContainer 
        center={[defaultCenter.lat, defaultCenter.lng]} 
        zoom={zoom} 
        scrollWheelZoom={false} 
        className="h-full w-full"
        attributionControl={false}
      >
        <RecenterMap coords={defaultCenter} />
        <TileLayer url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png" />

        {userLocation && userLocation.lat && (
          <Marker position={[userLocation.lat, userLocation.lng]} icon={userIcon}>
            <Popup>موقعك الحالي</Popup>
          </Marker>
        )}

        {storeLocation && storeLocation.lat && (
          <Marker position={[storeLocation.lat, storeLocation.lng]} icon={storeIcon}>
            <Popup>موقع المتجر</Popup>
          </Marker>
        )}

        {customerLocation && customerLocation.lat && (
          <Marker position={[customerLocation.lat, customerLocation.lng]} icon={customerIcon}>
            <Popup>موقع التوصيل</Popup>
          </Marker>
        )}

        {driverLocation && driverLocation.lat && (
          <Marker position={[driverLocation.lat, driverLocation.lng]} icon={driverIcon}>
            <Popup>موقع السائق الآن</Popup>
          </Marker>
        )}
      </MapContainer>

      <div className="absolute bottom-2 left-2 bg-black/50 backdrop-blur-md text-white p-1 px-3 rounded-full text-[8px] font-bold z-[400] pointer-events-none">
        خريطة كيمو الحية
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Category, Product, StoreProfile, OrderStatus, Order, Coordinates } from '../types';
import { formatCurrency } from '../utils/helpers';
import { db, auth } from '../services/firebase';
import { ref, onValue, push, set, update, off } from 'firebase/database';
import { 
  Search, Plus, Minus, ShoppingCart, MapPin, Loader2, Home, User, 
  Camera, LogOut, ClipboardList, Trash2, Star, ShieldCheck, 
  LayoutGrid, Save, RefreshCw, Phone, Sparkles, Navigation, X, Bot, Send,
  ChevronLeft, ShoppingBag, Heart, Filter, CheckCircle2, Layout, Bike, PhoneCall,
  Clock, Map as MapIcon, Timer, Truck
} from 'lucide-react';
import { MapVisualizer } from '../components/MapVisualizer';

export const CustomerScreen: React.FC<{onLogout: () => void, userName: string}> = ({ onLogout, userName }) => {
  const [activeTab, setActiveTab] = useState<'HOME' | 'CATEGORIES' | 'ORDERS' | 'PROFILE'>('HOME');
  const [activeStore, setActiveStore] = useState<StoreProfile | null>(null);
  const [cart, setCart] = useState<{product: Product; quantity: number}[]>([]);
  const [isOrdering, setIsOrdering] = useState(false);
  const [stores, setStores] = useState<StoreProfile[]>([]);
  const [allProducts, setAllProducts] = useState<Product[]>([]);
  const [myOrders, setMyOrders] = useState<Order[]>([]);
  const [loading, setLoading] = useState(true);
  const [searchQuery, setSearchQuery] = useState('');
  const [selectedCategory, setSelectedCategory] = useState<string | null>(null);

  // تتبع الطلب
  const [trackingOrder, setTrackingOrder] = useState<Order | null>(null);
  const [driverLiveCoords, setDriverLiveCoords] = useState<Coordinates | null>(null);

  const [isEditingProfile, setIsEditingProfile] = useState(false);
  const [profileData, setProfileData] = useState({ name: '', phone: '', coordinates: null as any });
  const [isUpdating, setIsUpdating] = useState(false);
  const [isLocating, setIsLocating] = useState(false);

  const user = auth.currentUser;

  useEffect(() => {
    if (!user) return;

    onValue(ref(db, 'stores'), (snap) => {
      const data = snap.val();
      if (data) setStores(Object.keys(data).map(k => ({ id: k, ...data[k] })));
      setLoading(false);
    });

    onValue(ref(db, 'products'), (snap) => {
      const data = snap.val();
      if (data) setAllProducts(Object.keys(data).map(k => ({ id: k, ...data[k] })));
    });

    onValue(ref(db, 'orders'), (snap) => {
      const data = snap.val();
      const list: Order[] = [];
      if (data) Object.keys(data).forEach(k => { if (data[k].customerId === user.uid) list.push({ id: k, ...data[k] }); });
      setMyOrders(list.sort((a, b) => b.timestamp - a.timestamp));

      // تحديث بيانات التتبع إذا كانت الشاشة مفتوحة
      if (trackingOrder) {
        const updated = list.find(o => o.id === trackingOrder.id);
        if (updated) setTrackingOrder(updated);
      }
    });

    onValue(ref(db, `customers/${user.uid}`), (snap) => {
      if (snap.exists()) {
        const data = snap.val();
        setProfileData({ 
          name: data.name || '', 
          phone: data.phone || '',
          coordinates: data.coordinates || null
        });
      }
    });
  }, [user]);

  // مراقبة موقع السائق عند التتبع
  useEffect(() => {
    if (trackingOrder?.driverId) {
      const driverPosRef = ref(db, `drivers/${trackingOrder.driverId}/coordinates`);
      onValue(driverPosRef, (snap) => {
        if (snap.exists()) {
          setDriverLiveCoords(snap.val());
        }
      });
      return () => off(driverPosRef);
    } else {
      setDriverLiveCoords(null);
    }
  }, [trackingOrder]);

  const addToCart = (p: Product) => {
    setCart(prev => {
      const ex = prev.find(i => i.product.id === p.id);
      if (ex) return prev.map(i => i.product.id === p.id ? {...i, quantity: i.quantity + 1} : i);
      return [...prev, { product: p, quantity: 1 }];
    });
  };

  const removeFromCart = (id: string) => {
    setCart(prev => prev.map(i => i.product.id === id ? {...i, quantity: i.quantity - 1} : i).filter(i => i.quantity > 0));
  };

  const grandTotal = cart.reduce((s, i) => s + (i.product.price * i.quantity), 0) + 200;

  const handleCheckout = async () => {
    if (cart.length === 0) return;
    setIsOrdering(true);

    try {
      const firstProductStoreId = cart[0].product.storeId;
      const store = stores.find(s => s.id === firstProductStoreId);

      const orderData = {
        customerId: user!.uid, 
        customerName: profileData.name || userName,
        storeId: firstProductStoreId, 
        storeName: store?.name || "متجر كيمو",
        products: cart, 
        totalPrice: grandTotal, 
        deliveryFee: 200,
        status: OrderStatus.PENDING, 
        timestamp: Date.now(),
        address: "بئر العاتر",
        customerPhone: profileData.phone || '',
        coordinates: profileData.coordinates || { lat: 34.7495, lng: 8.0617 },
        storeCoordinates: store?.coordinates || { lat: 34.7495, lng: 8.0617 }
      };

      const newOrderRef = push(ref(db, 'orders'));
      await set(newOrderRef, orderData);

      alert("تم إرسال طلبك بنجاح! سيتم التواصل معك قريباً.");
      setCart([]); 
      setActiveTab('ORDERS');
    } catch (error) {
      console.error("Checkout Error:", error);
      alert("حدث خطأ أثناء إتمام الطلب، يرجى المحاولة مرة أخرى.");
    } finally {
      setIsOrdering(false);
    }
  };

  const handleUpdateProfile = async () => {
    if (!user) return;
    setIsUpdating(true);
    await update(ref(db, `customers/${user.uid}`), { name: profileData.name, phone: profileData.phone });
    setIsEditingProfile(false);
    setIsUpdating(false);
  };

  const handleUpdateLocation = () => {
    setIsLocating(true);
    navigator.geolocation.getCurrentPosition((pos) => {
      if (user) {
        update(ref(db, `customers/${user.uid}`), {
          coordinates: { lat: pos.coords.latitude, lng: pos.coords.longitude }
        });
        setProfileData(prev => ({...prev, coordinates: { lat: pos.coords.latitude, lng: pos.coords.longitude }}));
        alert("تم تحديد موقعك بنجاح ✓");
      }
      setIsLocating(false);
    }, () => {
      alert("يرجى تفعيل الـ GPS في متصفحك أولاً.");
      setIsLocating(false);
    });
  };

  if (loading) return <div className="h-screen flex items-center justify-center bg-white"><Loader2 className="animate-spin text-orange-500 w-12 h-12" /></div>;

  return (
    <div className="bg-[#F4F4F4] min-h-screen pb-32 font-cairo text-right" dir="rtl">

      {/* 0. Tracking Overlay */}
      {trackingOrder && (
        <div className="fixed inset-0 z-[1000] bg-white animate-fade-in flex flex-col">
          <div className="p-4 flex items-center justify-between border-b border-slate-100 bg-white shadow-sm">
            <button onClick={() => setTrackingOrder(null)} className="p-2 bg-slate-100 rounded-full active:scale-90"><X size={20}/></button>
            <div className="text-center">
               <h3 className="font-black text-slate-800 text-sm">تتبع طلبي المباشر</h3>
               <p className="text-[9px] font-bold text-slate-400">رقم الطلب: #{trackingOrder.id?.slice(-5).toUpperCase()}</p>
            </div>
            <div className="w-10"></div>
          </div>

          <div className="flex-1 relative">
            <MapVisualizer 
              height="h-full" 
              zoom={15}
              customerLocation={trackingOrder.coordinates}
              storeLocation={trackingOrder.storeCoordinates}
              driverLocation={driverLiveCoords || undefined}
            />
          </div>

          <div className="bg-white p-6 rounded-t-[3rem] shadow-[0_-10px_40px_rgba(0,0,0,0.15)] -mt-10 z-[1001] relative border-t border-slate-50">
            <div className="w-12 h-1.5 bg-slate-100 rounded-full mx-auto mb-6"></div>

            {/* Status Stepper */}
            <div className="flex items-center justify-between mb-8 px-2">
               <StatusStep label="انتظار" active={true} done={trackingOrder.status !== OrderStatus.PENDING} />
               <div className={`flex-1 h-0.5 mx-2 rounded-full ${trackingOrder.status !== OrderStatus.PENDING ? 'bg-orange-500' : 'bg-slate-100'}`}></div>
               <StatusStep label="تجهيز" active={trackingOrder.status === OrderStatus.ACCEPTED_BY_STORE || trackingOrder.status === OrderStatus.ACCEPTED_BY_DRIVER || trackingOrder.status === OrderStatus.DELIVERED} done={trackingOrder.status === OrderStatus.ACCEPTED_BY_DRIVER || trackingOrder.status === OrderStatus.DELIVERED} />
               <div className={`flex-1 h-0.5 mx-2 rounded-full ${trackingOrder.status === OrderStatus.ACCEPTED_BY_DRIVER || trackingOrder.status === OrderStatus.DELIVERED ? 'bg-orange-500' : 'bg-slate-100'}`}></div>
               <StatusStep label="طريق" active={trackingOrder.status === OrderStatus.ACCEPTED_BY_DRIVER || trackingOrder.status === OrderStatus.DELIVERED} done={trackingOrder.status === OrderStatus.DELIVERED} />
               <div className={`flex-1 h-0.5 mx-2 rounded-full ${trackingOrder.status === OrderStatus.DELIVERED ? 'bg-orange-500' : 'bg-slate-100'}`}></div>
               <StatusStep label="تسليم" active={trackingOrder.status === OrderStatus.DELIVERED} done={trackingOrder.status === OrderStatus.DELIVERED} />
            </div>

            <div className="flex items-center gap-4 mb-6 bg-slate-50 p-4 rounded-[2rem]">
              <div className="w-14 h-14 brand-gradient rounded-2xl flex items-center justify-center text-white shadow-lg">
                <Bike size={28} />
              </div>
              <div className="flex-1">
                <h4 className="font-black text-slate-800 text-base">{trackingOrder.driverName || 'جاري البحث عن موصل...'}</h4>
                <p className="text-[10px] text-slate-400 font-bold">موصل كيمو السريع</p>
              </div>
              {trackingOrder.driverPhone && (
                <a href={`tel:${trackingOrder.driverPhone}`} className="w-12 h-12 bg-green-500 rounded-2xl flex items-center justify-center text-white shadow-lg active:scale-90 transition-all">
                  <Phone size={20} />
                </a>
              )}
            </div>

            <div className="flex gap-3">
               <button className="flex-1 bg-slate-900 text-white py-4 rounded-2xl font-black text-xs flex items-center justify-center gap-2 active:scale-95 transition-all">
                  <Bot size={16} /> مساعدة كيمو
               </button>
               <button onClick={() => setTrackingOrder(null)} className="px-6 bg-slate-100 text-slate-400 py-4 rounded-2xl font-black text-xs">إغلاق</button>
            </div>
          </div>
        </div>
      )}

      {/* 1. Promo Header */}
      {activeTab === 'HOME' && !searchQuery && !selectedCategory && (
        <div className="bg-gradient-to-b from-[#E62E04] to-[#FF6000] pt-12 pb-8 px-6 text-center text-white relative overflow-hidden">
           <div className="absolute -right-10 -top-10 w-40 h-40 bg-white/10 rounded-full blur-3xl"></div>
           <h1 className="text-4xl font-black mb-1 tracking-tighter uppercase italic">KIMO HOME</h1>
           <p className="text-sm font-bold opacity-90">Refresh your home • بئر العاتر</p>
           <p className="text-[8px] mt-4 opacity-60">*السعر الفعلي قد يختلف حسب التوقيت والمنطقة.</p>
        </div>
      )}

      {/* 2. Main Sticky Header */}
      <div className="bg-white sticky top-0 z-[100] px-4 pt-4 pb-2 shadow-sm">
        <div className="flex items-center gap-3 mb-4">
          <div className="relative flex-1">
            <input 
              type="text" 
              placeholder="ابحث في كيمو..." 
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              className="w-full bg-[#F0F0F0] border-none rounded-full py-2.5 pr-10 pl-14 text-sm font-bold outline-none focus:ring-2 focus:ring-orange-500/20"
            />
            <Search className="absolute right-3.5 top-3 w-4.5 h-4.5 text-slate-400" />
            <div className="absolute left-1.5 top-1.5 flex items-center gap-1.5">
               <Camera className="w-5 h-5 text-slate-400 p-1" />
               <button className="bg-black text-white p-1.5 rounded-full shadow-lg"><Search className="w-3.5 h-3.5" /></button>
            </div>
          </div>
          <div className="relative cursor-pointer" onClick={() => setActiveTab('HOME')}>
            <ShoppingCart className="w-7 h-7 text-slate-700" />
            {cart.length > 0 && <span className="absolute -top-1 -right-1 bg-[#FF6000] text-white text-[9px] font-black w-4.5 h-4.5 rounded-full flex items-center justify-center border-2 border-white">{cart.length}</span>}
          </div>
        </div>

        <div className="flex gap-6 overflow-x-auto no-scrollbar pb-1 px-2">
          {['الكل', ...Object.values(Category)].map((cat) => (
            <button 
              key={cat}
              onClick={() => { setSelectedCategory(cat === 'الكل' ? null : cat); setActiveTab('HOME'); }}
              className={`whitespace-nowrap text-sm font-bold pb-2 transition-all relative ${(!selectedCategory && cat === 'الكل') || selectedCategory === cat ? 'text-[#FF6000]' : 'text-slate-500'}`}
            >
              {cat}
              {((!selectedCategory && cat === 'الكل') || selectedCategory === cat) && <div className="absolute bottom-0 left-0 right-0 h-0.5 bg-[#FF6000] rounded-full"></div>}
            </button>
          ))}
        </div>
      </div>

      <main className="p-3 max-w-lg mx-auto">
        {activeTab === 'HOME' && (
          <div className="animate-fade-in-up">
            {!selectedCategory && !searchQuery && (
              <div className="flex gap-4 overflow-x-auto no-scrollbar py-6 mb-2">
                {stores.slice(0, 6).map((store, i) => (
                  <div key={i} onClick={() => { setActiveStore(store); setSelectedCategory(store.category); }} className="flex flex-col items-center min-w-[75px] gap-2 cursor-pointer">
                    <div className="w-16 h-16 bg-white rounded-full flex items-center justify-center shadow-md border border-slate-50 overflow-hidden p-0.5 hover:scale-105 transition-transform">
                      <img src={store.image} className="w-full h-full object-cover rounded-full" />
                    </div>
                    <span className="text-[9px] font-black text-slate-600 truncate w-16 text-center">{store.name}</span>
                  </div>
                ))}
              </div>
            )}

            <div className="grid grid-cols-2 gap-3">
              {allProducts
                .filter(p => !selectedCategory || p.category === selectedCategory)
                .filter(p => p.name.toLowerCase().includes(searchQuery.toLowerCase()))
                .map((p) => {
                  const cartItem = cart.find(i => i.product.id === p.id);
                  return (
                    <div key={p.id} className="bg-white rounded-xl overflow-hidden shadow-sm flex flex-col relative group border border-slate-50">
                      <div className="relative h-48 overflow-hidden bg-slate-50">
                        <img src={p.image} className="w-full h-full object-cover transition-transform duration-500 group-hover:scale-110" />
                        <button className="absolute top-2 left-2 bg-white/90 backdrop-blur-md p-1.5 rounded-full shadow-sm"><Heart className="w-4 h-4 text-slate-400" /></button>
                      </div>

                      <div className="p-3 flex-1 flex flex-col">
                        <h4 className="text-[11px] font-bold text-slate-800 line-clamp-2 mb-1 h-8 leading-tight">{p.name}</h4>
                        <div className="flex items-center gap-1 mb-1.5">
                          <div className="flex text-yellow-400">
                             {[1,2,3,4,5].map(s => <Star key={s} size={9} fill="currentColor" />)}
                          </div>
                          <span className="text-[9px] text-slate-400 font-bold">(15,230)</span>
                        </div>
                        <div className="mt-auto">
                          <p className="text-[9px] text-slate-400 font-black mb-1.5 flex items-center gap-1"><ShieldCheck className="w-3 h-3 text-blue-500" /> 10K+ sold</p>
                          <div className="flex justify-between items-center">
                            <span className="text-[#E62E04] font-black text-base">{formatCurrency(p.price)}</span>
                            <button 
                              onClick={() => addToCart(p)}
                              className="w-9 h-9 rounded-full border border-slate-200 flex items-center justify-center text-slate-700 hover:bg-[#FF6000] hover:text-white hover:border-transparent transition-all shadow-sm active:scale-90"
                            >
                              <Plus className="w-4.5 h-4.5" />
                            </button>
                          </div>
                        </div>
                      </div>
                      {cartItem && (
                        <div className="absolute top-2 right-2 bg-[#FF6000] text-white text-[10px] font-black w-6 h-6 rounded-full flex items-center justify-center shadow-lg animate-scale-up border-2 border-white">
                          {cartItem.quantity}
                        </div>
                      )}
                    </div>
                  );
                })}
            </div>
          </div>
        )}

        {activeTab === 'CATEGORIES' && (
          <div className="animate-fade-in-up py-4 px-2">
            <h2 className="text-2xl font-black text-slate-900 mb-6">تصفح بـ الفئة</h2>
            <div className="grid grid-cols-2 gap-4">
               {Object.values(Category).map((cat, i) => (
                 <button 
                   key={i} 
                   onClick={() => { setSelectedCategory(cat); setActiveTab('HOME'); }}
                   className="bg-white p-6 rounded-[2rem] shadow-sm border border-slate-100 flex flex-col items-center gap-4 active:scale-95 transition-all"
                 >
                    <div className="w-16 h-16 brand-gradient rounded-full flex items-center justify-center text-white shadow-lg">
                       <ShoppingBag />
                    </div>
                    <span className="font-black text-slate-700">{cat}</span>
                 </button>
               ))}
            </div>
          </div>
        )}

        {activeTab === 'ORDERS' && (
           <div className="space-y-4 animate-fade-in-up">
              <h2 className="text-2xl font-black text-slate-900 mb-4 px-2">سجل طلباتي</h2>
              {myOrders.length === 0 ? (
                 <div className="bg-white rounded-[2.5rem] p-16 text-center text-slate-300 border border-dashed border-slate-200">
                   <ClipboardList className="w-16 h-16 mx-auto mb-4 opacity-10" />
                   <p className="font-black text-sm text-slate-400">لا توجد طلبات سابقة لعرضها</p>
                 </div>
              ) : (
                myOrders.map(o => (
                  <div key={o.id} className="bg-white p-5 rounded-[2.5rem] shadow-sm border border-slate-100 relative overflow-hidden group">
                    <div className="flex justify-between mb-4">
                       <div className="flex items-center gap-3">
                          <div className="w-10 h-10 bg-slate-100 rounded-xl flex items-center justify-center text-slate-500">
                             <ShoppingBag size={20} />
                          </div>
                          <div>
                            <span className="text-sm font-black text-slate-800 block">{o.storeName}</span>
                            <p className="text-[10px] text-slate-400 font-bold">{new Date(o.timestamp).toLocaleString('ar-DZ')}</p>
                          </div>
                       </div>
                       <span className={`text-[9px] h-fit font-black px-4 py-1.5 rounded-full ${o.status === OrderStatus.DELIVERED ? 'bg-green-100 text-green-600' : 'bg-orange-100 text-orange-600'}`}>
                          {o.status}
                       </span>
                    </div>

                    <div className="flex items-center justify-between py-4 border-t border-slate-50">
                       <div className="flex flex-col">
                          <span className="text-[9px] text-slate-400 font-black uppercase">إجمالي الفاتورة</span>
                          <span className="text-xl font-black text-slate-900 leading-none mt-1">{formatCurrency(o.totalPrice)}</span>
                       </div>

                       <div className="flex gap-2">
                          <button onClick={() => setTrackingOrder(o)} className="bg-orange-500 text-white px-6 py-3 rounded-2xl font-black text-[11px] flex items-center gap-2 shadow-lg shadow-orange-500/20 active:scale-95 transition-all">
                             <MapIcon size={14} /> تتبع الحالة
                          </button>
                          <button className="p-3 bg-slate-50 text-slate-400 rounded-2xl active:scale-95 transition-all"><ChevronLeft size={16} /></button>
                       </div>
                    </div>

                    {o.status === OrderStatus.ACCEPTED_BY_DRIVER && (
                      <div className="bg-green-50 p-3 mt-1 rounded-2xl flex items-center gap-2">
                         <div className="w-2 h-2 bg-green-500 rounded-full animate-pulse"></div>
                         <p className="text-[10px] font-black text-green-600">الموصل في الطريق إليك الآن</p>
                      </div>
                    )}
                  </div>
                ))
              )}
           </div>
        )}

        {activeTab === 'PROFILE' && (
           <div className="animate-fade-in-up">
              <div className="bg-white p-10 rounded-[3rem] shadow-sm text-center border border-slate-50">
                 <div className="w-28 h-28 bg-slate-50 rounded-full mx-auto mb-6 border-4 border-white shadow-xl overflow-hidden relative group">
                    <img src={`https://api.dicebear.com/7.x/avataaars/svg?seed=${userName}`} className="w-full h-full" />
                    <div className="absolute inset-0 bg-black/20 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center cursor-pointer">
                       <Camera className="text-white w-6 h-6" />
                    </div>
                 </div>

                 {!isEditingProfile ? (
                   <>
                     <h3 className="text-2xl font-black text-slate-800 mb-1">{profileData.name || userName}</h3>
                     <p className="text-xs text-slate-400 font-bold mb-8">{profileData.phone || 'لم يتم إضافة هاتف'}</p>
                     <div className="grid grid-cols-2 gap-4 mb-8">
                        <div className="bg-slate-50 p-4 rounded-2xl">
                           <p className="text-[10px] text-slate-400 font-black mb-1 uppercase">الطلبات</p>
                           <p className="text-lg font-black text-slate-800">{myOrders.length}</p>
                        </div>
                        <div className="bg-slate-50 p-4 rounded-2xl">
                           <p className="text-[10px] text-slate-400 font-black mb-1 uppercase">النقاط</p>
                           <p className="text-lg font-black text-orange-500">240</p>
                        </div>
                     </div>
                     <div className="space-y-3">
                        <button onClick={() => setIsEditingProfile(true)} className="w-full bg-[#F0F0F0] py-4 rounded-2xl font-black text-slate-700 text-sm flex items-center justify-center gap-2 active:scale-95 transition-all"><User size={18} /> تعديل الحساب</button>
                        <button onClick={onLogout} className="w-full bg-red-50 py-4 rounded-2xl font-black text-red-500 text-sm flex items-center justify-center gap-2 mt-6"><LogOut size={18} /> خروج من كيمو</button>
                     </div>
                   </>
                 ) : (
                    <div className="space-y-4 text-right">
                       <h4 className="text-lg font-black text-slate-800 mb-4">تعديل البيانات</h4>
                       <div className="space-y-1">
                          <label className="text-[10px] font-black text-slate-400 pr-2">الاسم الكامل</label>
                          <input type="text" value={profileData.name} onChange={e => setProfileData({...profileData, name: e.target.value})} className="w-full p-4 bg-slate-50 rounded-2xl font-bold outline-none border-2 border-transparent focus:border-orange-500 transition-all" />
                       </div>
                       <div className="space-y-1">
                          <label className="text-[10px] font-black text-slate-400 pr-2">رقم الهاتف</label>
                          <input type="tel" value={profileData.phone} onChange={e => setProfileData({...profileData, phone: e.target.value})} className="w-full p-4 bg-slate-50 rounded-2xl font-bold outline-none border-2 border-transparent focus:border-orange-500 transition-all" />
                       </div>
                       <button onClick={handleUpdateLocation} disabled={isLocating} className="w-full py-4 border-2 border-dashed border-orange-200 text-orange-600 rounded-2xl font-black text-xs flex items-center justify-center gap-2 mt-4">
                          {isLocating ? <Loader2 className="animate-spin" /> : <Navigation size={16} />}
                          تحديث موقع التوصيل الحالي
                       </button>
                       <div className="flex gap-3 mt-8">
                          <button onClick={handleUpdateProfile} disabled={isUpdating} className="flex-1 bg-black text-white py-4 rounded-2xl font-black text-sm shadow-xl active:scale-95 transition-all">حفظ البيانات</button>
                          <button onClick={() => setIsEditingProfile(false)} className="px-6 bg-slate-100 text-slate-400 py-4 rounded-2xl font-black text-sm">إلغاء</button>
                       </div>
                    </div>
                 )}
              </div>
           </div>
        )}
      </main>

      {cart.length > 0 && activeTab === 'HOME' && (
        <div className="fixed bottom-24 left-4 right-4 bg-white/95 backdrop-blur-xl rounded-[2.5rem] shadow-2xl p-3 z-[200] border border-white animate-slide-up flex items-center justify-between pl-6">
           <div className="flex items-center gap-4">
              <div className="w-14 h-14 bg-orange-100 rounded-2xl flex items-center justify-center text-[#FF6000] relative">
                 <ShoppingBag className="w-7 h-7" />
                 <span className="absolute -top-1 -right-1 bg-black text-white text-[10px] font-black w-6 h-6 rounded-full flex items-center justify-center border-2 border-white">{cart.length}</span>
              </div>
              <div>
                 <p className="text-[10px] font-black text-slate-400 uppercase">إجمالي السلة</p>
                 <p className="text-xl font-black text-[#FF6000] leading-none">{formatCurrency(grandTotal)}</p>
              </div>
           </div>
           <button 
             onClick={handleCheckout} 
             disabled={isOrdering}
             className="bg-[#FF6000] text-white px-10 py-4 rounded-2xl font-black text-sm shadow-xl shadow-orange-500/20 active:scale-95 transition-all flex items-center gap-2"
           >
             {isOrdering ? <Loader2 className="animate-spin" /> : <>إتمام الطلب <ChevronLeft size={18} /></>}
           </button>
        </div>
      )}

      <nav className="fixed bottom-0 left-0 right-0 bg-white border-t border-slate-100 h-20 flex justify-around items-center px-4 z-[500] shadow-[0_-5px_20px_rgba(0,0,0,0.03)]">
        <NavBtn act={activeTab === 'HOME'} onClick={() => { setActiveTab('HOME'); setSelectedCategory(null); }} icon={<Home />} label="الرئيسية" />
        <NavBtn act={activeTab === 'CATEGORIES'} onClick={() => setActiveTab('CATEGORIES')} icon={<LayoutGrid />} label="الأقسام" />
        <NavBtn act={activeTab === 'ORDERS'} onClick={() => setActiveTab('ORDERS')} icon={<ClipboardList />} label="طلباتي" />
        <NavBtn act={activeTab === 'PROFILE'} onClick={() => setActiveTab('PROFILE')} icon={<User />} label="حسابي" />
      </nav>

      <style>{`
        .no-scrollbar::-webkit-scrollbar { display: none; }
        .no-scrollbar { -ms-overflow-style: none; scrollbar-width: none; }
      `}</style>
    </div>
  );
};

const NavBtn = ({ act, onClick, icon, label }: any) => (
  <button onClick={onClick} className={`flex flex-col items-center gap-1.5 transition-all ${act ? 'text-[#FF6000]' : 'text-slate-400'}`}>
    <div className={`p-1 ${act ? 'scale-110' : 'scale-100'} transition-transform`}>
      {React.cloneElement(icon, { size: 22, strokeWidth: act ? 3 : 2 })}
    </div>
    <span className="text-[9px] font-black tracking-tighter">{label}</span>
  </button>
);

const StatusStep = ({ label, active, done }: { label: string; active: boolean; done: boolean }) => (
  <div className="flex flex-col items-center gap-1">
     <div className={`w-6 h-6 rounded-full flex items-center justify-center transition-all ${done ? 'bg-orange-500 text-white' : active ? 'bg-orange-100 text-orange-600 ring-2 ring-orange-500 ring-offset-2' : 'bg-slate-100 text-slate-300'}`}>
        {done ? <CheckCircle2 size={12} /> : active ? <div className="w-2 h-2 bg-orange-500 rounded-full animate-pulse"></div> : <Clock size={12} />}
     </div>
     <span className={`text-[8px] font-black uppercase ${active ? 'text-slate-800' : 'text-slate-300'}`}>{label}</span>
  </div>
);

import React, { useState, useRef, useEffect } from 'react';
import { Category, Product, Order, OrderStatus, StoreProfile } from '../types';
import { db, auth } from '../services/firebase';
import { ref, push, set, onValue, remove, update } from 'firebase/database';
import { 
  Package, Plus, Upload, Loader2, Trash2, ArrowLeft, 
  ClipboardList, CheckCircle, Camera, LogOut, User, 
  RefreshCw, Phone, Tag, Sparkles, Wand2, Save, MapPin, Navigation 
} from 'lucide-react';
import { formatCurrency } from '../utils/helpers';
import { generateProductDescription } from '../services/geminiService';

interface StoreScreenProps {
  onLogout: () => void;
  userName: string;
}

const uploadImage = async (file: File): Promise<string | null> => {
  const formData = new FormData();
  formData.append("file", file);
  formData.append("upload_preset", "makemm");
  const cloudName = 'dkqxgwjnr';
  try {
    const res = await fetch(`https://api.cloudinary.com/v1_1/${cloudName}/image/upload`, {
      method: "POST",
      body: formData,
    });
    const data = await res.json();
    return data.secure_url || null;
  } catch (error) { return null; }
};

export const StoreScreen: React.FC<StoreScreenProps> = ({ onLogout, userName }) => {
  const [activeTab, setActiveTab] = useState<'PRODUCTS' | 'ORDERS' | 'PROFILE'>('PRODUCTS');
  const [myProducts, setMyProducts] = useState<Product[]>([]);
  const [orders, setOrders] = useState<Order[]>([]);
  const [storeProfile, setStoreProfile] = useState<StoreProfile | null>(null);
  const [loading, setLoading] = useState(true);

  const [isAddingProduct, setIsAddingProduct] = useState(false);
  const [isUploading, setIsUploading] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const [isAiGenerating, setIsAiGenerating] = useState(false);

  // Profile Edit States
  const [isEditingProfile, setIsEditingProfile] = useState(false);
  const [editProfileData, setEditProfileData] = useState({ name: '', phone: '', image: '' });
  const [isUpdatingProfile, setIsUpdatingProfile] = useState(false);
  const [isLocating, setIsLocating] = useState(false);
  const [isUploadingProfileImage, setIsUploadingProfileImage] = useState(false);

  const [newProduct, setNewProduct] = useState<Partial<Product>>({
    name: '', description: '', price: 0, category: Category.FOOD, image: ''
  });

  const profileImageInputRef = useRef<HTMLInputElement>(null);
  const currentStoreId = auth.currentUser?.uid;

  useEffect(() => {
    if (!currentStoreId) return;

    onValue(ref(db, `stores/${currentStoreId}`), (snapshot) => {
      if (snapshot.exists()) {
        const data = snapshot.val();
        setStoreProfile(data);
        setEditProfileData({ 
          name: data.name || '', 
          phone: data.phone || '', 
          image: data.image || '' 
        });
      }
    });

    onValue(ref(db, 'products'), (snapshot) => {
      const data = snapshot.val();
      const list: Product[] = [];
      if (data) Object.keys(data).forEach(key => { if (data[key].storeId === currentStoreId) list.push({ ...data[key], id: key }); });
      setMyProducts(list.reverse());
    });

    onValue(ref(db, 'orders'), (snapshot) => {
      const data = snapshot.val();
      const list: Order[] = [];
      if (data) Object.keys(data).forEach(key => { if (data[key].storeId === currentStoreId) list.push({ ...data[key], id: key }); });
      setOrders(list.sort((a, b) => b.timestamp - a.timestamp));
      setLoading(false);
    });
  }, [currentStoreId]);

  const handleAiDescription = async () => {
    if (!newProduct.name) return alert("أدخل اسم المنتج أولاً!");
    setIsAiGenerating(true);
    const description = await generateProductDescription(newProduct.name, newProduct.category || Category.FOOD);
    setNewProduct(prev => ({ ...prev, description }));
    setIsAiGenerating(false);
  };

  const saveProduct = async () => {
    if (!newProduct.name || !newProduct.price || !newProduct.image || !currentStoreId) return alert("أكمل البيانات");
    setIsSaving(true);
    try {
      const newRef = push(ref(db, 'products'));
      await set(newRef, { ...newProduct, storeId: currentStoreId, id: newRef.key });
      setIsAddingProduct(false);
      setNewProduct({ name: '', description: '', price: 0, category: Category.FOOD, image: '' });
    } finally { setIsSaving(false); }
  };

  const handleUpdateProfile = async () => {
    if (!currentStoreId || !editProfileData.name || !editProfileData.phone) return;
    setIsUpdatingProfile(true);
    try {
      await update(ref(db, `stores/${currentStoreId}`), {
        name: editProfileData.name,
        phone: editProfileData.phone,
        image: editProfileData.image
      });
      setIsEditingProfile(false);
      alert("تم تحديث بيانات المتجر بنجاح ✓");
    } catch (e) {
      alert("حدث خطأ أثناء التحديث");
    } finally {
      setIsUpdatingProfile(false);
    }
  };

  const handleProfileImageUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      setIsUploadingProfileImage(true);
      const url = await uploadImage(file);
      if (url) {
        setEditProfileData(prev => ({ ...prev, image: url }));
      }
      setIsUploadingProfileImage(false);
    }
  };

  const handleUpdateLocation = () => {
    setIsLocating(true);
    if ("geolocation" in navigator) {
      navigator.geolocation.getCurrentPosition(
        async (position) => {
          if (currentStoreId) {
            await update(ref(db, `stores/${currentStoreId}`), {
              coordinates: { 
                lat: position.coords.latitude, 
                lng: position.coords.longitude 
              }
            });
            alert("تم تحديث موقع المتجر الجغرافي بنجاح ✓");
          }
          setIsLocating(false);
        },
        (error) => {
          alert("يرجى تفعيل الـ GPS لتحديد موقع المتجر");
          setIsLocating(false);
        }
      );
    } else {
      alert("المتصفح لا يدعم تحديد الموقع");
      setIsLocating(false);
    }
  };

  if (loading) return <div className="h-screen flex items-center justify-center bg-slate-900"><Loader2 className="animate-spin text-orange-500 w-12 h-12" /></div>;

  return (
    <div className="min-h-screen bg-[#F8F9FA] pb-32 font-cairo text-right" dir="rtl">
      <header className="p-6 flex justify-between items-center bg-white border-b border-gray-100 sticky top-0 z-50">
        <div>
           <h1 className="text-2xl font-black text-slate-800">كيمو متاجر</h1>
           <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest">{storeProfile?.name || userName}</p>
        </div>
        {activeTab === 'PRODUCTS' && !isAddingProduct && (
          <button onClick={() => setIsAddingProduct(true)} className="bg-orange-500 text-white px-6 py-3 rounded-2xl font-black text-sm flex items-center gap-2 shadow-lg shadow-orange-500/20 active:scale-95 transition-all"><Plus className="w-5 h-5" /> منتج جديد</button>
        )}
      </header>

      <main className="p-6 max-w-lg mx-auto">
        {activeTab === 'PRODUCTS' && (
          <div className="animate-fade-in-up">
            {!isAddingProduct ? (
              <div className="space-y-4">
                {myProducts.length === 0 ? (
                  <div className="bg-white rounded-[2.5rem] p-12 text-center text-slate-300 border border-dashed border-slate-200">
                    <Package className="w-16 h-16 mx-auto mb-4 opacity-10" />
                    <p className="font-black text-sm">لا توجد منتجات معروضة حالياً</p>
                  </div>
                ) : (
                  myProducts.map(p => (
                    <div key={p.id} className="bg-white p-5 rounded-[2.5rem] shadow-sm border border-gray-50 flex gap-4 items-center group">
                      <img src={p.image} className="w-24 h-24 rounded-2xl object-cover shadow-inner" />
                      <div className="flex-1 text-right">
                        <h4 className="font-black text-slate-800 text-lg">{p.name}</h4>
                        <p className="text-xs text-slate-400 font-bold mb-3">{p.description?.slice(0, 40)}...</p>
                        <div className="flex items-center justify-between">
                           <span className="text-xl font-black text-orange-500">{formatCurrency(p.price)}</span>
                           <button onClick={() => remove(ref(db, `products/${p.id}`))} className="p-2 text-slate-300 hover:text-red-500 transition-colors"><Trash2 className="w-5 h-5"/></button>
                        </div>
                      </div>
                    </div>
                  ))
                )}
              </div>
            ) : (
              <div className="bg-white p-8 rounded-[3rem] shadow-xl animate-scale-up border border-slate-50">
                <button onClick={() => setIsAddingProduct(false)} className="mb-6 flex items-center gap-2 text-slate-400 font-bold text-sm"><ArrowLeft className="w-4 h-4"/> إلغاء</button>
                <div className="space-y-6">
                   <div onClick={() => !isUploading && document.getElementById('p-img')?.click()} className="w-full h-48 border-2 border-dashed border-slate-200 rounded-[2.5rem] flex flex-col items-center justify-center cursor-pointer overflow-hidden relative bg-slate-50 hover:bg-slate-100 transition-all">
                     {newProduct.image ? <img src={newProduct.image} className="w-full h-full object-cover" /> : <div className="text-center"><Upload className="text-slate-300 mx-auto mb-2" /><p className="text-xs text-slate-400 font-bold">ارفع صورة المنتج</p></div>}
                     {isUploading && <div className="absolute inset-0 bg-white/60 flex items-center justify-center"><Loader2 className="animate-spin text-orange-500" /></div>}
                     <input type="file" id="p-img" onChange={e => {
                        const file = e.target.files?.[0];
                        if (file) { setIsUploading(true); uploadImage(file).then(url => { if (url) setNewProduct({...newProduct, image: url}); setIsUploading(false); }); }
                     }} className="hidden" accept="image/*" />
                   </div>

                   <input type="text" placeholder="اسم المنتج" value={newProduct.name} onChange={e => setNewProduct({...newProduct, name: e.target.value})} className="w-full p-4 bg-slate-50 rounded-2xl font-bold outline-none border-2 border-transparent focus:border-orange-500 transition-all" />

                   <div className="relative">
                      <textarea 
                        placeholder="وصف المنتج..." 
                        value={newProduct.description} 
                        onChange={e => setNewProduct({...newProduct, description: e.target.value})} 
                        className="w-full p-4 bg-slate-50 rounded-2xl font-bold outline-none border-2 border-transparent focus:border-orange-500 transition-all h-32 resize-none" 
                      />
                      <button 
                        onClick={handleAiDescription}
                        disabled={isAiGenerating}
                        className="absolute bottom-4 left-4 flex items-center gap-2 bg-orange-100 text-orange-600 px-4 py-2 rounded-xl text-[10px] font-black hover:bg-orange-200 transition-all"
                      >
                         {isAiGenerating ? <Loader2 className="animate-spin w-3 h-3" /> : <Sparkles className="w-3 h-3" />}
                         توليد بالذكاء الاصطناعي
                      </button>
                   </div>

                   <input type="number" placeholder="السعر بالدينار" value={newProduct.price || ''} onChange={e => setNewProduct({...newProduct, price: Number(e.target.value)})} className="w-full p-4 bg-slate-50 rounded-2xl font-bold outline-none border-2 border-transparent focus:border-orange-500 transition-all" />

                   <button onClick={saveProduct} disabled={isSaving || isUploading} className="w-full brand-gradient text-white py-5 rounded-[2rem] font-black shadow-xl shadow-orange-500/20 flex items-center justify-center gap-3">
                     {isSaving ? <Loader2 className="animate-spin" /> : <><CheckCircle className="w-6 h-6" /> نشر المنتج الآن</>}
                   </button>
                </div>
              </div>
            )}
          </div>
        )}

        {activeTab === 'ORDERS' && (
           <div className="space-y-4 animate-fade-in-up">
              <h2 className="text-3xl font-black text-slate-900 mb-6">طلبات المتجر</h2>
              {orders.length === 0 ? (
                <div className="bg-white rounded-[2.5rem] p-12 text-center text-slate-300 border border-dashed border-slate-200">
                  <ClipboardList className="w-16 h-16 mx-auto mb-4 opacity-10" />
                  <p className="font-black text-sm">لا توجد طلبيات حالياً</p>
                </div>
              ) : (
                orders.map(o => (
                  <div key={o.id} className="bg-white p-6 rounded-[2.5rem] shadow-sm border border-slate-50">
                     <div className="flex justify-between items-start mb-4">
                        <div>
                          <h4 className="font-black text-slate-800 text-lg">{o.customerName}</h4>
                          <p className="text-[10px] text-slate-400 font-bold">{new Date(o.timestamp).toLocaleString('ar-DZ')}</p>
                        </div>
                        <span className="text-orange-500 font-black text-xl">{formatCurrency(o.totalPrice)}</span>
                     </div>
                     <div className="mb-6">
                        <p className="text-xs font-bold text-slate-500 flex items-center gap-2"><MapPin className="w-4 h-4" /> {o.address}</p>
                     </div>
                     {o.status === OrderStatus.PENDING ? (
                        <button onClick={() => update(ref(db, `orders/${o.id}`), { status: OrderStatus.ACCEPTED_BY_STORE })} className="w-full bg-slate-900 text-white py-4 rounded-2xl font-black shadow-lg active:scale-95 transition-all">قبول وتحضير الطلب</button>
                     ) : (
                        <div className="bg-green-50 text-green-600 text-center py-3 rounded-2xl font-black text-xs uppercase tracking-widest border border-green-100 flex items-center justify-center gap-2">
                          <CheckCircle className="w-4 h-4" /> {o.status}
                        </div>
                     )}
                  </div>
                ))
              )}
           </div>
        )}

        {activeTab === 'PROFILE' && (
          <div className="animate-fade-in-up">
             <div className="bg-white p-10 rounded-[3rem] shadow-sm border border-gray-100 text-center relative overflow-hidden">
                <div className="absolute top-0 right-0 w-full h-2 brand-gradient"></div>

                <div 
                  className={`w-32 h-32 rounded-[2.5rem] border-4 border-slate-50 overflow-hidden shadow-xl mx-auto mb-8 bg-slate-50 p-1 relative group ${isEditingProfile ? 'cursor-pointer' : ''}`}
                  onClick={() => isEditingProfile && !isUploadingProfileImage && profileImageInputRef.current?.click()}
                >
                   <img src={isEditingProfile ? editProfileData.image : (storeProfile?.image || `https://api.dicebear.com/7.x/identicon/svg?seed=${storeProfile?.name || userName}`)} className="w-full h-full object-cover rounded-[2rem]" />
                   {isEditingProfile && (
                     <div className="absolute inset-0 bg-black/40 flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity">
                        <Camera className="text-white w-8 h-8" />
                     </div>
                   )}
                   {isUploadingProfileImage && (
                     <div className="absolute inset-0 bg-white/60 flex items-center justify-center">
                        <Loader2 className="animate-spin text-orange-500" />
                     </div>
                   )}
                </div>
                <input 
                  type="file" 
                  ref={profileImageInputRef} 
                  onChange={handleProfileImageUpload} 
                  className="hidden" 
                  accept="image/*" 
                />

                {!isEditingProfile ? (
                  <>
                    <h3 className="text-2xl font-black mb-1 text-slate-800">{storeProfile?.name || userName}</h3>
                    <p className="text-orange-500 font-black text-xs mb-2 uppercase tracking-widest">{storeProfile?.category || 'متجر كيمو'}</p>
                    <p className="text-slate-400 font-bold mb-10 flex items-center justify-center gap-2"><Phone className="w-4 h-4" /> {storeProfile?.phone || 'لا يوجد رقم مسجل'}</p>

                    <div className="space-y-4">
                       <button onClick={() => setIsEditingProfile(true)} className="w-full bg-slate-100 text-slate-600 py-4 rounded-2xl font-black flex items-center justify-center gap-2 transition-all hover:bg-slate-200">
                         تعديل البروفيل
                       </button>
                       <button onClick={onLogout} className="w-full bg-red-50 text-red-500 py-4 rounded-2xl font-black flex items-center justify-center gap-2 hover:bg-red-500 hover:text-white transition-all">
                         <LogOut className="w-5 h-5" /> تسجيل الخروج
                       </button>
                    </div>
                  </>
                ) : (
                  <div className="space-y-5 text-right">
                    <div className="space-y-2">
                       <label className="text-[10px] font-black text-slate-400 pr-3 uppercase">اسم المتجر</label>
                       <input 
                         type="text" 
                         value={editProfileData.name} 
                         onChange={e => setEditProfileData({...editProfileData, name: e.target.value})}
                         className="w-full p-4 bg-slate-50 border border-slate-100 rounded-2xl font-bold outline-none focus:border-orange-500 transition-all"
                       />
                    </div>

                    <div className="space-y-2">
                       <label className="text-[10px] font-black text-slate-400 pr-3 uppercase">رقم هاتف المتجر</label>
                       <input 
                         type="tel" 
                         value={editProfileData.phone} 
                         onChange={e => setEditProfileData({...editProfileData, phone: e.target.value})}
                         className="w-full p-4 bg-slate-50 border border-slate-100 rounded-2xl font-bold outline-none focus:border-orange-500 transition-all"
                       />
                    </div>

                    <button 
                      onClick={handleUpdateLocation}
                      disabled={isLocating}
                      className="w-full py-4 border-2 border-dashed border-orange-200 text-orange-600 rounded-2xl font-black text-xs flex items-center justify-center gap-2 bg-orange-50/50 hover:bg-orange-50 transition-all"
                    >
                      {isLocating ? <Loader2 className="animate-spin w-4 h-4" /> : <Navigation className="w-4 h-4" />}
                      تحديث موقع المتجر (GPS)
                    </button>

                    <div className="flex gap-4 pt-6">
                       <button 
                         onClick={handleUpdateProfile}
                         disabled={isUpdatingProfile || isUploadingProfileImage}
                         className="flex-1 brand-gradient text-white py-4 rounded-2xl font-black shadow-xl flex items-center justify-center gap-2 active:scale-95 transition-all"
                       >
                         {isUpdatingProfile ? <Loader2 className="animate-spin" /> : <Save className="w-5 h-5" />}
                         حفظ البيانات
                       </button>
                       <button 
                         onClick={() => setIsEditingProfile(false)}
                         className="px-8 bg-slate-100 text-slate-400 py-4 rounded-2xl font-black hover:bg-slate-200 transition-all"
                       >
                         إلغاء
                       </button>
                    </div>
                  </div>
                )}
             </div>
          </div>
        )}
      </main>

      <nav className="fixed bottom-8 left-8 right-8 bg-[#2B2F3B]/95 backdrop-blur-xl rounded-[2.5rem] p-3 flex justify-around items-center shadow-2xl z-[200]">
         <button onClick={() => { setIsAddingProduct(false); setActiveTab('PRODUCTS'); }} className={`p-5 rounded-full transition-all ${activeTab === 'PRODUCTS' ? 'bg-orange-500 text-white scale-110 shadow-lg' : 'text-slate-500'}`}><Package className="w-7 h-7" /></button>
         <button onClick={() => { setIsAddingProduct(false); setActiveTab('ORDERS'); }} className={`p-5 rounded-full transition-all ${activeTab === 'ORDERS' ? 'bg-orange-500 text-white scale-110 shadow-lg' : 'text-slate-500'}`}><ClipboardList className="w-7 h-7" /></button>
         <button onClick={() => { setIsAddingProduct(false); setActiveTab('PROFILE'); }} className={`p-5 rounded-full transition-all ${activeTab === 'PROFILE' ? 'bg-orange-500 text-white scale-110 shadow-lg' : 'text-slate-500'}`}><User className="w-7 h-7" /></button>
      </nav>
    </div>
  );
};

import React, { useState, useRef } from 'react';
import { Category, UserRole } from '../types';
import { auth, db } from '../services/firebase';
import { createUserWithEmailAndPassword, signInWithEmailAndPassword } from 'firebase/auth';
import { ref, set } from 'firebase/database';
import { ShoppingBag, Store, Bike, MapPin, ArrowRight, Loader2, Phone, Lock, User, Mail, ChevronLeft, AlertCircle, Upload, Camera, X, Navigation } from 'lucide-react';

interface AuthScreenProps {
  onLogin: (role: UserRole, name?: string) => void;
}

const uploadImage = async (file: File): Promise<string | null> => {
  const formData = new FormData();
  formData.append("file", file);
  formData.append("upload_preset", "makemm");
  const cloudName = 'dkqxgwjnr';
  try {
    const res = await fetch(`https://api.cloudinary.com/v1_1/${cloudName}/image/upload`, {
      method: "POST",
      body: formData,
    });
    const data = await res.json();
    return data.secure_url || null;
  } catch (error) {
    return null;
  }
};

export const AuthScreen: React.FC<AuthScreenProps> = ({ onLogin }) => {
  const [selectedRole, setSelectedRole] = useState<UserRole | null>(null);
  const [authMode, setAuthMode] = useState<'LOGIN' | 'REGISTER'>('LOGIN');
  const [isLoading, setIsLoading] = useState(false);
  const [isUploading, setIsUploading] = useState(false);
  const [isLocating, setIsLocating] = useState(false);
  const [formData, setFormData] = useState({ 
    name: '', 
    email: '', 
    phone: '', 
    password: '', 
    storeImage: '',
    coords: null as {lat: number, lng: number} | null
  });
  const [error, setError] = useState('');

  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleRoleSelect = (role: UserRole) => {
    setSelectedRole(role);
    setAuthMode('LOGIN');
    setError('');
  };

  const handleBack = () => {
    setSelectedRole(null);
    setFormData({ name: '', email: '', phone: '', password: '', storeImage: '', coords: null });
    setError('');
  };

  const handleGetLocation = () => {
    setIsLocating(true);
    setError('');
    if ("geolocation" in navigator) {
      navigator.geolocation.getCurrentPosition(
        (position) => {
          setFormData(prev => ({ 
            ...prev, 
            coords: { 
              lat: position.coords.latitude, 
              lng: position.coords.longitude 
            } 
          }));
          setIsLocating(false);
        },
        (error) => {
          setIsLocating(false);
          setError("يرجى تفعيل صلاحية الوصول للموقع (GPS) لتتمكن من التسجيل.");
        },
        { enableHighAccuracy: true }
      );
    } else {
      setIsLocating(false);
      setError("متصفحك لا يدعم تقنية تحديد الموقع.");
    }
  };

  const handleImageUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      setIsUploading(true);
      const url = await uploadImage(file);
      if (url) setFormData(prev => ({ ...prev, storeImage: url }));
      setIsUploading(false);
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');

    if (authMode === 'REGISTER') {
      if (!formData.coords) {
        setError('تحديد الموقع الجغرافي إلزامي لضمان جودة التوصيل.');
        return;
      }
      if (!formData.name || !formData.phone || !formData.email || !formData.password) {
        setError('يرجى ملء كافة البيانات المطلوبة.');
        return;
      }
    }

    setIsLoading(true);

    try {
      if (authMode === 'REGISTER') {
        const userCredential = await createUserWithEmailAndPassword(auth, formData.email, formData.password);
        const user = userCredential.user;

        const dbPath = selectedRole === UserRole.CUSTOMER ? 'customers' : selectedRole === UserRole.STORE ? 'stores' : 'drivers';

        const profileData: any = {
            id: user.uid,
            name: formData.name,
            email: formData.email,
            phone: formData.phone,
            role: selectedRole,
            createdAt: Date.now(),
            coordinates: formData.coords
        };

        if (selectedRole === UserRole.STORE) {
            profileData.category = Category.FOOD;
            profileData.image = formData.storeImage || `https://picsum.photos/400/300?random=${user.uid.slice(0,5)}`;
            profileData.rating = 0;
            profileData.reviewCount = 0;
            profileData.isVerified = false;
        }

        await set(ref(db, `${dbPath}/${user.uid}`), profileData);
        onLogin(selectedRole!, formData.name);
      } else {
        await signInWithEmailAndPassword(auth, formData.email, formData.password);
        onLogin(selectedRole || UserRole.CUSTOMER);
      }
    } catch (err: any) {
      if (err.code === 'auth/email-already-in-use') setError('هذا البريد الإلكتروني مسجل مسبقاً.');
      else if (err.code === 'auth/weak-password') setError('كلمة المرور ضعيفة جداً.');
      else setError('حدث خطأ أثناء التسجيل: ' + err.message);
    } finally {
      setIsLoading(false);
    }
  };

  if (!selectedRole) {
    return (
      <div className="min-h-screen bg-[#0F172A] flex flex-col items-center justify-center p-4 relative overflow-hidden font-cairo text-right" dir="rtl">
        {/* الحلقات الديكورية في الخلفية */}
        <div className="absolute top-1/4 left-1/2 -translate-x-1/2 w-96 h-96 bg-orange-500/10 rounded-full blur-[100px] pointer-events-none"></div>

        <div className="z-10 text-center mb-12 animate-fade-in-up">
          {/* الشعار الجديد المرفوع من المستخدم */}
          <div className="w-36 h-36 bg-white rounded-[3rem] flex items-center justify-center mx-auto mb-6 shadow-[0_20px_50px_rgba(0,0,0,0.3)] relative overflow-hidden group border border-white/20">
            <img 
              src="https://res.cloudinary.com/dkqxgwjnr/image/upload/v1740000000/kimo_new_logo.png" 
              alt="Kimo Logo" 
              className="w-[85%] h-[85%] object-contain transition-transform duration-700 group-hover:scale-110"
              onError={(e) => {
                // Fallback في حال فشل تحميل الصورة، يتم استخدام النسخة المخزنة محلياً أو المرفوعة
                e.currentTarget.src = "https://i.ibb.co/v6mBfGZp/Screenshot-2025-02-18-214156.png"; 
              }}
            />
            <div className="absolute inset-0 bg-gradient-to-tr from-orange-500/10 to-transparent pointer-events-none"></div>
          </div>

          <h1 className="text-6xl font-black text-white mb-2 tracking-tighter drop-shadow-lg">كيمو</h1>
          <p className="text-slate-400 font-bold tracking-wide">كل شي يوصلك وين ما كنت</p>
        </div>

        <div className="grid grid-cols-1 gap-4 w-full max-w-sm z-10">
          <RoleCard icon={<ShoppingBag/>} title="أنا زبون" desc="اطلب ووصلك لعند الباب" onClick={() => handleRoleSelect(UserRole.CUSTOMER)} />
          <RoleCard icon={<Store/>} title="أنا متجر" desc="اعرض منتجاتك وزيد دخلك" onClick={() => handleRoleSelect(UserRole.STORE)} />
          <RoleCard icon={<Bike/>} title="أنا موصل" desc="خدم أحرار في منطقتك" onClick={() => handleRoleSelect(UserRole.DRIVER)} />
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-white flex items-center justify-center p-4 font-cairo text-right" dir="rtl">
      <div className="w-full max-w-md animate-scale-up">
        <button onClick={handleBack} className="flex items-center gap-2 text-slate-400 font-bold mb-6 text-sm hover:text-slate-600 transition-colors"><ChevronLeft className="w-4 h-4 rotate-180" /> رجوع للخلف</button>
        <h2 className="text-4xl font-black text-slate-800 mb-2">{authMode === 'LOGIN' ? 'تسجيل دخول' : 'إنشاء حساب'}</h2>
        <p className="text-slate-500 mb-8 font-bold">أهلاً بك في كيمو - قسم {selectedRole === UserRole.STORE ? 'المتاجر' : selectedRole === UserRole.DRIVER ? 'الموصلين' : 'الزبائن'}</p>

        <form onSubmit={handleSubmit} className="space-y-4">
          {error && <div className="bg-red-50 text-red-500 p-4 rounded-2xl text-xs font-black border border-red-100 flex items-center gap-2 animate-pulse"><AlertCircle size={16}/> {error}</div>}

          {authMode === 'REGISTER' && (
            <>
              {selectedRole === UserRole.STORE && (
                <div className="flex flex-col items-center mb-6">
                  <div 
                    onClick={() => fileInputRef.current?.click()}
                    className="w-24 h-24 rounded-[2rem] bg-slate-50 border-2 border-dashed border-slate-200 flex items-center justify-center cursor-pointer overflow-hidden relative group hover:border-orange-500 transition-all"
                  >
                    {formData.storeImage ? <img src={formData.storeImage} className="w-full h-full object-cover" /> : <Camera className="text-slate-300 group-hover:text-orange-500 transition-colors" />}
                    {isUploading && <div className="absolute inset-0 bg-white/60 flex items-center justify-center"><Loader2 className="animate-spin text-orange-500" /></div>}
                  </div>
                  <input type="file" ref={fileInputRef} onChange={handleImageUpload} className="hidden" accept="image/*" />
                  <p className="text-[10px] text-slate-400 mt-2 font-black uppercase tracking-widest">تحميل شعار المتجر</p>
                </div>
              )}

              <button 
                type="button" 
                onClick={handleGetLocation} 
                disabled={isLocating}
                className={`w-full p-5 rounded-2xl border-2 border-dashed transition-all flex items-center justify-center gap-3 font-black text-sm ${formData.coords ? 'border-green-500 text-green-600 bg-green-50 shadow-inner' : 'border-orange-200 text-orange-600 bg-orange-50 hover:bg-orange-100'}`}
              >
                {isLocating ? <Loader2 className="animate-spin w-5 h-5" /> : <Navigation className="w-5 h-5" />}
                {formData.coords ? 'تم التقاط موقعك الحالي بنجاح ✓' : 'تحديد موقعي الآن عبر GPS (إلزامي)'}
              </button>

              <div className="relative">
                <input type="text" value={formData.name} onChange={e => setFormData({...formData, name: e.target.value})} className="w-full p-4 pr-12 bg-slate-50 border border-slate-100 rounded-2xl outline-none focus:border-orange-500 font-bold transition-all shadow-sm" placeholder="الاسم الكامل" />
                <User className="absolute right-4 top-4 text-slate-300 w-5 h-5" />
              </div>

              <div className="relative">
                <input type="tel" value={formData.phone} onChange={e => setFormData({...formData, phone: e.target.value})} className="w-full p-4 pr-12 bg-slate-50 border border-slate-100 rounded-2xl outline-none focus:border-orange-500 font-bold transition-all shadow-sm" placeholder="رقم الهاتف" />
                <Phone className="absolute right-4 top-4 text-slate-300 w-5 h-5" />
              </div>
            </>
          )}

          <div className="relative">
            <input type="email" value={formData.email} onChange={e => setFormData({...formData, email: e.target.value})} className="w-full p-4 pr-12 bg-slate-50 border border-slate-100 rounded-2xl outline-none focus:border-orange-500 font-bold transition-all shadow-sm" placeholder="البريد الإلكتروني" />
            <Mail className="absolute right-4 top-4 text-slate-300 w-5 h-5" />
          </div>

          <div className="relative">
            <input type="password" value={formData.password} onChange={e => setFormData({...formData, password: e.target.value})} className="w-full p-4 pr-12 bg-slate-50 border border-slate-100 rounded-2xl outline-none focus:border-orange-500 font-bold transition-all shadow-sm" placeholder="كلمة المرور" />
            <Lock className="absolute right-4 top-4 text-slate-300 w-5 h-5" />
          </div>

          <button type="submit" disabled={isLoading || isUploading || (authMode === 'REGISTER' && !formData.coords)} className="w-full bg-[#2B2F3B] text-white py-5 rounded-2xl font-black text-lg shadow-xl shadow-slate-900/10 active:scale-95 transition-all disabled:opacity-50 disabled:cursor-not-allowed">
            {isLoading ? <Loader2 className="animate-spin mx-auto" /> : (authMode === 'LOGIN' ? 'دخول' : 'بدء الاستخدام في كيمو')}
          </button>

          <button type="button" onClick={() => { setAuthMode(authMode === 'LOGIN' ? 'REGISTER' : 'LOGIN'); setError(''); }} className="w-full text-center text-slate-400 text-sm font-bold pt-4 hover:text-orange-500 transition-colors">
            {authMode === 'LOGIN' ? 'جديد في كيمو؟ سجل حسابك الحقيقي هنا' : 'لديك حساب؟ سجل دخولك'}
          </button>
        </form>
      </div>
    </div>
  );
};

const RoleCard = ({ icon, title, desc, onClick }: any) => (
  <button onClick={onClick} className="bg-slate-800/40 backdrop-blur-md border border-slate-700/50 p-6 rounded-[2.5rem] text-right flex items-center gap-5 hover:bg-slate-800/80 transition-all active:scale-95 group shadow-lg">
    <div className="w-16 h-16 bg-orange-500 text-white rounded-2xl flex items-center justify-center shrink-0 shadow-lg shadow-orange-500/20 group-hover:rotate-6 transition-transform">
      {React.cloneElement(icon, { size: 32 })}
    </div>
    <div>
      <h3 className="text-xl font-black text-white leading-none mb-1.5">{title}</h3>
      <p className="text-slate-400 text-[11px] font-bold">{desc}</p>
    </div>
  </button>
);

import React, { useState, useRef, useEffect } from 'react';
import { Category, Product, Order, OrderStatus, StoreProfile } from '../types';
import { db, auth } from '../services/firebase';
import { ref, push, set, onValue, remove, update } from 'firebase/database';
import { 
  Package, Plus, Upload, Loader2, Trash2, ArrowLeft, 
  ClipboardList, CheckCircle, Camera, LogOut, User, 
  RefreshCw, Phone, Tag, Sparkles, Wand2, Save, MapPin, Navigation,
  ChevronLeft, ShoppingBag, Star, LayoutGrid, Home
} from 'lucide-react';
import { formatCurrency } from '../utils/helpers';
import { generateProductDescription } from '../services/geminiService';

interface StoreScreenProps {
  onLogout: () => void;
  userName: string;
}

const uploadImage = async (file: File): Promise<string | null> => {
  const formData = new FormData();
  formData.append("file", file);
  formData.append("upload_preset", "makemm");
  const cloudName = 'dkqxgwjnr';
  try {
    const res = await fetch(`https://api.cloudinary.com/v1_1/${cloudName}/image/upload`, {
      method: "POST",
      body: formData,
    });
    const data = await res.json();
    return data.secure_url || null;
  } catch (error) { return null; }
};

export const StoreScreen: React.FC<StoreScreenProps> = ({ onLogout, userName }) => {
  const [activeTab, setActiveTab] = useState<'PRODUCTS' | 'ORDERS' | 'PROFILE'>('PRODUCTS');
  const [myProducts, setMyProducts] = useState<Product[]>([]);
  const [orders, setOrders] = useState<Order[]>([]);
  const [storeProfile, setStoreProfile] = useState<StoreProfile | null>(null);
  const [loading, setLoading] = useState(true);

  const [isAddingProduct, setIsAddingProduct] = useState(false);
  const [isUploading, setIsUploading] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const [isAiGenerating, setIsAiGenerating] = useState(false);

  const [isEditingProfile, setIsEditingProfile] = useState(false);
  const [editProfileData, setEditProfileData] = useState({ name: '', phone: '', image: '' });
  const [isUpdatingProfile, setIsUpdatingProfile] = useState(false);
  const [isLocating, setIsLocating] = useState(false);
  const [isUploadingProfileImage, setIsUploadingProfileImage] = useState(false);

  const [newProduct, setNewProduct] = useState<Partial<Product>>({
    name: '', description: '', price: 0, category: Category.FOOD, image: ''
  });

  const profileImageInputRef = useRef<HTMLInputElement>(null);
  const currentStoreId = auth.currentUser?.uid;

  useEffect(() => {
    if (!currentStoreId) return;

    onValue(ref(db, `stores/${currentStoreId}`), (snapshot) => {
      if (snapshot.exists()) {
        const data = snapshot.val();
        setStoreProfile(data);
        setEditProfileData({ 
          name: data.name || '', 
          phone: data.phone || '', 
          image: data.image || '' 
        });
      }
    });

    onValue(ref(db, 'products'), (snapshot) => {
      const data = snapshot.val();
      const list: Product[] = [];
      if (data) Object.keys(data).forEach(key => { if (data[key].storeId === currentStoreId) list.push({ ...data[key], id: key }); });
      setMyProducts(list.reverse());
    });

    onValue(ref(db, 'orders'), (snapshot) => {
      const data = snapshot.val();
      const list: Order[] = [];
      if (data) Object.keys(data).forEach(key => { if (data[key].storeId === currentStoreId) list.push({ ...data[key], id: key }); });
      setOrders(list.sort((a, b) => b.timestamp - a.timestamp));
      setLoading(false);
    });
  }, [currentStoreId]);

  const handleAiDescription = async () => {
    if (!newProduct.name) return alert("أدخل اسم المنتج أولاً!");
    setIsAiGenerating(true);
    const description = await generateProductDescription(newProduct.name, newProduct.category || Category.FOOD);
    setNewProduct(prev => ({ ...prev, description }));
    setIsAiGenerating(false);
  };

  const saveProduct = async () => {
    if (!newProduct.name || !newProduct.price || !newProduct.image || !currentStoreId) return alert("أكمل البيانات");
    setIsSaving(true);
    try {
      const newRef = push(ref(db, 'products'));
      await set(newRef, { ...newProduct, storeId: currentStoreId, id: newRef.key });
      setIsAddingProduct(false);
      setNewProduct({ name: '', description: '', price: 0, category: Category.FOOD, image: '' });
    } finally { setIsSaving(false); }
  };

  const handleUpdateProfile = async () => {
    if (!currentStoreId || !editProfileData.name || !editProfileData.phone) return;
    setIsUpdatingProfile(true);
    try {
      await update(ref(db, `stores/${currentStoreId}`), {
        name: editProfileData.name,
        phone: editProfileData.phone,
        image: editProfileData.image
      });
      setIsEditingProfile(false);
      alert("تم تحديث بيانات المتجر بنجاح ✓");
    } catch (e) {
      alert("حدث خطأ أثناء التحديث");
    } finally {
      setIsUpdatingProfile(false);
    }
  };

  const handleProfileImageUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      setIsUploadingProfileImage(true);
      const url = await uploadImage(file);
      if (url) setEditProfileData(prev => ({ ...prev, image: url }));
      setIsUploadingProfileImage(false);
    }
  };

  if (loading) return <div className="h-screen flex items-center justify-center bg-white"><Loader2 className="animate-spin text-orange-500 w-12 h-12" /></div>;

  return (
    <div className="bg-[#F4F4F4] min-h-screen pb-32 font-cairo text-right" dir="rtl">

      {/* Header Consistent with Customer */}
      <header className="bg-white sticky top-0 z-[100] px-6 pt-8 pb-4 shadow-sm flex items-center justify-between">
        <div>
           <h1 className="text-2xl font-black text-slate-800">كيمو متاجر</h1>
           <p className="text-[10px] text-orange-500 font-bold uppercase tracking-widest">{storeProfile?.name || userName}</p>
        </div>
        {activeTab === 'PRODUCTS' && !isAddingProduct && (
          <button onClick={() => setIsAddingProduct(true)} className="bg-slate-900 text-white p-3 rounded-2xl shadow-lg active:scale-95 transition-all">
            <Plus size={20} />
          </button>
        )}
      </header>

      <main className="p-4 max-w-lg mx-auto">
        {activeTab === 'PRODUCTS' && (
          <div className="animate-fade-in-up">
            {!isAddingProduct ? (
              <div className="space-y-4">
                <h2 className="text-xl font-black text-slate-800 px-2 mb-4">منتجاتي الحالية</h2>
                {myProducts.length === 0 ? (
                  <div className="bg-white rounded-[2.5rem] p-16 text-center text-slate-300 border border-dashed border-slate-200 shadow-sm">
                    <Package className="w-16 h-16 mx-auto mb-4 opacity-10" />
                    <p className="font-black text-sm text-slate-400">ابدأ بإضافة منتجك الأول لبيعه في كيمو</p>
                  </div>
                ) : (
                  myProducts.map(p => (
                    <div key={p.id} className="bg-white p-4 rounded-[2.5rem] shadow-sm border border-slate-50 flex gap-4 items-center group relative overflow-hidden">
                      <div className="w-24 h-24 rounded-[1.8rem] overflow-hidden bg-slate-50 border border-slate-100 flex-shrink-0">
                        <img src={p.image} className="w-full h-full object-cover" />
                      </div>
                      <div className="flex-1 text-right">
                        <h4 className="font-black text-slate-800 text-base mb-1">{p.name}</h4>
                        <p className="text-[10px] text-slate-400 font-bold mb-3 line-clamp-1">{p.description}</p>
                        <div className="flex items-center justify-between">
                           <span className="text-lg font-black text-orange-600">{formatCurrency(p.price)}</span>
                           <button onClick={() => remove(ref(db, `products/${p.id}`))} className="w-9 h-9 bg-red-50 text-red-400 rounded-xl flex items-center justify-center active:scale-90 transition-all"><Trash2 size={16}/></button>
                        </div>
                      </div>
                    </div>
                  ))
                )}
              </div>
            ) : (
              <div className="bg-white p-8 rounded-[3rem] shadow-xl animate-scale-up border border-slate-50">
                <button onClick={() => setIsAddingProduct(false)} className="mb-6 flex items-center gap-2 text-slate-400 font-black text-xs uppercase"><ChevronLeft className="w-4 h-4 rotate-180" /> العودة للمنتجات</button>
                <div className="space-y-6">
                   <div onClick={() => !isUploading && document.getElementById('p-img')?.click()} className="w-full h-48 border-2 border-dashed border-slate-200 rounded-[2.5rem] flex flex-col items-center justify-center cursor-pointer overflow-hidden relative bg-slate-50 hover:bg-slate-100 transition-all">
                     {newProduct.image ? <img src={newProduct.image} className="w-full h-full object-cover" /> : <div className="text-center"><Upload className="text-slate-300 mx-auto mb-2" /><p className="text-[10px] text-slate-400 font-black uppercase">تحميل صورة المنتج</p></div>}
                     {isUploading && <div className="absolute inset-0 bg-white/60 flex items-center justify-center"><Loader2 className="animate-spin text-orange-500" /></div>}
                     <input type="file" id="p-img" onChange={e => {
                        const file = e.target.files?.[0];
                        if (file) { setIsUploading(true); uploadImage(file).then(url => { if (url) setNewProduct({...newProduct, image: url}); setIsUploading(false); }); }
                     }} className="hidden" accept="image/*" />
                   </div>
                   <input type="text" placeholder="ما هو اسم المنتج؟" value={newProduct.name} onChange={e => setNewProduct({...newProduct, name: e.target.value})} className="w-full p-4 bg-slate-50 rounded-2xl font-bold outline-none border-2 border-transparent focus:border-orange-500 transition-all" />
                   <div className="relative">
                      <textarea placeholder="صف المنتج بكلمات بسيطة..." value={newProduct.description} onChange={e => setNewProduct({...newProduct, description: e.target.value})} className="w-full p-5 bg-slate-50 rounded-[2rem] font-bold outline-none h-32 resize-none" />
                      <button onClick={handleAiDescription} disabled={isAiGenerating} className="absolute bottom-4 left-4 flex items-center gap-2 bg-orange-100 text-orange-600 px-4 py-2 rounded-xl text-[10px] font-black">{isAiGenerating ? <Loader2 className="animate-spin w-3 h-3" /> : <Sparkles className="w-3 h-3" />} ذكاء اصطناعي</button>
                   </div>
                   <input type="number" placeholder="السعر (دينار جزائري)" value={newProduct.price || ''} onChange={e => setNewProduct({...newProduct, price: Number(e.target.value)})} className="w-full p-4 bg-slate-50 rounded-2xl font-bold outline-none border-2 border-transparent focus:border-orange-500 transition-all" />
                   <button onClick={saveProduct} disabled={isSaving || isUploading} className="w-full brand-gradient text-white py-5 rounded-[2rem] font-black shadow-xl flex items-center justify-center gap-3">
                     {isSaving ? <Loader2 className="animate-spin" /> : <>حفظ ونشر المنتج</>}
                   </button>
                </div>
              </div>
            )}
          </div>
        )}

        {activeTab === 'ORDERS' && (
           <div className="space-y-4 animate-fade-in-up px-2">
              <h2 className="text-2xl font-black text-slate-900 mb-6">طلبات المتجر</h2>
              {orders.length === 0 ? (
                <div className="bg-white rounded-[2.5rem] p-16 text-center text-slate-300 border border-dashed border-slate-200 shadow-sm">
                  <ClipboardList className="w-16 h-16 mx-auto mb-4 opacity-10" />
                  <p className="font-black text-sm text-slate-400">لا توجد طلبيات لعرضها حالياً</p>
                </div>
              ) : (
                orders.map(o => (
                  <div key={o.id} className="bg-white p-6 rounded-[2.5rem] shadow-sm border border-slate-50 overflow-hidden relative">
                     <div className="flex justify-between items-start mb-4">
                        <div>
                          <h4 className="font-black text-slate-800 text-lg leading-tight">{o.customerName}</h4>
                          <p className="text-[10px] text-slate-400 font-bold">{new Date(o.timestamp).toLocaleString('ar-DZ')}</p>
                        </div>
                        <span className="text-orange-500 font-black text-xl">{formatCurrency(o.totalPrice)}</span>
                     </div>
                     <div className="flex items-center gap-2 mb-6 bg-slate-50 p-3 rounded-2xl">
                        <MapPin size={14} className="text-slate-400" />
                        <p className="text-[10px] font-bold text-slate-600 truncate">{o.address}</p>
                     </div>
                     {o.status === OrderStatus.PENDING ? (
                        <button onClick={() => update(ref(db, `orders/${o.id}`), { status: OrderStatus.ACCEPTED_BY_STORE })} className="w-full bg-slate-900 text-white py-4 rounded-2xl font-black text-sm shadow-lg active:scale-95 transition-all">تحضير الطلبية الآن</button>
                     ) : (
                        <div className="bg-green-50 text-green-600 text-center py-3 rounded-2xl font-black text-[10px] border border-green-100 uppercase tracking-widest">{o.status}</div>
                     )}
                  </div>
                ))
              )}
           </div>
        )}

        {activeTab === 'PROFILE' && (
          <div className="animate-fade-in-up">
             <div className="bg-white p-10 rounded-[3rem] shadow-sm text-center border border-slate-50 relative overflow-hidden">
                <div 
                  className="w-28 h-28 rounded-[2.2rem] border-4 border-white shadow-xl mx-auto mb-6 bg-slate-50 relative overflow-hidden group cursor-pointer"
                  onClick={() => isEditingProfile && !isUploadingProfileImage && profileImageInputRef.current?.click()}
                >
                   <img src={isEditingProfile ? editProfileData.image : (storeProfile?.image || `https://api.dicebear.com/7.x/identicon/svg?seed=${storeProfile?.name}`)} className="w-full h-full object-cover" />
                   {isEditingProfile && (
                     <div className="absolute inset-0 bg-black/40 flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity"><Camera className="text-white w-6 h-6" /></div>
                   )}
                   {isUploadingProfileImage && (
                     <div className="absolute inset-0 bg-white/60 flex items-center justify-center"><Loader2 className="animate-spin text-orange-500" /></div>
                   )}
                </div>
                <input type="file" ref={profileImageInputRef} onChange={handleProfileImageUpload} className="hidden" accept="image/*" />

                {!isEditingProfile ? (
                  <>
                    <h3 className="text-2xl font-black mb-1 text-slate-800">{storeProfile?.name || userName}</h3>
                    <p className="text-xs text-slate-400 font-bold mb-8">{storeProfile?.phone || 'لا يوجد هاتف'}</p>
                    <div className="grid grid-cols-2 gap-4 mb-8">
                        <div className="bg-slate-50 p-4 rounded-2xl">
                           <p className="text-[10px] text-slate-400 font-black mb-1">المنتجات</p>
                           <p className="text-lg font-black text-slate-800">{myProducts.length}</p>
                        </div>
                        <div className="bg-slate-50 p-4 rounded-2xl">
                           <p className="text-[10px] text-slate-400 font-black mb-1">التقييم</p>
                           <div className="flex items-center justify-center gap-1"><Star size={12} className="text-yellow-400 fill-current" /><p className="text-lg font-black text-slate-800">{storeProfile?.rating?.toFixed(1) || '0.0'}</p></div>
                        </div>
                    </div>
                    <div className="space-y-3">
                       <button onClick={() => setIsEditingProfile(true)} className="w-full bg-[#F0F0F0] py-4 rounded-2xl font-black text-slate-700 text-sm active:scale-95 transition-all">تعديل الملف</button>
                       <button onClick={onLogout} className="w-full bg-red-50 py-4 rounded-2xl font-black text-red-500 text-sm mt-6">خروج من كيمو</button>
                    </div>
                  </>
                ) : (
                  <div className="space-y-5 text-right">
                    <div className="space-y-1">
                       <label className="text-[10px] font-black text-slate-400 pr-2">اسم المتجر</label>
                       <input type="text" value={editProfileData.name} onChange={e => setEditProfileData({...editProfileData, name: e.target.value})} className="w-full p-4 bg-slate-50 rounded-2xl font-bold outline-none" />
                    </div>
                    <div className="space-y-1">
                       <label className="text-[10px] font-black text-slate-400 pr-2">رقم الهاتف</label>
                       <input type="tel" value={editProfileData.phone} onChange={e => setEditProfileData({...editProfileData, phone: e.target.value})} className="w-full p-4 bg-slate-50 rounded-2xl font-bold outline-none" />
                    </div>
                    <div className="flex gap-3 pt-4">
                       <button onClick={handleUpdateProfile} disabled={isUpdatingProfile} className="flex-1 bg-black text-white py-4 rounded-2xl font-black text-sm shadow-xl active:scale-95 transition-all">حفظ</button>
                       <button onClick={() => setIsEditingProfile(false)} className="px-6 bg-slate-100 text-slate-400 py-4 rounded-2xl font-black">إلغاء</button>
                    </div>
                  </div>
                )}
             </div>
          </div>
        )}
      </main>

      {/* Bottom Nav Consistent with Customer */}
      <nav className="fixed bottom-0 left-0 right-0 bg-white border-t border-slate-100 h-20 flex justify-around items-center px-4 z-[500] shadow-[0_-5px_20px_rgba(0,0,0,0.03)]">
        <NavBtn act={activeTab === 'PRODUCTS'} onClick={() => setActiveTab('PRODUCTS')} icon={<LayoutGrid />} label="منتجاتي" />
        <NavBtn act={activeTab === 'ORDERS'} onClick={() => setActiveTab('ORDERS')} icon={<ClipboardList />} label="الطلبيات" />
        <NavBtn act={activeTab === 'PROFILE'} onClick={() => setActiveTab('PROFILE')} icon={<User />} label="حسابي" />
      </nav>
    </div>
  );
};

const NavBtn = ({ act, onClick, icon, label }: any) => (
  <button onClick={onClick} className={`flex flex-col items-center gap-1.5 transition-all ${act ? 'text-[#FF6000]' : 'text-slate-400'}`}>
    <div className={`p-1 ${act ? 'scale-110' : 'scale-100'} transition-transform`}>
      {React.cloneElement(icon, { size: 22, strokeWidth: act ? 3 : 2 })}
    </div>
    <span className="text-[9px] font-black tracking-tighter">{label}</span>
  </button>
);

import React, { useState, useEffect } from 'react';
import { MapVisualizer } from '../components/MapVisualizer';
import { RatingModal } from '../components/RatingModal';
import { 
  MapPin, Navigation, CheckCircle, Clock, Loader2, Package, Bike, 
  ArrowRight, User, LogOut, Camera, Phone, RefreshCw, Save,
  ChevronLeft, ShoppingBag, Star, LayoutGrid, Home, X, Bot, Map as MapIcon
} from 'lucide-react';
import { db, auth } from '../services/firebase';
import { ref, onValue, update, off } from 'firebase/database';
import { Order, OrderStatus, Coordinates } from '../types';
import { formatCurrency } from '../utils/helpers';

export const DriverScreen: React.FC<{onLogout: () => void, userName: string}> = ({ onLogout, userName }) => {
  const [activeTab, setActiveTab] = useState<'AVAILABLE' | 'ACTIVE' | 'PROFILE'>('AVAILABLE');
  const [showRating, setShowRating] = useState(false);
  const [availableOrders, setAvailableOrders] = useState<Order[]>([]);
  const [activeOrder, setActiveOrder] = useState<Order | null>(null);
  const [driverProfile, setDriverProfile] = useState<any>(null);
  const [loading, setLoading] = useState(true);

  const [isEditing, setIsEditing] = useState(false);
  const [editData, setEditData] = useState({ name: '', phone: '' });
  const [isUpdating, setIsUpdating] = useState(false);

  const currentDriverId = auth.currentUser?.uid;

  useEffect(() => {
    let interval: any;
    if (activeOrder && currentDriverId) {
      interval = setInterval(() => {
        navigator.geolocation.getCurrentPosition((pos) => {
          update(ref(db, `drivers/${currentDriverId}`), {
            coordinates: { lat: pos.coords.latitude, lng: pos.coords.longitude }
          });
        }, null, { enableHighAccuracy: true });
      }, 10000);
    }
    return () => clearInterval(interval);
  }, [activeOrder, currentDriverId]);

  useEffect(() => {
    if (!currentDriverId) return;

    onValue(ref(db, `drivers/${currentDriverId}`), (snap) => {
      if (snap.exists()) {
        const data = snap.val();
        setDriverProfile(data);
        setEditData({ name: data.name || '', phone: data.phone || '' });
      }
    });

    onValue(ref(db, 'orders'), (snapshot) => {
        const data = snapshot.val();
        const available: Order[] = [];
        let myActive: Order | null = null;
        if (data) {
            Object.keys(data).forEach(key => {
                const order = { ...data[key], id: key } as Order;
                if (order.driverId === currentDriverId && order.status !== OrderStatus.DELIVERED) myActive = order;
                if (order.status === OrderStatus.ACCEPTED_BY_STORE && !order.driverId) available.push(order);
            });
        }
        setAvailableOrders(available);
        setActiveOrder(myActive);
        setLoading(false);
    });
  }, [currentDriverId]);

  const handleUpdateProfile = async () => {
    if (!currentDriverId || !editData.name || !editData.phone) return;
    setIsUpdating(true);
    await update(ref(db, `drivers/${currentDriverId}`), { name: editData.name, phone: editData.phone });
    setIsEditing(false);
    setIsUpdating(false);
    alert("تم حفظ بياناتك ✓");
  };

  const handleAcceptOrder = async (orderId: string) => {
      if (!currentDriverId) return;
      await update(ref(db, `orders/${orderId}`), {
          status: OrderStatus.ACCEPTED_BY_DRIVER,
          driverId: currentDriverId,
          driverName: driverProfile?.name || userName,
          driverPhone: driverProfile?.phone || ''
      });
      setActiveTab('ACTIVE');
  };

  const handleCompleteOrder = async () => {
    if (!activeOrder) return;
    await update(ref(db, `orders/${activeOrder.id}`), { status: OrderStatus.DELIVERED });
    setShowRating(true);
  };

  if (loading) return <div className="h-screen flex items-center justify-center bg-white"><Loader2 className="animate-spin text-orange-500 w-12 h-12" /></div>;

  return (
    <div className="bg-[#F4F4F4] min-h-screen pb-32 font-cairo text-right" dir="rtl">

       {showRating && activeOrder && (
         <RatingModal type="CUSTOMER" targetId={activeOrder.customerId} targetName={activeOrder.customerName} onClose={() => { setShowRating(false); setActiveTab('AVAILABLE'); }} />
       )}

       {/* Special Full Screen Tracking for Driver */}
       {activeTab === 'ACTIVE' && activeOrder && (
         <div className="fixed inset-0 z-[1000] bg-white animate-fade-in flex flex-col">
           <div className="p-4 flex items-center justify-between border-b border-slate-100 bg-white shadow-sm">
             <button onClick={() => setActiveTab('AVAILABLE')} className="p-2 bg-slate-100 rounded-full active:scale-90"><ChevronLeft size={20} className="rotate-180"/></button>
             <div className="text-center">
                <h3 className="font-black text-slate-800 text-sm">مهمة توصيل نشطة</h3>
                <p className="text-[9px] font-bold text-slate-400">رقم الطلب: #{activeOrder.id?.slice(-5).toUpperCase()}</p>
             </div>
             <div className="w-10"></div>
           </div>

           <div className="flex-1 relative">
             <MapVisualizer height="h-full" zoom={15} customerLocation={activeOrder.coordinates} storeLocation={activeOrder.storeCoordinates} driverLocation={driverProfile?.coordinates} />
           </div>

           <div className="bg-white p-6 rounded-t-[3rem] shadow-[0_-10px_40px_rgba(0,0,0,0.15)] -mt-10 z-[1001] relative border-t border-slate-50">
             <div className="w-12 h-1.5 bg-slate-100 rounded-full mx-auto mb-6"></div>

             <div className="flex items-center gap-4 mb-6 bg-slate-50 p-4 rounded-[2rem]">
               <div className="w-14 h-14 brand-gradient rounded-2xl flex items-center justify-center text-white shadow-lg"><User size={28} /></div>
               <div className="flex-1">
                 <h4 className="font-black text-slate-800 text-base">{activeOrder.customerName}</h4>
                 <p className="text-[10px] text-slate-400 font-bold flex items-center gap-1"><MapPin size={10}/> {activeOrder.address}</p>
               </div>
               <a href={`tel:${activeOrder.customerPhone}`} className="w-12 h-12 bg-green-500 rounded-2xl flex items-center justify-center text-white shadow-lg active:scale-90 transition-all"><Phone size={20} /></a>
             </div>

             <div className="grid grid-cols-2 gap-3 mb-6">
                <div className="bg-slate-50 p-4 rounded-2xl">
                   <p className="text-[10px] text-slate-400 font-black mb-1">المتجر</p>
                   <p className="text-xs font-black text-slate-800 truncate">{activeOrder.storeName}</p>
                </div>
                <div className="bg-slate-50 p-4 rounded-2xl">
                   <p className="text-[10px] text-slate-400 font-black mb-1">المبلغ المحصل</p>
                   <p className="text-xs font-black text-orange-600">{formatCurrency(activeOrder.totalPrice)}</p>
                </div>
             </div>

             <button onClick={handleCompleteOrder} className="w-full brand-gradient text-white py-5 rounded-[2rem] font-black shadow-xl active:scale-95 transition-all flex items-center justify-center gap-3 mb-2">
                <CheckCircle size={24} /> تم تسليم الطلبية بنجاح
             </button>
           </div>
         </div>
       )}

       <header className="bg-white sticky top-0 z-[100] px-6 pt-8 pb-4 shadow-sm">
          <h1 className="text-2xl font-black text-slate-800">كيمو موصلين</h1>
          <p className="text-[10px] text-orange-500 font-bold uppercase tracking-widest">{driverProfile?.name || userName}</p>
       </header>

       <main className="p-4 max-w-lg mx-auto">
         {activeTab === 'AVAILABLE' && (
           <div className="animate-fade-in-up space-y-4 px-2">
              <div className="flex items-center justify-between mb-2">
                 <h2 className="text-xl font-black text-slate-800">طلبات متاحة للتوصيل</h2>
                 <div className="flex items-center gap-2 bg-green-100 px-3 py-1 rounded-full"><div className="w-2 h-2 bg-green-500 rounded-full animate-pulse"></div><span className="text-[8px] font-black text-green-700">متاح الآن</span></div>
              </div>

              {availableOrders.length === 0 ? (
                <div className="bg-white rounded-[2.5rem] p-16 text-center text-slate-300 border border-dashed border-slate-200 shadow-sm">
                  <Bike className="w-16 h-16 mx-auto mb-4 opacity-10" />
                  <p className="font-black text-sm text-slate-400">لا توجد طلبات في منطقتك حالياً</p>
                </div>
              ) : (
                availableOrders.map(o => (
                  <div key={o.id} className="bg-white p-6 rounded-[2.5rem] shadow-sm border border-slate-50 overflow-hidden relative group">
                     <div className="flex justify-between items-start mb-4">
                        <div className="flex items-center gap-3">
                           <div className="w-10 h-10 bg-slate-50 rounded-xl flex items-center justify-center text-orange-500"><ShoppingBag size={20} /></div>
                           <div>
                              <h4 className="font-black text-slate-800 text-base">{o.storeName}</h4>
                              <p className="text-[9px] text-slate-400 font-bold uppercase tracking-tighter">بئر العاتر • الجزائر</p>
                           </div>
                        </div>
                        <span className="text-lg font-black text-orange-600">{formatCurrency(o.totalPrice)}</span>
                     </div>
                     <div className="bg-slate-50 p-3 rounded-2xl flex items-center gap-2 mb-6">
                        <MapPin size={14} className="text-slate-400" />
                        <p className="text-[10px] font-bold text-slate-500 truncate">{o.address}</p>
                     </div>
                     <button onClick={() => handleAcceptOrder(o.id)} className="w-full bg-slate-900 text-white py-4 rounded-2xl font-black text-sm shadow-lg active:scale-95 transition-all">قبول هذه المهمة</button>
                  </div>
                ))
              )}
           </div>
         )}

         {activeTab === 'PROFILE' && (
           <div className="animate-fade-in-up">
              <div className="bg-white p-10 rounded-[3rem] shadow-sm text-center border border-slate-50 relative overflow-hidden">
                 <div className="w-28 h-28 rounded-[2.2rem] border-4 border-white shadow-xl mx-auto mb-6 bg-slate-50 relative overflow-hidden group">
                    <img src={`https://api.dicebear.com/7.x/identicon/svg?seed=${driverProfile?.name}`} className="w-full h-full object-cover" />
                 </div>

                 {!isEditing ? (
                   <>
                     <h3 className="text-2xl font-black mb-1 text-slate-800">{driverProfile?.name || userName}</h3>
                     <p className="text-xs text-slate-400 font-bold mb-8">{driverProfile?.phone || 'لا يوجد هاتف'}</p>
                     <div className="grid grid-cols-2 gap-4 mb-8">
                        <div className="bg-slate-50 p-4 rounded-2xl">
                           <p className="text-[10px] text-slate-400 font-black mb-1">التقييم</p>
                           <div className="flex items-center justify-center gap-1"><Star size={12} className="text-yellow-400 fill-current" /><p className="text-lg font-black text-slate-800">{driverProfile?.rating?.toFixed(1) || '0.0'}</p></div>
                        </div>
                        <div className="bg-slate-50 p-4 rounded-2xl">
                           <p className="text-[10px] text-slate-400 font-black mb-1">المكسب</p>
                           <p className="text-lg font-black text-green-600">0.00 د.ج</p>
                        </div>
                     </div>
                     <div className="space-y-3">
                        <button onClick={() => setIsEditing(true)} className="w-full bg-[#F0F0F0] py-4 rounded-2xl font-black text-slate-700 text-sm active:scale-95 transition-all">تعديل الملف</button>
                        <button onClick={onLogout} className="w-full bg-red-50 py-4 rounded-2xl font-black text-red-500 text-sm mt-6">خروج من كيمو</button>
                     </div>
                   </>
                 ) : (
                    <div className="space-y-5 text-right">
                       <div className="space-y-1">
                          <label className="text-[10px] font-black text-slate-400 pr-2">الاسم بالكامل</label>
                          <input type="text" value={editData.name} onChange={e => setEditData({...editData, name: e.target.value})} className="w-full p-4 bg-slate-50 rounded-2xl font-bold outline-none" />
                       </div>
                       <div className="space-y-1">
                          <label className="text-[10px] font-black text-slate-400 pr-2">رقم الهاتف</label>
                          <input type="tel" value={editData.phone} onChange={e => setEditData({...editData, phone: e.target.value})} className="w-full p-4 bg-slate-50 rounded-2xl font-bold outline-none" />
                       </div>
                       <div className="flex gap-3 pt-4">
                          <button onClick={handleUpdateProfile} disabled={isUpdating} className="flex-1 bg-black text-white py-4 rounded-2xl font-black text-sm active:scale-95 transition-all">حفظ</button>
                          <button onClick={() => setIsEditing(false)} className="px-6 bg-slate-100 text-slate-400 py-4 rounded-2xl font-black">إلغاء</button>
                       </div>
                    </div>
                 )}
              </div>
           </div>
         )}
       </main>

       {/* Bottom Nav Consistent with Others */}
       <nav className="fixed bottom-0 left-0 right-0 bg-white border-t border-slate-100 h-20 flex justify-around items-center px-4 z-[500] shadow-[0_-5px_20px_rgba(0,0,0,0.03)]">
         <NavBtn act={activeTab === 'AVAILABLE'} onClick={() => setActiveTab('AVAILABLE')} icon={<LayoutGrid />} label="طلبات عامة" />
         <NavBtn act={activeTab === 'ACTIVE'} onClick={() => setActiveTab('ACTIVE')} icon={<MapIcon />} label="المهمة الحالية" />
         <NavBtn act={activeTab === 'PROFILE'} onClick={() => setActiveTab('PROFILE')} icon={<User />} label="حسابي" />
       </nav>
    </div>
  );
};

const NavBtn = ({ act, onClick, icon, label }: any) => (
  <button onClick={onClick} className={`flex flex-col items-center gap-1.5 transition-all ${act ? 'text-[#FF6000]' : 'text-slate-400'}`}>
    <div className={`p-1 ${act ? 'scale-110' : 'scale-100'} transition-transform`}>
      {React.cloneElement(icon, { size: 22, strokeWidth: act ? 3 : 2 })}
    </div>
    <span className="text-[9px] font-black tracking-tighter">{label}</span>
  </button>
);

export enum UserRole {
  GUEST = 'GUEST',
  CUSTOMER = 'CUSTOMER',
  STORE = 'STORE',
  DRIVER = 'DRIVER'
}

export enum OrderStatus {
  PENDING = 'PENDING',               // Customer placed it, waiting for store
  ACCEPTED_BY_STORE = 'ACCEPTED_BY_STORE', // Store accepted, waiting for driver
  ACCEPTED_BY_DRIVER = 'ACCEPTED_BY_DRIVER', // Driver accepted, on the way to Store
  PICKED_UP = 'PICKED_UP',           // Driver got the order from store, on the way to Customer
  DELIVERED = 'DELIVERED',           // Complete
  CANCELLED = 'CANCELLED'
}

