  customerPhone?: string; 
  storeId: string;
  storeName: string;
  storePhone?: string; 
  driverId?: string;
  driverName?: string;
  driverPhone?: string;
  products: {product: Product, quantity: number}[];
  totalPrice: number;
  deliveryFee: number;
  status: OrderStatus;
  timestamp: number;
  address: string;
  notes?: string; // ملاحظات إضافية من الزبون
