const uploadImage = async (file: File): Promise<string | null> => {
  const formData = new FormData();
  formData.append("file", file);
  formData.append("upload_preset", "makemm");
  const cloudName = 'dkqxgwjnr';
  try {
    const res = await fetch(`https://api.cloudinary.com/v1_1/${cloudName}/image/upload`, {
      method: "POST",
      body: formData,
    });
    const data = await res.json();
    return data.secure_url || null;
  } catch (error) { return null; }
};

export const AuthScreen: React.FC<AuthScreenProps> = ({ onLogin }) => {
  const [selectedRole, setSelectedRole] = useState<UserRole | null>(null);
  const [authMode, setAuthMode] = useState<'LOGIN' | 'REGISTER'>('LOGIN');
  const [isLoading, setIsLoading] = useState(false);
  const [isUploading, setIsUploading] = useState(false);
  const [isLocating, setIsLocating] = useState(false);
  const [formData, setFormData] = useState({ 
    name: '', 
    email: '', 
    phone: '', 
    password: '', 
    wilaya: WILAYAS_ALGERIA[15], // الافتراضي الجزائر العاصمة
    storeImage: '',
    coords: null as {lat: number, lng: number} | null
  });
  const [error, setError] = useState('');

  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleRoleSelect = (role: UserRole) => {
    setSelectedRole(role);
    setAuthMode('LOGIN');
    setError('');
  };

  const handleBack = () => {
    setSelectedRole(null);
    setFormData({ name: '', email: '', phone: '', password: '', wilaya: WILAYAS_ALGERIA[15], storeImage: '', coords: null });
    setError('');
  };

  const handleGetLocation = () => {
    setIsLocating(true);
    setError('');
    if ("geolocation" in navigator) {
      navigator.geolocation.getCurrentPosition(
        (position) => {
          setFormData(prev => ({ 
            ...prev, 
            coords: { lat: position.coords.latitude, lng: position.coords.longitude } 
          }));
          setIsLocating(false);
        },
        () => {
          setIsLocating(false);
          setError("يرجى تفعيل GPS لتحديد موقعك بدقة على الخريطة.");
        },
        { enableHighAccuracy: true }
      );
    } else {
      setIsLocating(false);
      setError("متصفحك لا يدعم تحديد الموقع.");
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');

    if (authMode === 'REGISTER') {
      if (!formData.name || !formData.phone || !formData.email || !formData.password || !formData.wilaya) {
        setError('يرجى ملء كافة البيانات بما في ذلك الولاية.');
        return;
      }
    }

    setIsLoading(true);

    try {
      if (authMode === 'REGISTER') {
        const userCredential = await createUserWithEmailAndPassword(auth, formData.email, formData.password);
        const user = userCredential.user;
        const dbPath = selectedRole === UserRole.CUSTOMER ? 'customers' : selectedRole === UserRole.STORE ? 'stores' : 'drivers';

        const profileData: any = {
            id: user.uid,
            name: formData.name,
            email: formData.email,
            phone: formData.phone,
            role: selectedRole,
            wilaya: formData.wilaya,
            createdAt: Date.now(),
            coordinates: formData.coords || { lat: 36.7538, lng: 3.0588 } // الجزائر العاصمة افتراضياً
        };

        if (selectedRole === UserRole.STORE) {
            profileData.category = Category.FOOD;
            profileData.image = formData.storeImage || `https://picsum.photos/400/300?random=${user.uid.slice(0,5)}`;
            profileData.rating = 0;
            profileData.reviewCount = 0;
        }

        await set(ref(db, `${dbPath}/${user.uid}`), profileData);
        onLogin(selectedRole!, formData.name);
      } else {
        await signInWithEmailAndPassword(auth, formData.email, formData.password);
        onLogin(selectedRole || UserRole.CUSTOMER);
      }
    } catch (err: any) {
      setError('حدث خطأ: ' + err.message);
    } finally {
      setIsLoading(false);
    }
  };

  if (!selectedRole) {
    return (
      <div className="min-h-screen bg-[#0F172A] flex flex-col items-center justify-center p-4 font-cairo text-right" dir="rtl">
        <div className="text-center mb-12 animate-fade-in-up">
          <div className="bg-orange-500 w-24 h-24 rounded-[2.5rem] flex items-center justify-center mx-auto mb-6 shadow-2xl">
            <span className="text-white text-5xl font-black">K</span>
          </div>
          <h1 className="text-6xl font-black text-white mb-2 tracking-tight">كيمو</h1>
          <p className="text-slate-400 font-bold">تطبيق التوصيل الوطني الأول في الجزائر 🇩🇿</p>
        </div>
        <div className="grid grid-cols-1 gap-4 w-full max-w-sm">
          <RoleCard icon={<ShoppingBag/>} title="أنا زبون" desc="اطلب من أفضل متاجر ولايتك" onClick={() => handleRoleSelect(UserRole.CUSTOMER)} />
          <RoleCard icon={<Store/>} title="أنا متجر" desc="وسع تجارتك في كل الجزائر" onClick={() => handleRoleSelect(UserRole.STORE)} />
          <RoleCard icon={<Bike/>} title="أنا موصل" desc="كن شريكاً في التوصيل الوطني" onClick={() => handleRoleSelect(UserRole.DRIVER)} />
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-white flex items-center justify-center p-4 font-cairo text-right" dir="rtl">
      <div className="w-full max-w-md animate-scale-up">
        <button onClick={handleBack} className="flex items-center gap-2 text-slate-400 font-bold mb-6 text-sm"><ChevronLeft className="w-4 h-4 rotate-180" /> رجوع</button>
        <h2 className="text-4xl font-black text-slate-800 mb-2">{authMode === 'LOGIN' ? 'دخول' : 'حساب جديد'}</h2>
        <p className="text-slate-500 mb-8 font-bold">انضم لشبكة كيمو في {formData.wilaya}</p>

        <form onSubmit={handleSubmit} className="space-y-4">
          {error && <div className="bg-red-50 text-red-500 p-4 rounded-2xl text-xs font-black border border-red-100 flex items-center gap-2"><AlertCircle size={16}/> {error}</div>}

          {authMode === 'REGISTER' && (
            <>
              {selectedRole === UserRole.STORE && (
                <div className="flex flex-col items-center mb-6">
                  <div onClick={() => fileInputRef.current?.click()} className="w-24 h-24 rounded-[2rem] bg-slate-50 border-2 border-dashed border-slate-200 flex items-center justify-center cursor-pointer overflow-hidden relative">
                    {formData.storeImage ? <img src={formData.storeImage} className="w-full h-full object-cover" /> : <Camera className="text-slate-300" />}
                    {isUploading && <div className="absolute inset-0 bg-white/60 flex items-center justify-center"><Loader2 className="animate-spin text-orange-500" /></div>}
                  </div>
                  <input type="file" ref={fileInputRef} onChange={async (e) => {
                    const f = e.target.files?.[0];
                    if (f) { setIsUploading(true); const url = await uploadImage(f); if (url) setFormData({...formData, storeImage: url}); setIsUploading(false); }
                  }} className="hidden" accept="image/*" />
                </div>
              )}

              <div className="relative">
                <select 
                  value={formData.wilaya} 
                  onChange={e => setFormData({...formData, wilaya: e.target.value})}
                  className="w-full p-4 pr-12 bg-slate-50 border border-slate-100 rounded-2xl outline-none focus:border-orange-500 font-bold appearance-none shadow-sm cursor-pointer"
                >
                  {WILAYAS_ALGERIA.map(w => <option key={w} value={w}>{w}</option>)}
                </select>
                <Globe className="absolute right-4 top-4 text-slate-300 w-5 h-5 pointer-events-none" />
              </div>

              <div className="flex gap-2">
                <button 
                  type="button" 
                  onClick={handleGetLocation} 
                  className={`flex-1 flex items-center justify-center gap-2 p-4 rounded-2xl font-bold text-xs transition-all ${formData.coords ? 'bg-green-100 text-green-600 border border-green-200' : 'bg-slate-100 text-slate-600 border border-slate-200'}`}
                >
                  {isLocating ? <Loader2 className="animate-spin w-4 h-4" /> : formData.coords ? <><MapPin size={16}/> تم تحديد موقعك</> : <><Navigation size={16}/> تحديد موقعي GPS</>}
                </button>
              </div>

              <div className="relative">
                <input type="text" value={formData.name} onChange={e => setFormData({...formData, name: e.target.value})} className="w-full p-4 pr-12 bg-slate-50 border border-slate-100 rounded-2xl outline-none focus:border-orange-500 font-bold shadow-sm" placeholder="الاسم الكامل" />
                <User className="absolute right-4 top-4 text-slate-300 w-5 h-5" />
              </div>

              <div className="relative">
                <input type="tel" value={formData.phone} onChange={e => setFormData({...formData, phone: e.target.value})} className="w-full p-4 pr-12 bg-slate-50 border border-slate-100 rounded-2xl outline-none focus:border-orange-500 font-bold shadow-sm" placeholder="رقم الهاتف" />
                <Phone className="absolute right-4 top-4 text-slate-300 w-5 h-5" />
              </div>
            </>
          )}

          <div className="relative">
            <input type="email" value={formData.email} onChange={e => setFormData({...formData, email: e.target.value})} className="w-full p-4 pr-12 bg-slate-50 border border-slate-100 rounded-2xl outline-none focus:border-orange-500 font-bold shadow-sm" placeholder="البريد الإلكتروني" />
            <Mail className="absolute right-4 top-4 text-slate-300 w-5 h-5" />
          </div>

          <div className="relative">
            <input type="password" value={formData.password} onChange={e => setFormData({...formData, password: e.target.value})} className="w-full p-4 pr-12 bg-slate-50 border border-slate-100 rounded-2xl outline-none focus:border-orange-500 font-bold shadow-sm" placeholder="كلمة المرور" />
            <Lock className="absolute right-4 top-4 text-slate-300 w-5 h-5" />
          </div>

          <button type="submit" disabled={isLoading || isUploading} className="w-full bg-slate-900 text-white py-5 rounded-2xl font-black text-lg shadow-xl active:scale-95 transition-all">
            {isLoading ? <Loader2 className="animate-spin mx-auto" /> : (authMode === 'LOGIN' ? 'دخول' : 'ابدأ في كيمو')}
          </button>

          <button type="button" onClick={() => setAuthMode(authMode === 'LOGIN' ? 'REGISTER' : 'LOGIN')} className="w-full text-center text-slate-400 text-sm font-bold pt-4">
            {authMode === 'LOGIN' ? 'ليس لديك حساب؟ سجل ولايتك الآن' : 'لديك حساب؟ سجل دخولك'}
          </button>
        </form>
      </div>
    </div>
  );
};

