export const CustomerScreen: React.FC<{onLogout: () => void, userName: string}> = ({ onLogout, userName }) => {
  const [activeTab, setActiveTab] = useState<'HOME' | 'CATEGORIES' | 'ORDERS' | 'PROFILE'>('HOME');
  const [cart, setCart] = useState<{product: Product; quantity: number}[]>([]);
  const [isOrdering, setIsOrdering] = useState(false);
  const [stores, setStores] = useState<StoreProfile[]>([]);
  const [allProducts, setAllProducts] = useState<Product[]>([]);
  const [myOrders, setMyOrders] = useState<Order[]>([]);
  const [loading, setLoading] = useState(true);
  const [searchQuery, setSearchQuery] = useState('');
  const [selectedCategory, setSelectedCategory] = useState<string | null>(null);
  const [showCheckout, setShowCheckout] = useState(false);
  const [orderNotes, setOrderNotes] = useState('');

  const [trackingOrder, setTrackingOrder] = useState<Order | null>(null);
  const [ratingOrder, setRatingOrder] = useState<Order | null>(null);

  const [profileData, setProfileData] = useState({ name: '', phone: '', avatar: '', wilaya: '', coordinates: null as any });

  const user = auth.currentUser;

  useEffect(() => {
    if (!user) return;

    onValue(ref(db, `customers/${user.uid}`), (snap) => {
      if (snap.exists()) {
        const data = snap.val();
        setProfileData({ 
          name: data.name || '', 
          phone: data.phone || '',
          avatar: data.avatar || '',
          wilaya: data.wilaya || WILAYAS_ALGERIA[15],
          coordinates: data.coordinates || null
        });
      }
    });

    onValue(ref(db, 'stores'), (snap) => {
      const data = snap.val();
      if (data) setStores(Object.keys(data).map(k => ({ id: k, ...data[k] })));
    });

    onValue(ref(db, 'products'), (snap) => {
      const data = snap.val();
      if (data) setAllProducts(Object.keys(data).map(k => ({ id: k, ...data[k] })));
      setLoading(false);
    });

    onValue(ref(db, 'orders'), (snap) => {
      const data = snap.val();
      const list: Order[] = [];
      if (data) Object.keys(data).forEach(k => { if (data[k].customerId === user.uid) list.push({ id: k, ...data[k] }); });
      setMyOrders(list.sort((a, b) => b.timestamp - a.timestamp));
    });
  }, [user]);

  const addToCart = (p: Product) => {
    setCart(prev => {
      const ex = prev.find(i => i.product.id === p.id);
      if (ex) return prev.map(i => i.product.id === p.id ? {...i, quantity: i.quantity + 1} : i);
      return [...prev, { product: p, quantity: 1 }];
    });
  };

  const removeFromCart = (id: string) => {
    setCart(prev => prev.map(i => i.product.id === id ? {...i, quantity: i.quantity - 1} : i).filter(i => i.quantity > 0));
  };

  const handleCheckout = async () => {
    if (cart.length === 0 || !user) return;
    setIsOrdering(true);
    try {
      const storeId = cart[0].product.storeId;
      const store = stores.find(s => s.id === storeId);

      const orderData = {
        customerId: user.uid, 
        customerName: profileData.name || userName,
        storeId, 
        storeName: store?.name || "متجر كيمو",
        products: JSON.parse(JSON.stringify(cart)),
        totalPrice: cart.reduce((s, i) => s + (i.product.price * i.quantity), 0) + 200, 
        deliveryFee: 200,
        status: OrderStatus.PENDING, 
        timestamp: Date.now(),
        address: profileData.wilaya,
        wilaya: profileData.wilaya,
        notes: orderNotes.trim(),
        customerPhone: profileData.phone || '',
        coordinates: profileData.coordinates || { lat: 36.7538, lng: 3.0588 },
        storeCoordinates: store?.coordinates || { lat: 36.7538, lng: 3.0588 }
      };

      await set(push(ref(db, 'orders')), orderData);
      setCart([]); setShowCheckout(false); setActiveTab('ORDERS');
    } finally { setIsOrdering(false); }
  };

  const localStores = stores.filter(s => s.wilaya === profileData.wilaya);
  const localStoreIds = localStores.map(s => s.id);

  const filteredProducts = allProducts
    .filter(p => localStoreIds.includes(p.storeId))
    .filter(p => !selectedCategory || p.category === selectedCategory)
    .filter(p => p.name.toLowerCase().includes(searchQuery.toLowerCase()));

  if (loading) return <div className="h-screen flex items-center justify-center"><Loader2 className="animate-spin text-orange-500" /></div>;

  return (
    <div className="bg-[#F8FAFC] min-h-screen pb-40 font-cairo text-right" dir="rtl">

      {showCheckout && (
        <div className="fixed inset-0 z-[2000] bg-slate-900/60 backdrop-blur-sm flex items-end">
           <div className="w-full bg-white rounded-t-[3rem] p-8 animate-slide-up shadow-2xl flex flex-col max-h-[90vh]">
              <div className="w-12 h-1.5 bg-slate-100 rounded-full mx-auto mb-6"></div>
              <h3 className="text-2xl font-black text-slate-800 mb-6">تأكيد طلب {profileData.wilaya}</h3>
              <div className="flex-1 overflow-y-auto space-y-4 mb-6">
                 {cart.map(item => (
                   <div key={item.product.id} className="flex items-center gap-4 bg-slate-50 p-4 rounded-[2rem]">
                      <img src={item.product.image} className="w-16 h-16 rounded-2xl object-cover" />
                      <div className="flex-1">
                         <h4 className="font-bold text-slate-800 text-sm">{item.product.name}</h4>
                         <p className="text-orange-500 font-black text-xs">{formatCurrency(item.product.price)}</p>
                      </div>
                      <div className="flex items-center gap-3">
                         <button onClick={() => removeFromCart(item.product.id)} className="text-slate-400"><Minus size={14}/></button>
                         <span className="font-black text-sm">{item.quantity}</span>
                         <button onClick={() => addToCart(item.product)} className="text-orange-500"><Plus size={14}/></button>
                      </div>
                   </div>
                 ))}
                 <textarea placeholder="ملاحظات الموقع أو الطلب..." value={orderNotes} onChange={e => setOrderNotes(e.target.value)} className="w-full bg-slate-50 border rounded-2xl p-4 text-xs h-24 outline-none" />
              </div>
              <button onClick={handleCheckout} disabled={isOrdering} className="w-full brand-gradient text-white py-5 rounded-[2rem] font-black shadow-xl">
                {isOrdering ? <Loader2 className="animate-spin mx-auto" /> : 'إرسال الطلب الآن'}
              </button>
           </div>
        </div>
      )}

      <div className="bg-white sticky top-0 z-[100] px-4 pt-4 pb-2 shadow-sm border-b">
        <div className="flex items-center gap-3 mb-4">
          <div className="bg-orange-500 text-white p-2.5 rounded-full relative shadow-lg shadow-orange-500/20 active:scale-90 transition-all" onClick={() => setShowCheckout(true)}>
            <ShoppingCart className="w-5 h-5" />
            {cart.length > 0 && <span className="absolute -top-1 -right-1 bg-black text-[9px] w-4 h-4 rounded-full flex items-center justify-center border border-white">{cart.length}</span>}
          </div>
          <div className="relative flex-1">
            <input type="text" placeholder={`ابحث في محلات ${profileData.wilaya}...`} value={searchQuery} onChange={e => setSearchQuery(e.target.value)} className="w-full bg-[#F3F4F6] rounded-full py-2.5 pr-10 pl-4 text-xs font-bold outline-none border border-transparent focus:border-orange-500 transition-all" />
            <Search className="absolute right-3.5 top-2.5 w-4 h-4 text-slate-400" />
          </div>
        </div>
        <div className="flex items-center justify-between px-1 mb-2">
           <div className="flex items-center gap-2">
              <div className="w-2 h-2 bg-green-500 rounded-full animate-pulse"></div>
              <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">مباشر: {profileData.wilaya} 🇩🇿</span>
           </div>
           {profileData.coordinates && (
             <div className="flex items-center gap-1 text-orange-500">
                <MapPin size={10} />
                <span className="text-[9px] font-black">موقعك الجغرافي مفعل</span>
             </div>
           )}
        </div>
      </div>

      <main className="p-3 max-w-lg mx-auto">
        {activeTab === 'HOME' && (
          <div className="animate-fade-in-up">
              <div className="mb-6 rounded-[2.5rem] overflow-hidden shadow-2xl relative h-44 brand-gradient group">
                  <div className="absolute inset-0 bg-black/20 group-hover:bg-transparent transition-all"></div>
                  <div className="absolute inset-0 p-8 flex flex-col justify-center items-start text-white">
                     <h2 className="text-3xl font-black mb-2">كل الجزائر <br/>بين يديك</h2>
                     <p className="text-xs font-bold opacity-80">تطبيق كيمو يغطي {profileData.wilaya} بالكامل</p>
                  </div>
                  <Sparkles className="absolute left-8 top-1/2 -translate-y-1/2 text-white/20 w-32 h-32" />
              </div>

              {filteredProducts.length > 0 ? (
                <div className="grid grid-cols-2 gap-3">
                  {filteredProducts.map((p) => (
                    <div key={p.id} className="bg-white rounded-2xl overflow-hidden shadow-sm border border-slate-50 transition-all hover:shadow-md group">
                      <div className="relative h-40 bg-slate-50">
                        <img src={p.image} className="w-full h-full object-cover transition-transform group-hover:scale-110" />
                        <button onClick={() => addToCart(p)} className="absolute bottom-2 left-2 w-10 h-10 rounded-2xl brand-gradient text-white flex items-center justify-center shadow-lg active:scale-90 transition-all"><Plus size={20} /></button>
                      </div>
                      <div className="p-3">
                        <h4 className="text-[11px] font-bold text-slate-800 line-clamp-1 mb-1">{p.name}</h4>
                        <span className="text-orange-600 font-black text-sm">{formatCurrency(p.price)}</span>
                      </div>
                    </div>
                  ))}
                </div>
              ) : (
                <div className="flex flex-col items-center justify-center py-24 text-center opacity-40">
                   <div className="w-20 h-20 bg-slate-100 rounded-[2rem] flex items-center justify-center mb-4"><ShoppingBag size={32} /></div>
                   <h3 className="font-black text-lg">لا توجد متاجر في {profileData.wilaya}</h3>
                   <p className="text-xs font-bold">كن أول من ينضم لشبكتنا في هذه الولاية!</p>
                </div>
              )}
          </div>
        )}
        {/* ... بقية التبويبات ... */}
      </main>

      <nav className="fixed bottom-0 left-0 right-0 bg-white border-t h-20 flex justify-around items-center px-4 z-[500] shadow-lg">
        <NavBtn act={activeTab === 'HOME'} onClick={() => setActiveTab('HOME')} icon={<Home />} label="الرئيسية" />
        <NavBtn act={activeTab === 'CATEGORIES'} onClick={() => setActiveTab('CATEGORIES')} icon={<LayoutGrid />} label="الأقسام" />
        <NavBtn act={activeTab === 'ORDERS'} onClick={() => setActiveTab('ORDERS')} icon={<ClipboardList />} label="طلباتي" />
        <NavBtn act={activeTab === 'PROFILE'} onClick={() => setActiveTab('PROFILE')} icon={<User />} label="حسابي" />
      </nav>
    </div>
  );
};

