  <button onClick={onClick} className={`flex flex-col items-center gap-1.5 transition-all ${act ? 'text-orange-500' : 'text-slate-400'}`}>
    {React.cloneElement(icon, { size: 22, strokeWidth: act ? 3 : 2 })}
    <span className="text-[9px] font-black">{label}</span>
  </button>
