import React, { useState, useEffect, useRef } from 'react';
import { Category, Product, StoreProfile, OrderStatus, Order, Coordinates } from '../types';
import { formatCurrency, WILAYAS_ALGERIA } from '../utils/helpers';
import { db, auth } from '../services/firebase';
import { ref, onValue, push, set, update, off } from 'firebase/database';
import { 
  Search, Plus, Minus, ShoppingCart, MapPin, Loader2, Home, User, 
  Camera, LogOut, ClipboardList, Trash2, Star, ShieldCheck, Globe,
  LayoutGrid, Save, RefreshCw, Phone, Sparkles, Navigation, X, Bot, Send,
  ChevronLeft, ShoppingBag, Heart, Filter, CheckCircle2, Layout, Bike, PhoneCall,
  Clock, Map as MapIcon, Timer, Truck, ArrowRight, CheckCircle, Edit3, ShoppingBasket
} from 'lucide-react';

// وظيفة رفع الصور للسيرفر
const uploadImage = async (file: File): Promise<string | null> => {
  const formData = new FormData();
  formData.append("file", file);
  formData.append("upload_preset", "makemm");
  const cloudName = 'dkqxgwjnr';
  try {
    const res = await fetch(`https://api.cloudinary.com/v1_1/${cloudName}/image/upload`, {
      method: "POST",
      body: formData,
    });
    const data = await res.json();
    return data.secure_url || null;
  } catch (error) { return null; }
};

export const CustomerScreen: React.FC<{onLogout: () => void, userName: string}> = ({ onLogout, userName }) => {
  const [activeTab, setActiveTab] = useState<'HOME' | 'CATEGORIES' | 'ORDERS' | 'PROFILE'>('HOME');
  const [cart, setCart] = useState<{product: Product; quantity: number}[]>([]);
  const [isOrdering, setIsOrdering] = useState(false);
  const [stores, setStores] = useState<StoreProfile[]>([]);
  const [allProducts, setAllProducts] = useState<Product[]>([]);
  const [myOrders, setMyOrders] = useState<Order[]>([]);
  const [loading, setLoading] = useState(true);
  const [searchQuery, setSearchQuery] = useState('');
  const [selectedCategory, setSelectedCategory] = useState<string | null>(null);
  const [showCheckout, setShowCheckout] = useState(false);
  const [orderNotes, setOrderNotes] = useState('');

  // حالات تعديل البروفيل
  const [isEditingProfile, setIsEditingProfile] = useState(false);
  const [isUpdating, setIsUpdating] = useState(false);
  const [isUploading, setIsUploading] = useState(false);
  const [profileData, setProfileData] = useState({ name: '', phone: '', avatar: '', wilaya: '', coordinates: null as any });
  const fileInputRef = useRef<HTMLInputElement>(null);

  const user = auth.currentUser;

  useEffect(() => {
    if (!user) return;

    // جلب بيانات المستخدم
    const userRef = ref(db, `customers/${user.uid}`);
    onValue(userRef, (snap) => {
      if (snap.exists()) {
        const data = snap.val();
        setProfileData({ 
          name: data.name || userName, 
          phone: data.phone || '',
          avatar: data.avatar || '',
          wilaya: data.wilaya || WILAYAS_ALGERIA[15],
          coordinates: data.coordinates || null
        });
      }
    });

    onValue(ref(db, 'stores'), (snap) => {
      const data = snap.val();
      if (data) setStores(Object.keys(data).map(k => ({ id: k, ...data[k] })));
    });

    onValue(ref(db, 'products'), (snap) => {
      const data = snap.val();
      if (data) setAllProducts(Object.keys(data).map(k => ({ id: k, ...data[k] })));
      setLoading(false);
    });

    onValue(ref(db, 'orders'), (snap) => {
      const data = snap.val();
      const list: Order[] = [];
      if (data) Object.keys(data).forEach(k => { if (data[k].customerId === user.uid) list.push({ id: k, ...data[k] }); });
      setMyOrders(list.sort((a, b) => b.timestamp - a.timestamp));
    });
  }, [user]);

  const handleUpdateProfile = async () => {
    if (!user) return;
    setIsUpdating(true);
    try {
      await update(ref(db, `customers/${user.uid}`), {
        name: profileData.name,
        phone: profileData.phone,
        avatar: profileData.avatar,
        wilaya: profileData.wilaya,
        coordinates: profileData.coordinates
      });
      setIsEditingProfile(false);
    } catch (e) {
      alert("فشل تحديث البيانات");
    } finally {
      setIsUpdating(false);
    }
  };

  const handleUpdateLocation = () => {
    if ("geolocation" in navigator) {
      navigator.geolocation.getCurrentPosition((pos) => {
        setProfileData(prev => ({ ...prev, coordinates: { lat: pos.coords.latitude, lng: pos.coords.longitude } }));
        alert("تم تحديث موقعك الجغرافي بنجاح");
      });
    }
  };

  const addToCart = (p: Product) => {
    setCart(prev => {
      const ex = prev.find(i => i.product.id === p.id);
      if (ex) return prev.map(i => i.product.id === p.id ? {...i, quantity: i.quantity + 1} : i);
      return [...prev, { product: p, quantity: 1 }];
    });
  };

  const removeFromCart = (id: string) => {
    setCart(prev => prev.map(i => i.product.id === id ? {...i, quantity: i.quantity - 1} : i).filter(i => i.quantity > 0));
  };

  const handleCheckout = async () => {
    if (cart.length === 0 || !user) return;
    setIsOrdering(true);
    try {
      const storeId = cart[0].product.storeId;
      const store = stores.find(s => s.id === storeId);
      const orderData = {
        customerId: user.uid, 
        customerName: profileData.name,
        storeId, 
        storeName: store?.name || "متجر كيمو",
        products: JSON.parse(JSON.stringify(cart)),
        totalPrice: cart.reduce((s, i) => s + (i.product.price * i.quantity), 0) + 200, 
        deliveryFee: 200,
        status: OrderStatus.PENDING, 
        timestamp: Date.now(),
        address: profileData.wilaya,
        wilaya: profileData.wilaya,
        notes: orderNotes.trim(),
        customerPhone: profileData.phone,
        coordinates: profileData.coordinates || { lat: 36.7538, lng: 3.0588 },
        storeCoordinates: store?.coordinates || { lat: 36.7538, lng: 3.0588 }
      };
      await set(push(ref(db, 'orders')), orderData);
      setCart([]); setShowCheckout(false); setActiveTab('ORDERS');
    } finally { setIsOrdering(false); }
  };

  const localStores = stores.filter(s => s.wilaya === profileData.wilaya);
  const localStoreIds = localStores.map(s => s.id);
  const filteredProducts = allProducts
    .filter(p => localStoreIds.includes(p.storeId))
    .filter(p => !selectedCategory || p.category === selectedCategory)
    .filter(p => p.name.toLowerCase().includes(searchQuery.toLowerCase()));

  if (loading) return <div className="h-screen flex items-center justify-center"><Loader2 className="animate-spin text-orange-500" /></div>;

  return (
    <div className="bg-[#F8FAFC] min-h-screen pb-40 font-cairo text-right" dir="rtl">

      <div className="bg-white sticky top-0 z-[100] px-4 pt-4 pb-2 shadow-sm border-b">
        <div className="flex items-center gap-3 mb-4">
          <div className="bg-orange-500 text-white p-2.5 rounded-full relative shadow-lg active:scale-90 transition-all" onClick={() => setShowCheckout(true)}>
            <ShoppingCart className="w-5 h-5" />
            {cart.length > 0 && <span className="absolute -top-1 -right-1 bg-black text-[9px] w-4 h-4 rounded-full flex items-center justify-center border border-white">{cart.length}</span>}
          </div>
          <div className="relative flex-1">
            <input type="text" placeholder={`ابحث في ${profileData.wilaya}...`} value={searchQuery} onChange={e => setSearchQuery(e.target.value)} className="w-full bg-[#F3F4F6] rounded-full py-2.5 pr-10 pl-4 text-xs font-bold outline-none border border-transparent focus:border-orange-500 transition-all" />
            <Search className="absolute right-3.5 top-2.5 w-4 h-4 text-slate-400" />
          </div>
        </div>
      </div>

      <main className="p-3 max-w-lg mx-auto">
        {activeTab === 'HOME' && (
          <div className="animate-fade-in-up">
            <div className="grid grid-cols-2 gap-3">
              {filteredProducts.map((p) => (
                <div key={p.id} className="bg-white rounded-2xl overflow-hidden shadow-sm border border-slate-50 transition-all hover:shadow-md group">
                  <div className="relative h-40 bg-slate-50">
                    <img src={p.image} className="w-full h-full object-cover transition-transform group-hover:scale-110" />
                    <button onClick={() => addToCart(p)} className="absolute bottom-2 left-2 w-10 h-10 rounded-2xl bg-orange-500 text-white flex items-center justify-center shadow-lg active:scale-90 transition-all"><Plus size={20} /></button>
                  </div>
                  <div className="p-3">
                    <h4 className="text-[11px] font-bold text-slate-800 line-clamp-1 mb-1">{p.name}</h4>
                    <span className="text-orange-600 font-black text-sm">{formatCurrency(p.price)}</span>
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}

        {activeTab === 'PROFILE' && (
          <div className="animate-fade-in-up">
             <div className="bg-white p-8 rounded-[3rem] shadow-sm border text-center relative overflow-hidden">
                {!isEditingProfile ? (
                  <>
                    <div className="w-28 h-28 bg-slate-100 rounded-[2.5rem] mx-auto mb-6 border-4 border-white shadow-xl overflow-hidden relative">
                       {profileData.avatar ? <img src={profileData.avatar} className="w-full h-full object-cover" /> : <User size={40} className="m-auto mt-8 text-slate-300" />}
                    </div>
                    <h3 className="text-2xl font-black mb-1">{profileData.name}</h3>
                    <p className="text-xs text-orange-500 font-bold mb-8">{profileData.wilaya} 🇩🇿</p>
                    <div className="space-y-3">
                       <button onClick={() => setIsEditingProfile(true)} className="w-full bg-slate-900 text-white py-4 rounded-2xl font-black text-sm flex items-center justify-center gap-2"><Edit3 size={18} /> تعديل الحساب</button>
                       <button onClick={onLogout} className="w-full bg-red-50 text-red-500 py-4 rounded-2xl font-black text-sm">تسجيل خروج</button>
                    </div>
                  </>
                ) : (
                  <div className="space-y-4 text-right">
                    <h3 className="text-xl font-black mb-6 text-center">تعديل بياناتي</h3>

                    <div className="flex flex-col items-center mb-4">
                       <div onClick={() => fileInputRef.current?.click()} className="w-24 h-24 rounded-[2rem] bg-slate-50 border-2 border-dashed flex items-center justify-center cursor-pointer overflow-hidden relative">
                         {profileData.avatar ? <img src={profileData.avatar} className="w-full h-full object-cover" /> : <Camera className="text-slate-300" />}
                         {isUploading && <div className="absolute inset-0 bg-white/60 flex items-center justify-center"><Loader2 className="animate-spin text-orange-500" /></div>}
                       </div>
                       <input type="file" ref={fileInputRef} onChange={async (e) => {
                         const f = e.target.files?.[0];
                         if (f) { setIsUploading(true); const url = await uploadImage(f); if (url) setProfileData({...profileData, avatar: url}); setIsUploading(false); }
                       }} className="hidden" accept="image/*" />
                    </div>

                    <div className="space-y-1">
                      <label className="text-[10px] font-black text-slate-400 px-2">الاسم</label>
                      <input type="text" value={profileData.name} onChange={e => setProfileData({...profileData, name: e.target.value})} className="w-full p-4 bg-slate-50 rounded-2xl font-bold outline-none" />
                    </div>

                    <div className="space-y-1">
                      <label className="text-[10px] font-black text-slate-400 px-2">الهاتف</label>
                      <input type="tel" value={profileData.phone} onChange={e => setProfileData({...profileData, phone: e.target.value})} className="w-full p-4 bg-slate-50 rounded-2xl font-bold outline-none" />
                    </div>

                    <div className="space-y-1">
                      <label className="text-[10px] font-black text-slate-400 px-2">الولاية</label>
                      <select value={profileData.wilaya} onChange={e => setProfileData({...profileData, wilaya: e.target.value})} className="w-full p-4 bg-slate-50 rounded-2xl font-bold outline-none appearance-none">
                        {WILAYAS_ALGERIA.map(w => <option key={w} value={w}>{w}</option>)}
                      </select>
                    </div>

                    <button onClick={handleUpdateLocation} className="w-full bg-blue-50 text-blue-600 py-3 rounded-2xl font-black text-xs flex items-center justify-center gap-2"><Navigation size={14} /> تحديث موقع GPS</button>

                    <div className="flex gap-2 pt-4">
                       <button onClick={handleUpdateProfile} disabled={isUpdating} className="flex-1 bg-orange-500 text-white py-4 rounded-2xl font-black shadow-lg">
                         {isUpdating ? <Loader2 className="animate-spin mx-auto" /> : 'حفظ'}
                       </button>
                       <button onClick={() => setIsEditingProfile(false)} className="px-6 bg-slate-100 text-slate-400 py-4 rounded-2xl font-black">إلغاء</button>
                    </div>
                  </div>
                )}
             </div>
          </div>
        )}
      </main>

      <nav className="fixed bottom-0 left-0 right-0 bg-white border-t h-20 flex justify-around items-center px-4 z-[500] shadow-lg">
        <NavBtn act={activeTab === 'HOME'} onClick={() => setActiveTab('HOME')} icon={<Home />} label="الرئيسية" />
        <NavBtn act={activeTab === 'CATEGORIES'} onClick={() => setActiveTab('CATEGORIES')} icon={<LayoutGrid />} label="الأقسام" />
        <NavBtn act={activeTab === 'ORDERS'} onClick={() => setActiveTab('ORDERS')} icon={<ClipboardList />} label="طلباتي" />
        <NavBtn act={activeTab === 'PROFILE'} onClick={() => setActiveTab('PROFILE')} icon={<User />} label="حسابي" />
      </nav>
    </div>
  );
};

const NavBtn = ({ act, onClick, icon, label }: any) => (
  <button onClick={onClick} className={`flex flex-col items-center gap-1.5 transition-all ${act ? 'text-orange-500' : 'text-slate-400'}`}>
    {React.cloneElement(icon, { size: 22, strokeWidth: act ? 3 : 2 })}
    <span className="text-[9px] font-black">{label}</span>
