export const DriverScreen: React.FC<{onLogout: () => void, userName: string}> = ({ onLogout, userName }) => {
  const [activeTab, setActiveTab] = useState<'AVAILABLE' | 'ACTIVE' | 'PROFILE'>('AVAILABLE');
  const [availableOrders, setAvailableOrders] = useState<Order[]>([]);
  const [activeOrder, setActiveOrder] = useState<Order | null>(null);
  const [loading, setLoading] = useState(true);

  // حالات تعديل البروفيل
  const [isEditingProfile, setIsEditingProfile] = useState(false);
  const [isUpdating, setIsUpdating] = useState(false);
  const [isUploading, setIsUploading] = useState(false);
  const [driverProfile, setDriverProfile] = useState<any>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const currentDriverId = auth.currentUser?.uid;

  useEffect(() => {
    if (!currentDriverId) return;

    onValue(ref(db, `drivers/${currentDriverId}`), (snap) => {
      if (snap.exists()) setDriverProfile(snap.val());
    });

    onValue(ref(db, 'orders'), (snapshot) => {
        const data = snapshot.val();
        const available: Order[] = [];
        let myActive: Order | null = null;
        if (data && driverProfile) {
            Object.keys(data).forEach(key => {
                const order = { ...data[key], id: key } as Order;
                if (order.driverId === currentDriverId && order.status !== OrderStatus.DELIVERED) myActive = order;
                if (order.status === OrderStatus.ACCEPTED_BY_STORE && !order.driverId && order.wilaya === driverProfile.wilaya) {
                  available.push(order);
                }
            });
        }
        setAvailableOrders(available);
        setActiveOrder(myActive);
        setLoading(false);
    });
  }, [currentDriverId, driverProfile]);

  const handleUpdateProfile = async () => {
    if (!currentDriverId) return;
    setIsUpdating(true);
    try {
      await update(ref(db, `drivers/${currentDriverId}`), {
        name: driverProfile.name,
        phone: driverProfile.phone,
        avatar: driverProfile.avatar,
        wilaya: driverProfile.wilaya,
        coordinates: driverProfile.coordinates
      });
      setIsEditingProfile(false);
    } catch (e) {
      alert("فشل التحديث");
    } finally {
      setIsUpdating(false);
    }
  };

  const handleUpdateLocation = () => {
    if ("geolocation" in navigator) {
      navigator.geolocation.getCurrentPosition((pos) => {
        setDriverProfile({...driverProfile, coordinates: { lat: pos.coords.latitude, lng: pos.coords.longitude } });
        alert("تم تحديث موقعك كشريك توصيل");
      });
    }
  };

  const handleAcceptOrder = async (orderId: string) => {
      if (!currentDriverId) return;
      try {
        await update(ref(db, `orders/${orderId}`), {
            status: OrderStatus.ACCEPTED_BY_DRIVER,
            driverId: currentDriverId,
            driverName: driverProfile?.name || userName,
            driverPhone: driverProfile?.phone || ''
        });
        setActiveTab('ACTIVE');
      } catch (error) {
        alert("فشل في قبول المهمة.");
      }
  };

  if (loading) return <div className="h-screen flex items-center justify-center bg-white"><Loader2 className="animate-spin text-orange-500 w-12 h-12" /></div>;

  return (
    <div className="bg-[#F4F4F4] min-h-screen pb-32 font-cairo text-right" dir="rtl">
       <header className="bg-white sticky top-0 z-[100] px-6 pt-8 pb-4 shadow-sm">
          <div className="flex justify-between items-center">
             <h1 className="text-2xl font-black text-slate-800">كيمو موصلين</h1>
             {driverProfile?.avatar && <img src={driverProfile.avatar} className="w-10 h-10 rounded-xl object-cover" />}
          </div>
       </header>

       <main className="p-4 max-w-lg mx-auto">
         {activeTab === 'AVAILABLE' && (
           <div className="animate-fade-in-up space-y-4">
              <h2 className="text-xl font-black px-2">طلبات {driverProfile?.wilaya}</h2>
              {availableOrders.map(o => (
                <div key={o.id} className="bg-white p-6 rounded-[2.5rem] shadow-sm border border-slate-50 relative group">
                   <div className="flex justify-between items-start mb-4">
                      <div className="flex items-center gap-3">
                         <div className="w-12 h-12 bg-slate-50 rounded-2xl flex items-center justify-center text-orange-500"><StoreIcon size={24} /></div>
                         <div>
                            <h4 className="font-black text-slate-800">{o.storeName}</h4>
                            <p className="text-[9px] text-slate-400 font-bold uppercase">{o.address}</p>
                         </div>
                      </div>
                      <span className="text-lg font-black text-orange-600">{formatCurrency(o.totalPrice)}</span>
                   </div>
                   <button onClick={() => handleAcceptOrder(o.id)} className="w-full bg-slate-900 text-white py-4 rounded-2xl font-black text-sm shadow-xl">قبول المهمة</button>
                </div>
              ))}
           </div>
         )}

         {activeTab === 'PROFILE' && (
           <div className="animate-fade-in-up">
              <div className="bg-white p-10 rounded-[3rem] shadow-sm border text-center">
                 {!isEditingProfile ? (
                   <>
                    <div className="w-28 h-28 rounded-[2.2rem] border-4 border-white shadow-xl mx-auto mb-6 bg-slate-50 overflow-hidden relative">
                       {driverProfile?.avatar ? <img src={driverProfile.avatar} className="w-full h-full object-cover" /> : <User size={40} className="m-auto mt-8 text-slate-200" />}
                    </div>
                    <h3 className="text-2xl font-black mb-1">{driverProfile?.name}</h3>
                    <p className="text-xs text-orange-500 font-bold mb-8">{driverProfile?.wilaya} 🏍️</p>
                    <div className="space-y-3">
                       <button onClick={() => setIsEditingProfile(true)} className="w-full bg-slate-900 text-white py-4 rounded-2xl font-black text-sm flex items-center justify-center gap-2"><Edit3 size={18} /> تعديل الحساب</button>
                       <button onClick={onLogout} className="w-full bg-red-50 text-red-500 py-4 rounded-2xl font-black text-sm">خروج</button>
                    </div>
                   </>
                 ) : (
                   <div className="space-y-4 text-right">
                      <h3 className="text-xl font-black mb-6 text-center">تعديل حساب الموصل</h3>
                      <div className="flex flex-col items-center mb-4">
                         <div onClick={() => fileInputRef.current?.click()} className="w-24 h-24 rounded-[2rem] bg-slate-50 border-2 border-dashed flex items-center justify-center cursor-pointer overflow-hidden relative">
                           {driverProfile.avatar ? <img src={driverProfile.avatar} className="w-full h-full object-cover" /> : <Camera className="text-slate-300" />}
                           {isUploading && <div className="absolute inset-0 bg-white/60 flex items-center justify-center"><Loader2 className="animate-spin text-orange-500" /></div>}
                         </div>
                         <input type="file" ref={fileInputRef} onChange={async (e) => {
                           const f = e.target.files?.[0];
                           if (f) { setIsUploading(true); const url = await uploadImage(f); if (url) setDriverProfile({...driverProfile, avatar: url}); setIsUploading(false); }
                         }} className="hidden" accept="image/*" />
                      </div>
                      <input type="text" value={driverProfile.name} onChange={e => setDriverProfile({...driverProfile, name: e.target.value})} className="w-full p-4 bg-slate-50 rounded-2xl font-bold" placeholder="الاسم" />
                      <input type="tel" value={driverProfile.phone} onChange={e => setDriverProfile({...driverProfile, phone: e.target.value})} className="w-full p-4 bg-slate-50 rounded-2xl font-bold" placeholder="رقم الهاتف" />
                      <select value={driverProfile.wilaya} onChange={e => setDriverProfile({...driverProfile, wilaya: e.target.value})} className="w-full p-4 bg-slate-50 rounded-2xl font-bold appearance-none">
                        {WILAYAS_ALGERIA.map(w => <option key={w} value={w}>{w}</option>)}
                      </select>
                      <button onClick={handleUpdateLocation} className="w-full bg-blue-50 text-blue-600 py-3 rounded-2xl font-black text-xs flex items-center justify-center gap-2"><Navigation size={14} /> تحديث موقع العمل (GPS)</button>
                      <div className="flex gap-2 pt-4">
                         <button onClick={handleUpdateProfile} disabled={isUpdating} className="flex-1 bg-orange-500 text-white py-4 rounded-2xl font-black">
                           {isUpdating ? <Loader2 className="animate-spin mx-auto" /> : 'حفظ'}
                         </button>
                         <button onClick={() => setIsEditingProfile(false)} className="px-6 bg-slate-100 text-slate-400 py-4 rounded-2xl font-black">إلغاء</button>
                      </div>
                   </div>
                 )}
              </div>
           </div>
         )}
       </main>

       <nav className="fixed bottom-0 left-0 right-0 bg-white border-t border-slate-100 h-20 flex justify-around items-center px-4 z-[500] shadow-lg">
         <NavBtn act={activeTab === 'AVAILABLE'} onClick={() => setActiveTab('AVAILABLE')} icon={<LayoutGrid />} label="طلبات الولاية" />
         <NavBtn act={activeTab === 'ACTIVE'} onClick={() => setActiveTab('ACTIVE')} icon={<MapIcon />} label="المهمة" />
         <NavBtn act={activeTab === 'PROFILE'} onClick={() => setActiveTab('PROFILE')} icon={<User />} label="حسابي" />
       </nav>
    </div>
  );
};

