  const askAi = async () => {
    if (!aiQuery.trim()) return;
    const q = aiQuery;
    setAiQuery('');
    setAiMessages(prev => [...prev, {role: 'user', text: q}]);
    setAiLoading(true);
    const res = await getKimoAssistantResponse(q, stores);
    setAiMessages(prev => [...prev, {role: 'ai', text: res}]);
    setAiLoading(false);
  };

  const handleUpdateProfile = async () => {
    if (!user) return;
    setIsUpdating(true);
    try {
      await update(ref(db, `customers/${user.uid}`), {
        name: profileData.name, phone: profileData.phone,
        avatar: profileData.avatar, wilaya: profileData.wilaya,
        coordinates: profileData.coordinates
