  const [aiMessages, setAiMessages] = useState<{role: 'ai'|'user', text: string}[]>([]);
  const [aiLoading, setAiLoading] = useState(false);

  const [profileData, setProfileData] = useState({ name: '', phone: '', avatar: '', wilaya: '', coordinates: null as any });
  const user = auth.currentUser;

  useEffect(() => {
    if (!user) return;
    onValue(ref(db, `customers/${user.uid}`), (snap) => {
      if (snap.exists()) setProfileData(snap.val());
    });
    onValue(ref(db, 'stores'), (snap) => {
      const data = snap.val();
      if (data) setStores(Object.keys(data).map(k => ({ id: k, ...data[k] })));
    });
    onValue(ref(db, 'products'), (snap) => {
      const data = snap.val();
      if (data) setAllProducts(Object.keys(data).map(k => ({ id: k, ...data[k] })));
      setLoading(false);
    });
    onValue(ref(db, 'orders'), (snap) => {
      const data = snap.val();
      const list: Order[] = [];
      if (data) Object.keys(data).forEach(k => { if (data[k].customerId === user.uid) list.push({ id: k, ...data[k] }); });
      setMyOrders(list.sort((a, b) => b.timestamp - a.timestamp));
    });
  }, [user]);

  const addToCart = (p: Product) => {
    // منع خلط المتاجر
    if (cart.length > 0 && cart[0].product.storeId !== p.storeId) {
      if (window.confirm("لا يمكنك الطلب من متجرين في نفس الوقت. هل تريد تفريغ السلة الحالية والبدء من هذا المتجر؟")) {
        setCart([{ product: p, quantity: 1 }]);
      }
      return;
    }

    setCart(prev => {
      const ex = prev.find(i => i.product.id === p.id);
      if (ex) return prev.map(i => i.product.id === p.id ? {...i, quantity: i.quantity + 1} : i);
      return [...prev, { product: p, quantity: 1 }];
    });
    setSelectedProduct(null);
  };

  const activeOrders = myOrders.filter(o => o.status !== OrderStatus.DELIVERED && o.status !== OrderStatus.CANCELLED);
  const localStores = stores.filter(s => s.wilaya === profileData.wilaya);
  const filteredProducts = allProducts
    .filter(p => localStores.some(s => s.id === p.storeId))
    .filter(p => !selectedCategory || p.category === selectedCategory)
    .filter(p => p.name.toLowerCase().includes(searchQuery.toLowerCase()));

  if (loading) return <div className="h-screen flex items-center justify-center bg-white"><Loader2 className="animate-spin text-orange-500 w-12 h-12" /></div>;

  return (
    <div className="bg-[#F8FAFC] min-h-screen pb-40 font-cairo text-right" dir="rtl">

      {/* مساعد كيمو - احترافي */}
      <div className="fixed bottom-24 left-6 z-[1000]">
        <button onClick={() => setShowAi(!showAi)} className="w-14 h-14 brand-gradient rounded-full flex items-center justify-center text-white shadow-2xl animate-pulse"><Bot size={28} /></button>
        {showAi && (
          <div className="absolute bottom-16 left-0 w-80 bg-white rounded-[2.5rem] shadow-2xl border border-slate-100 overflow-hidden animate-scale-up">
            <div className="bg-slate-900 p-4 text-white flex justify-between items-center">
              <div className="flex items-center gap-2"><Bot size={18} className="text-orange-500" /> <span className="text-xs font-black">كيمو AI</span></div>
              <X size={18} onClick={() => setShowAi(false)} className="cursor-pointer" />
            </div>
            <div className="h-64 overflow-y-auto p-4 space-y-3 bg-slate-50 text-[10px] font-bold">
               {aiMessages.map((m, i) => (
                 <div key={i} className={`p-3 rounded-2xl ${m.role === 'ai' ? 'bg-white text-slate-700' : 'bg-orange-500 text-white self-end text-left'}`}>{m.text}</div>
               ))}
               {aiLoading && <div className="animate-pulse text-slate-400">جاري التفكير...</div>}
            </div>
            <div className="p-3 bg-white flex gap-2 border-t">
               <input type="text" placeholder="اسأل كيمو عن الأكل..." className="flex-1 bg-slate-100 rounded-xl px-4 text-xs outline-none" onKeyPress={async (e) => {
                 if (e.key === 'Enter') {
                   const q = (e.target as HTMLInputElement).value;
                   setAiMessages(p => [...p, {role: 'user', text: q}]);
                   setAiLoading(true);
                   (e.target as HTMLInputElement).value = '';
                   const res = await getKimoAssistantResponse(q, stores);
                   setAiMessages(p => [...p, {role: 'ai', text: res}]);
                   setAiLoading(false);
                 }
               }} />
            </div>
          </div>
        )}
      </div>

      {/* نافذة تفاصيل المنتج - احترافية */}
      {selectedProduct && (
        <div className="fixed inset-0 z-[2000] bg-black/60 backdrop-blur-sm flex items-end justify-center">
           <div className="bg-white w-full max-w-md rounded-t-[3rem] p-8 animate-fade-in-up">
              <div className="flex justify-between items-start mb-6">
                 <button onClick={() => setSelectedProduct(null)} className="p-2 bg-slate-100 rounded-full"><X size={20}/></button>
                 <div className="bg-orange-50 text-orange-600 px-4 py-1 rounded-full text-[10px] font-black">{selectedProduct.category}</div>
              </div>
              <img src={selectedProduct.image} className="w-full h-64 object-cover rounded-[2.5rem] mb-6 shadow-xl" />
              <h2 className="text-2xl font-black text-slate-800 mb-2">{selectedProduct.name}</h2>
              <p className="text-sm text-slate-400 font-bold mb-8 leading-relaxed">{selectedProduct.description}</p>
              <div className="flex items-center justify-between">
                 <span className="text-2xl font-black text-orange-600">{formatCurrency(selectedProduct.price)}</span>
                 <button onClick={() => addToCart(selectedProduct)} className="bg-slate-900 text-white px-8 py-4 rounded-2xl font-black flex items-center gap-2 shadow-xl active:scale-95 transition-all">
                    <Plus size={20} /> إضافة للسلة
                 </button>
              </div>
           </div>
        </div>
      )}

      <header className="bg-white sticky top-0 z-[100] px-6 pt-8 pb-4 border-b border-slate-50">
        <div className="flex justify-between items-center mb-6">
           <div className="flex items-center gap-3">
              <div className="w-12 h-12 rounded-2xl bg-orange-500 flex items-center justify-center text-white font-black text-xl shadow-lg shadow-orange-200">K</div>
              <div>
                 <p className="text-[10px] font-black text-slate-400 uppercase">موقعك في</p>
                 <h2 className="text-sm font-black text-slate-800">{profileData.wilaya}</h2>
              </div>
           </div>
           <div className="flex gap-2">
              <div onClick={() => setShowCheckout(true)} className="p-3 bg-white border border-slate-100 rounded-2xl relative shadow-sm">
                 <ShoppingBag size={20} className="text-slate-800" />
                 {cart.length > 0 && <span className="absolute -top-1 -right-1 bg-orange-500 text-white w-5 h-5 rounded-full text-[10px] flex items-center justify-center font-black border-2 border-white">{cart.length}</span>}
              </div>
           </div>
        </div>
        <div className="relative">
           <input type="text" placeholder="ماذا تريد أن تأكل اليوم؟" value={searchQuery} onChange={e => setSearchQuery(e.target.value)} className="w-full bg-slate-50 rounded-2xl py-4 pr-12 pl-4 text-xs font-bold outline-none border border-transparent focus:border-orange-500 transition-all" />
           <Search className="absolute right-4 top-4 text-slate-400" size={20} />
        </div>
      </header>

      <main className="p-4 max-w-lg mx-auto space-y-8">
        {activeTab === 'HOME' && (
          <div className="space-y-8">
            {/* التتبع الحي بالخريطة - قمة الاحترافية */}
            {activeOrders.length > 0 && (
              <div className="space-y-4">
                 <h3 className="text-sm font-black text-slate-800 px-2 flex items-center gap-2 animate-pulse"><Zap size={14} className="text-orange-500" /> طلباتك الحالية</h3>
                 {activeOrders.map(o => (
                   <div key={o.id} className="bg-white rounded-[2.5rem] overflow-hidden shadow-xl border border-white">
                      <div className="h-32 relative">
                         <MapVisualizer storeLocation={o.storeCoordinates} customerLocation={o.coordinates} zoom={13} height="h-32" />
                      </div>
                      <div className="p-5 flex justify-between items-center">
                         <div className="flex items-center gap-3">
                            <div className="w-10 h-10 bg-slate-900 rounded-xl flex items-center justify-center text-white"><Truck size={20} /></div>
                            <div>
                               <h4 className="text-xs font-black text-slate-800">{o.storeName}</h4>
                               <p className="text-[9px] text-orange-500 font-black uppercase tracking-widest">{o.status}</p>
                            </div>
                         </div>
                         <button onClick={() => setActiveTab('ORDERS')} className="p-2 bg-slate-50 rounded-xl"><ChevronRight size={18} /></button>
                      </div>
                   </div>
                 ))}
              </div>
            )}

            <div className="flex gap-4 overflow-x-auto pb-4 scrollbar-hide">
               {Object.values(Category).map(cat => (
                 <button key={cat} onClick={() => setSelectedCategory(cat === selectedCategory ? null : cat)} className={`px-6 py-3 rounded-2xl text-xs font-black whitespace-nowrap transition-all ${selectedCategory === cat ? 'bg-orange-500 text-white shadow-lg shadow-orange-200' : 'bg-white text-slate-500 border border-slate-100'}`}>{cat}</button>
               ))}
            </div>

            <div className="grid grid-cols-2 gap-4">
               {filteredProducts.map(p => (
                 <div key={p.id} onClick={() => setSelectedProduct(p)} className="bg-white rounded-[2rem] p-3 shadow-sm border border-slate-50 group active:scale-95 transition-all">
                    <img src={p.image} className="w-full h-36 object-cover rounded-2xl mb-3" />
                    <h4 className="text-[11px] font-black text-slate-800 mb-1">{p.name}</h4>
                    <div className="flex items-center justify-between">
                       <span className="text-xs font-black text-orange-600">{formatCurrency(p.price)}</span>
                       <div className="w-7 h-7 bg-slate-900 text-white rounded-lg flex items-center justify-center"><Plus size={14} /></div>
                    </div>
                 </div>
               ))}
            </div>
          </div>
        )}
      </main>

      <nav className="fixed bottom-0 left-0 right-0 bg-white/80 backdrop-blur-xl border-t h-20 flex justify-around items-center px-4 z-[500] shadow-2xl">
        <NavBtn act={activeTab === 'HOME'} onClick={() => setActiveTab('HOME')} icon={<Home />} label="كيمو" />
        <NavBtn act={activeTab === 'CATEGORIES'} onClick={() => setActiveTab('CATEGORIES')} icon={<LayoutGrid />} label="الأقسام" />
        <NavBtn act={activeTab === 'ORDERS'} onClick={() => setActiveTab('ORDERS')} icon={<ClipboardList />} label="طلباتي" />
        <NavBtn act={activeTab === 'PROFILE'} onClick={() => setActiveTab('PROFILE')} icon={<User />} label="حسابي" />
      </nav>
    </div>
  );
};

const NavBtn = ({ act, onClick, icon, label }: any) => (
  <button onClick={onClick} className={`flex flex-col items-center gap-1.5 transition-all ${act ? 'text-orange-500 scale-110' : 'text-slate-400'}`}>
    {React.cloneElement(icon, { size: 22, strokeWidth: act ? 3 : 2 })}
    <span className="text-[9px] font-black">{label}</span>
