);

import React, { useState, useEffect, useRef } from 'react';
import { 
  MapPin, Navigation, CheckCircle, Clock, Loader2, Package, Bike, 
  ArrowRight, User, LogOut, Camera, Phone, RefreshCw, Save, Globe,
  ExternalLink, Map as MapIcon, Store as StoreIcon, PhoneCall, Edit3, 
  ShieldCheck, Power
} from 'lucide-react';
import { db, auth } from '../services/firebase';
import { ref, onValue, update } from 'firebase/database';
import { Order, OrderStatus, Coordinates } from '../types';
import { formatCurrency, WILAYAS_ALGERIA } from '../utils/helpers';
import { MapVisualizer } from '../components/MapVisualizer';

export const DriverScreen: React.FC<{onLogout: () => void, userName: string}> = ({ onLogout, userName }) => {
  const [activeTab, setActiveTab] = useState<'AVAILABLE' | 'ACTIVE' | 'PROFILE'>('AVAILABLE');
  const [availableOrders, setAvailableOrders] = useState<Order[]>([]);
  const [activeOrder, setActiveOrder] = useState<Order | null>(null);
  const [loading, setLoading] = useState(true);
  const [isOnline, setIsOnline] = useState(true);
  const [driverProfile, setDriverProfile] = useState<any>(null);

  const currentDriverId = auth.currentUser?.uid;

  useEffect(() => {
    if (!currentDriverId) return;

    onValue(ref(db, `drivers/${currentDriverId}`), (snap) => {
      if (snap.exists()) setDriverProfile(snap.val());
    });

    onValue(ref(db, 'orders'), (snapshot) => {
        const data = snapshot.val();
        const available: Order[] = [];
        let myActive: Order | null = null;
        if (data && driverProfile && isOnline) {
            Object.keys(data).forEach(key => {
                const order = { ...data[key], id: key } as Order;
                if (order.driverId === currentDriverId && order.status !== OrderStatus.DELIVERED) myActive = order;
                if (order.status === OrderStatus.ACCEPTED_BY_STORE && !order.driverId && order.wilaya === driverProfile.wilaya) {
                  available.push(order);
                }
            });
        }
        setAvailableOrders(available);
        setActiveOrder(myActive);
        setLoading(false);
    });
  }, [currentDriverId, driverProfile, isOnline]);

  const openInGoogleMaps = (coords?: Coordinates) => {
    if (!coords) return;
    window.open(`https://www.google.com/maps/dir/?api=1&destination=${coords.lat},${coords.lng}`, '_blank');
  };

  const handleUpdateStatus = async (status: OrderStatus) => {
    if (!activeOrder) return;
    await update(ref(db, `orders/${activeOrder.id}`), { status });
  };

  if (loading) return <div className="h-screen flex items-center justify-center bg-white"><Loader2 className="animate-spin text-orange-500 w-12 h-12" /></div>;

  return (
    <div className="bg-[#F4F4F4] min-h-screen pb-32 font-cairo text-right" dir="rtl">

       <header className="bg-white sticky top-0 z-[100] px-6 pt-10 pb-6 shadow-sm border-b">
          <div className="flex justify-between items-center">
             <div>
                <h1 className="text-2xl font-black text-slate-800">شريك كيمو</h1>
                <div className="flex items-center gap-1.5 mt-1">
                   <div className={`w-2 h-2 rounded-full ${isOnline ? 'bg-green-500 animate-pulse' : 'bg-slate-300'}`}></div>
                   <p className="text-[10px] text-slate-400 font-black uppercase">{isOnline ? 'متصل وجاهز' : 'غير متصل'}</p>
                </div>
             </div>
             <button onClick={() => setIsOnline(!isOnline)} className={`w-12 h-12 rounded-2xl flex items-center justify-center transition-all shadow-lg ${isOnline ? 'bg-orange-500 text-white' : 'bg-slate-100 text-slate-400'}`}>
                <Power size={22} />
             </button>
          </div>
       </header>

       <main className="p-4 max-w-lg mx-auto">
         {!isOnline && activeTab !== 'PROFILE' ? (
           <div className="flex flex-col items-center justify-center h-[60vh] text-center p-10 space-y-4">
              <div className="w-20 h-20 bg-slate-100 rounded-full flex items-center justify-center text-slate-300"><Bike size={40} /></div>
              <h3 className="text-xl font-black text-slate-800">أنت خارج الخدمة</h3>
              <p className="text-xs text-slate-400 font-bold">قم بتفعيل الاتصال لاستقبال طلبات ولاية {driverProfile?.wilaya}</p>
           </div>
         ) : activeTab === 'ACTIVE' && activeOrder ? (
           <div className="animate-fade-in-up space-y-6">
              <div className="bg-white rounded-[2.5rem] overflow-hidden shadow-xl border border-white">
                 <MapVisualizer 
                   storeLocation={activeOrder.storeCoordinates} 
                   customerLocation={activeOrder.coordinates} 
                   zoom={14} 
                   height="h-48" 
                 />
                 <div className="p-6 space-y-6">
                    <div className="flex justify-between items-start">
                       <div>
                          <p className="text-[10px] font-black text-orange-500 uppercase">المهمة الحالية</p>
                          <h4 className="text-lg font-black text-slate-800">{activeOrder.storeName}</h4>
                       </div>
                       <button onClick={() => openInGoogleMaps(activeOrder.storeCoordinates)} className="bg-blue-50 text-blue-600 p-3 rounded-xl flex items-center gap-2 text-[10px] font-black shadow-sm">
                          <Navigation size={14} /> خرائط جوجل
                       </button>
                    </div>

                    <div className="space-y-4 pt-4 border-t border-slate-50">
                       <Step icon={<StoreIcon/>} label="استلام من المتجر" sub={activeOrder.storeName} active={activeOrder.status === OrderStatus.ACCEPTED_BY_DRIVER} />
                       <Step icon={<User/>} label="توصيل إلى الزبون" sub={activeOrder.customerName} active={activeOrder.status === OrderStatus.PICKED_UP} />
                    </div>

                    <div className="pt-4">
                       {activeOrder.status === OrderStatus.ACCEPTED_BY_DRIVER ? (
                         <button onClick={() => handleUpdateStatus(OrderStatus.PICKED_UP)} className="w-full bg-slate-900 text-white py-5 rounded-2xl font-black shadow-xl flex items-center justify-center gap-2">
                            <Package size={20} /> تم استلام الطلب
                         </button>
                       ) : (
                         <button onClick={() => handleUpdateStatus(OrderStatus.DELIVERED)} className="w-full bg-green-500 text-white py-5 rounded-2xl font-black shadow-xl flex items-center justify-center gap-2">
                            <CheckCircle size={20} /> تم التوصيل بنجاح
                         </button>
                       )}
                    </div>
                 </div>
              </div>
           </div>
         ) : activeTab === 'AVAILABLE' && (
           <div className="space-y-4 animate-fade-in-up">
              <h2 className="text-lg font-black text-slate-800 px-2">الطلبات المتاحة ({availableOrders.length})</h2>
              {availableOrders.map(o => (
                <div key={o.id} className="bg-white p-6 rounded-[2rem] shadow-sm border border-slate-50">
                   <div className="flex justify-between items-center mb-4">
                      <div className="flex items-center gap-3">
                         <div className="w-10 h-10 bg-orange-50 text-orange-500 rounded-xl flex items-center justify-center"><StoreIcon size={20}/></div>
                         <h4 className="font-black text-slate-800 text-sm">{o.storeName}</h4>
                      </div>
                      <span className="text-orange-600 font-black">{formatCurrency(o.totalPrice)}</span>
                   </div>
                   <button onClick={() => update(ref(db, `orders/${o.id}`), { status: OrderStatus.ACCEPTED_BY_DRIVER, driverId: currentDriverId, driverName: driverProfile.name })} className="w-full bg-slate-900 text-white py-4 rounded-xl font-black text-xs shadow-lg">قبول المهمة</button>
                </div>
              ))}
           </div>
         )}
       </main>

       <nav className="fixed bottom-0 left-0 right-0 bg-white/90 backdrop-blur-xl border-t h-20 flex justify-around items-center px-4 z-[500] shadow-2xl">
         <NavBtn act={activeTab === 'AVAILABLE'} onClick={() => setActiveTab('AVAILABLE')} icon={<LayoutGrid />} label="الطلبات" />
         <NavBtn act={activeTab === 'ACTIVE'} onClick={() => setActiveTab('ACTIVE')} icon={<MapIcon />} label="المهمة" />
         <NavBtn act={activeTab === 'PROFILE'} onClick={() => setActiveTab('PROFILE')} icon={<User />} label="حسابي" />
       </nav>
    </div>
  );
};

const Step = ({ icon, label, sub, active }: any) => (
  <div className={`flex items-center gap-4 p-4 rounded-2xl border ${active ? 'bg-orange-50 border-orange-200' : 'bg-white border-slate-100 opacity-40'}`}>
     <div className={`w-10 h-10 rounded-xl flex items-center justify-center ${active ? 'bg-orange-500 text-white' : 'bg-slate-100 text-slate-400'}`}>{icon}</div>
     <div>
        <p className="text-[10px] font-black text-slate-400 uppercase">{label}</p>
        <p className="text-xs font-black text-slate-800">{sub}</p>
     </div>
  </div>
);

const NavBtn = ({ act, onClick, icon, label }: any) => (
  <button onClick={onClick} className={`flex flex-col items-center gap-1.5 transition-all ${act ? 'text-orange-500 scale-110' : 'text-slate-400'}`}>
    {React.cloneElement(icon, { size: 22, strokeWidth: act ? 3 : 2 })}
