import { ref, push, set, onValue, remove, update } from 'firebase/database';
import { 
  Package, Plus, Loader2, Trash2, 
  ClipboardList, CheckCircle, Camera, LogOut, User, 
  TrendingUp, DollarSign, ShoppingBag, Clock, Eye, EyeOff, LayoutDashboard,
  BarChart3, Calendar, ChevronLeft, MapPin, Edit3
} from 'lucide-react';
import { formatCurrency } from '../utils/helpers';

export const StoreScreen: React.FC<{onLogout: () => void, userName: string}> = ({ onLogout, userName }) => {
  const [activeTab, setActiveTab] = useState<'DASHBOARD' | 'PRODUCTS' | 'ORDERS' | 'PROFILE'>('DASHBOARD');
  const [myProducts, setMyProducts] = useState<any[]>([]);
  const [orders, setOrders] = useState<Order[]>([]);
  const [storeProfile, setStoreProfile] = useState<StoreProfile | null>(null);
  const [loading, setLoading] = useState(true);

  const currentStoreId = auth.currentUser?.uid;

  useEffect(() => {
    if (!currentStoreId) return;

    onValue(ref(db, `stores/${currentStoreId}`), (s) => {
      if (s.exists()) setStoreProfile(s.val());
    });

    onValue(ref(db, 'products'), (s) => {
      const data = s.val();
      const list: any[] = [];
      if (data) Object.keys(data).forEach(k => { if (data[k].storeId === currentStoreId) list.push({ ...data[k], id: k }); });
      setMyProducts(list.reverse());
    });

    onValue(ref(db, 'orders'), (s) => {
      const data = s.val();
      const list: Order[] = [];
      if (data) Object.keys(data).forEach(k => { if (data[k].storeId === currentStoreId) list.push({ ...data[k], id: k }); });
      setOrders(list.sort((a, b) => b.timestamp - a.timestamp));
      setLoading(false);
    });
  }, [currentStoreId]);

  const stats = {
    revenue: orders.filter(o => o.status === OrderStatus.DELIVERED).reduce((s, o) => s + o.totalPrice, 0),
    ordersCount: orders.length,
    activeItems: myProducts.filter(p => !p.isHidden).length
  };

  const toggleProductVisibility = async (id: string, currentHidden: boolean) => {
    await update(ref(db, `products/${id}`), { isHidden: !currentHidden });
  };

  if (loading) return <div className="h-screen flex items-center justify-center bg-white"><Loader2 className="animate-spin text-orange-500 w-12 h-12" /></div>;

  return (
    <div className="bg-[#F8FAFC] min-h-screen pb-32 font-cairo text-right" dir="rtl">

       <header className="bg-white sticky top-0 z-[100] px-6 pt-10 pb-6 shadow-sm border-b">
          <div className="flex justify-between items-center">
             <div>
                <h1 className="text-2xl font-black text-slate-800">لوحة المتجر</h1>
                <p className="text-[10px] text-slate-400 font-black uppercase mt-1 tracking-widest">{storeProfile?.name} • {storeProfile?.wilaya}</p>
             </div>
             <div className="w-12 h-12 bg-slate-900 rounded-2xl flex items-center justify-center text-white"><LayoutDashboard size={24} /></div>
          </div>
       </header>

       <main className="p-4 max-w-lg mx-auto space-y-6">
          {activeTab === 'DASHBOARD' && (
