                   <div className={`w-2 h-2 rounded-full ${isOnline ? 'bg-green-500 animate-pulse' : 'bg-slate-300'}`}></div>
                   <p className="text-[10px] text-slate-400 font-black uppercase">{isOnline ? 'متصل وجاهز' : 'غير متصل'}</p>
                </div>
             </div>
             <button onClick={() => setIsOnline(!isOnline)} className={`w-12 h-12 rounded-2xl flex items-center justify-center transition-all shadow-lg ${isOnline ? 'bg-orange-500 text-white' : 'bg-slate-100 text-slate-400'}`}>
                <Power size={22} />
             </button>
          </div>
       </header>

       <main className="p-4 max-w-lg mx-auto">
         {!isOnline && activeTab !== 'PROFILE' ? (
