const uploadImage = async (file: File): Promise<string | null> => {
  const formData = new FormData();
  formData.append("file", file);
  formData.append("upload_preset", "makemm");
  const cloudName = 'dkqxgwjnr';
  try {
    const res = await fetch(`https://api.cloudinary.com/v1_1/${cloudName}/image/upload`, {
      method: "POST",
      body: formData,
    });
    const data = await res.json();
    return data.secure_url || null;
  } catch (error) { return null; }
};

export const StoreScreen: React.FC<{onLogout: () => void, userName: string}> = ({ onLogout, userName }) => {
  const [activeTab, setActiveTab] = useState<'DASHBOARD' | 'PRODUCTS' | 'ORDERS' | 'PROFILE'>('DASHBOARD');
  const [myProducts, setMyProducts] = useState<any[]>([]);
  const [orders, setOrders] = useState<Order[]>([]);
  const [storeProfile, setStoreProfile] = useState<StoreProfile | null>(null);
  const [loading, setLoading] = useState(true);

  // حالات إضافة المنتج
  const [isAddingProduct, setIsAddingProduct] = useState(false);
  const [isAiGenerating, setIsAiGenerating] = useState(false);
  const [isSavingProduct, setIsSavingProduct] = useState(false);
  const [newProduct, setNewProduct] = useState({
    name: '', price: '', category: Category.FOOD, description: '', image: ''
  });

  // حالات تعديل البروفايل
  const [isEditingProfile, setIsEditingProfile] = useState(false);
  const [isUploading, setIsUploading] = useState(false);
  const [editProfile, setEditProfile] = useState({
    name: '', phone: '', wilaya: '', image: ''
  });

  const fileInputRef = useRef<HTMLInputElement>(null);
  const currentStoreId = auth.currentUser?.uid;

  useEffect(() => {
    if (!currentStoreId) return;

    onValue(ref(db, `stores/${currentStoreId}`), (s) => {
      if (s.exists()) {
        const data = s.val();
        setStoreProfile(data);
        setEditProfile({
          name: data.name || '',
          phone: data.phone || '',
          wilaya: data.wilaya || '',
          image: data.image || ''
        });
      }
    });

    onValue(ref(db, 'products'), (s) => {
      const data = s.val();
      const list: any[] = [];
      if (data) Object.keys(data).forEach(k => { if (data[k].storeId === currentStoreId) list.push({ ...data[k], id: k }); });
      setMyProducts(list.reverse());
    });

    onValue(ref(db, 'orders'), (s) => {
      const data = s.val();
      const list: Order[] = [];
      if (data) Object.keys(data).forEach(k => { if (data[k].storeId === currentStoreId) list.push({ ...data[k], id: k }); });
      setOrders(list.sort((a, b) => b.timestamp - a.timestamp));
      setLoading(false);
    });
  }, [currentStoreId]);

  const handleAddProduct = async () => {
    if (!newProduct.name || !newProduct.price || !newProduct.image) {
      alert("يرجى ملء جميع البيانات الأساسية وصورة المنتج");
      return;
    }
    setIsSavingProduct(true);
    try {
      const productData = {
        ...newProduct,
        price: Number(newProduct.price),
        storeId: currentStoreId,
        isHidden: false,
        timestamp: Date.now()
      };
      await push(ref(db, 'products'), productData);
      setIsAddingProduct(false);
      setNewProduct({ name: '', price: '', category: Category.FOOD, description: '', image: '' });
    } finally { setIsSavingProduct(false); }
  };

  const handleAiDescribe = async () => {
    if (!newProduct.name) return;
    setIsAiGenerating(true);
    const desc = await generateProductDescription(newProduct.name, newProduct.category);
    setNewProduct({ ...newProduct, description: desc });
    setIsAiGenerating(false);
  };

  const handleUpdateProfile = async () => {
    if (!currentStoreId) return;
    await update(ref(db, `stores/${currentStoreId}`), editProfile);
    setIsEditingProfile(false);
  };

  const toggleProductVisibility = async (id: string, currentHidden: boolean) => {
    await update(ref(db, `products/${id}`), { isHidden: !currentHidden });
  };

  if (loading) return <div className="h-screen flex items-center justify-center bg-white"><Loader2 className="animate-spin text-orange-500 w-12 h-12" /></div>;

  return (
    <div className="bg-[#F8FAFC] min-h-screen pb-32 font-cairo text-right" dir="rtl">

       <header className="bg-white sticky top-0 z-[100] px-6 pt-10 pb-6 shadow-sm border-b">
          <div className="flex justify-between items-center">
             <div>
                <h1 className="text-2xl font-black text-slate-800">إدارة المتجر</h1>
                <p className="text-[10px] text-slate-400 font-black uppercase mt-1 tracking-widest">{storeProfile?.name} • {storeProfile?.wilaya}</p>
             </div>
             <div className="w-12 h-12 bg-slate-900 rounded-2xl flex items-center justify-center text-white shadow-xl"><LayoutDashboard size={24} /></div>
          </div>
       </header>

       <main className="p-4 max-w-lg mx-auto space-y-6">

          {/* تبويب لوحة التحكم */}
          {activeTab === 'DASHBOARD' && (
            <div className="space-y-6 animate-fade-in-up">
               <div className="grid grid-cols-2 gap-4">
                  <StatCard icon={<DollarSign className="text-green-500" />} label="الأرباح الكلية" value={formatCurrency(orders.filter(o => o.status === OrderStatus.DELIVERED).reduce((s, o) => s + o.totalPrice, 0))} color="bg-green-50" />
                  <StatCard icon={<ShoppingBag className="text-orange-500" />} label="طلبات اليوم" value={orders.length} color="bg-orange-50" />
