                             <Store size={18} className="absolute right-4 top-4 text-slate-300" />
                          </div>
                          <div className="relative">
                             <input type="tel" placeholder="رقم الهاتف" className="w-full p-4 pr-12 bg-slate-50 rounded-2xl font-bold outline-none" value={editProfile.phone} onChange={e => setEditProfile({...editProfile, phone: e.target.value})} />
                             <Phone size={18} className="absolute right-4 top-4 text-slate-300" />
                          </div>
                          <div className="relative">
                             <select className="w-full p-4 pr-12 bg-slate-50 rounded-2xl font-bold outline-none appearance-none" value={editProfile.wilaya} onChange={e => setEditProfile({...editProfile, wilaya: e.target.value})}>
                                {WILAYAS_ALGERIA.map(w => <option key={w} value={w}>{w}</option>)}
                             </select>
                             <Globe size={18} className="absolute right-4 top-4 text-slate-300" />
                          </div>
                       </div>

                       <button onClick={handleUpdateProfile} className="w-full brand-gradient text-white py-5 rounded-2xl font-black text-lg shadow-xl shadow-orange-100 flex items-center justify-center gap-2 mt-4"><Save size={20}/> حفظ التغييرات</button>
                    </div>
                  )}
               </div>
            </div>
          )}

          {/* تبويب الطلبات */}
          {activeTab === 'ORDERS' && (
            <div className="space-y-4 animate-fade-in-up">
               <h2 className="text-lg font-black text-slate-800 px-2">إدارة الطلبات الواردة ({orders.length})</h2>
               {orders.map(o => (
                 <div key={o.id} className="bg-white p-6 rounded-[2.5rem] shadow-sm border border-slate-50 relative">
                    <div className="flex justify-between items-start mb-4">
                       <div>
                          <h4 className="font-black text-slate-800">{o.customerName}</h4>
                          <p className="text-[10px] text-slate-400 font-bold">{new Date(o.timestamp).toLocaleTimeString('ar-DZ')}</p>
                       </div>
                       <span className={`px-3 py-1 rounded-full text-[10px] font-black ${o.status === OrderStatus.PENDING ? 'bg-orange-50 text-orange-500' : 'bg-green-50 text-green-500'}`}>{o.status}</span>
                    </div>
                    <div className="bg-slate-50 p-4 rounded-2xl mb-4">
                       {o.products.map((item, idx) => <p key={idx} className="text-[11px] font-bold text-slate-600">{item.product.name} × {item.quantity}</p>)}
                    </div>
                    {o.status === OrderStatus.PENDING && (
                      <button onClick={() => update(ref(db, `orders/${o.id}`), { status: OrderStatus.ACCEPTED_BY_STORE })} className="w-full bg-slate-900 text-white py-4 rounded-2xl font-black text-xs shadow-lg flex items-center justify-center gap-2"><CheckCircle size={16}/> قبول وتحضير الطلب</button>
                    )}
                 </div>
               ))}
            </div>
          )}

       </main>

       <nav className="fixed bottom-0 left-0 right-0 bg-white/90 backdrop-blur-xl border-t h-20 flex justify-around items-center px-4 z-[500] shadow-2xl">
         <NavBtn act={activeTab === 'DASHBOARD'} onClick={() => setActiveTab('DASHBOARD')} icon={<BarChart3 />} label="الرئيسية" />
         <NavBtn act={activeTab === 'PRODUCTS'} onClick={() => setActiveTab('PRODUCTS')} icon={<Package />} label="المنتجات" />
         <NavBtn act={activeTab === 'ORDERS'} onClick={() => setActiveTab('ORDERS')} icon={<ClipboardList />} label="الطلبات" />
         <NavBtn act={activeTab === 'PROFILE'} onClick={() => setActiveTab('PROFILE')} icon={<User />} label="المحل" />
       </nav>
    </div>
  );
};

const StatCard = ({ icon, label, value, color }: any) => (
  <div className={`p-6 rounded-[2.2rem] ${color} border border-white/50 shadow-sm flex flex-col items-center`}>
     <div className="mb-4">{icon}</div>
     <p className="text-[9px] text-slate-500 font-black mb-1 uppercase tracking-tighter">{label}</p>
     <h4 className="text-lg font-black text-slate-800">{value}</h4>
  </div>
);

const ProfileStat = ({ label, value }: any) => (
  <div className="bg-slate-50 p-4 rounded-3xl">
     <p className="text-[10px] text-slate-400 font-black mb-1">{label}</p>
     <p className="text-xl font-black text-slate-800">{value}</p>
  </div>
);

const NavBtn = ({ act, onClick, icon, label }: any) => (
  <button onClick={onClick} className={`flex flex-col items-center gap-1.5 transition-all ${act ? 'text-orange-500 scale-110' : 'text-slate-400'}`}>
    {React.cloneElement(icon, { size: 22, strokeWidth: act ? 3 : 2 })}
    <span className="text-[9px] font-black">{label}</span>
  </button>
);

import React, { useState, useEffect, useRef } from 'react';
import { Category, Product, StoreProfile, OrderStatus, Order, Coordinates } from '../types';
import { formatCurrency, calculateDistance } from '../utils/helpers';
import { db, auth } from '../services/firebase';
import { ref, onValue, push, set, update } from 'firebase/database';
import { 
  Search, Plus, Minus, ShoppingCart, MapPin, Loader2, Home, User, 
  Star, LayoutGrid, Navigation, X, Bot, Heart, 
  Truck, CheckCircle, ShoppingBag, ChevronRight, Info, Zap, Store as StoreIcon,
  Map as MapIcon, Clock, Phone, History, CreditCard
} from 'lucide-react';
import { getKimoAssistantResponse } from '../services/geminiService';
import { MapVisualizer } from '../components/MapVisualizer';

export const CustomerScreen: React.FC<{onLogout: () => void, userName: string}> = ({ onLogout, userName }) => {
  const [activeTab, setActiveTab] = useState<'HOME' | 'CATEGORIES' | 'ORDERS' | 'PROFILE'>('HOME');
  const [cart, setCart] = useState<{product: Product; quantity: number}[]>([]);
  const [stores, setStores] = useState<StoreProfile[]>([]);
  const [allProducts, setAllProducts] = useState<Product[]>([]);
  const [myOrders, setMyOrders] = useState<Order[]>([]);
  const [favorites, setFavorites] = useState<string[]>([]);
  const [loading, setLoading] = useState(true);
  const [searchQuery, setSearchQuery] = useState('');
  const [selectedCategory, setSelectedCategory] = useState<string | null>(null);

  // Modals
  const [selectedStore, setSelectedStore] = useState<StoreProfile | null>(null);
  const [selectedProduct, setSelectedProduct] = useState<Product | null>(null);
  const [showCheckout, setShowCheckout] = useState(false);
  const [deliveryCoords, setDeliveryCoords] = useState<Coordinates | null>(null);

  // AI
  const [showAi, setShowAi] = useState(false);
  const [aiMessages, setAiMessages] = useState<{role: 'ai'|'user', text: string}[]>([]);
  const [aiLoading, setAiLoading] = useState(false);

  const [profileData, setProfileData] = useState({ name: '', phone: '', avatar: '', wilaya: '', coordinates: null as any });
  const user = auth.currentUser;

  useEffect(() => {
    if (!user) return;
    onValue(ref(db, `customers/${user.uid}`), (snap) => {
      if (snap.exists()) {
        const data = snap.val();
        setProfileData(data);
        if (data.coordinates) setDeliveryCoords(data.coordinates);
      }
    });
    onValue(ref(db, 'stores'), (snap) => {
      const data = snap.val();
      if (data) setStores(Object.keys(data).map(k => ({ id: k, ...data[k] })));
    });
    onValue(ref(db, 'products'), (snap) => {
      const data = snap.val();
      if (data) setAllProducts(Object.keys(data).map(k => ({ id: k, ...data[k] })));
      setLoading(false);
    });
    onValue(ref(db, 'orders'), (snap) => {
      const data = snap.val();
      const list: Order[] = [];
      if (data) Object.keys(data).forEach(k => { if (data[k].customerId === user.uid) list.push({ id: k, ...data[k] }); });
      setMyOrders(list.sort((a, b) => b.timestamp - a.timestamp));
    });
  }, [user]);

  const addToCart = (p: Product) => {
    if (cart.length > 0 && cart[0].product.storeId !== p.storeId) {
      if (window.confirm("لا يمكنك الطلب من متجرين مختلفين. هل تريد إفراغ سلتك الحالية؟")) {
        setCart([{ product: p, quantity: 1 }]);
      }
      return;
    }
    setCart(prev => {
      const ex = prev.find(i => i.product.id === p.id);
      if (ex) return prev.map(i => i.product.id === p.id ? {...i, quantity: i.quantity + 1} : i);
      return [...prev, { product: p, quantity: 1 }];
    });
  };

  const handleCheckout = async () => {
    if (!user || cart.length === 0 || !deliveryCoords) return;
    const total = cart.reduce((sum, item) => sum + (item.product.price * item.quantity), 0);
    const store = stores.find(s => s.id === cart[0].product.storeId);

    const orderData = {
      customerId: user.uid,
      customerName: profileData.name,
      customerPhone: profileData.phone,
      storeId: cart[0].product.storeId,
      storeName: store?.name || "متجر كيمو",
      storeCoordinates: store?.coordinates || profileData.coordinates,
      products: cart,
      totalPrice: total + 200, // 200 DA delivery fee
      deliveryFee: 200,
      status: OrderStatus.PENDING,
      timestamp: Date.now(),
      wilaya: profileData.wilaya,
      coordinates: deliveryCoords,
      address: "تم التحديد عبر الخريطة"
    };

    const newOrderRef = push(ref(db, 'orders'));
    await set(newOrderRef, orderData);
    setCart([]);
    setShowCheckout(false);
    setActiveTab('ORDERS');
    alert("تم إرسال طلبك بنجاح! كيمو سيصلك قريباً.");
  };

  const toggleFavorite = (id: string) => {
    setFavorites(prev => prev.includes(id) ? prev.filter(f => f !== id) : [...prev, id]);
  };

  const localStores = stores.filter(s => s.wilaya === profileData.wilaya);
  const featuredProducts = allProducts.filter(p => localStores.some(s => s.id === p.storeId)).slice(0, 6);

  if (loading) return <div className="h-screen flex items-center justify-center bg-white"><Loader2 className="animate-spin text-orange-500 w-12 h-12" /></div>;

  return (
    <div className="bg-[#F8FAFC] min-h-screen pb-32 font-cairo text-right" dir="rtl">

      {/* سلة المشتريات العائمة */}
      {cart.length > 0 && !showCheckout && (
        <div className="fixed bottom-24 left-4 right-4 z-[900] animate-fade-in-up">
           <button onClick={() => setShowCheckout(true)} className="w-full brand-gradient text-white p-5 rounded-[2.5rem] shadow-2xl flex items-center justify-between px-8">
              <div className="flex items-center gap-3">
                 <div className="bg-white/20 p-2 rounded-xl"><ShoppingCart size={20}/></div>
                 <div className="text-right">
                    <p className="text-[10px] font-black opacity-80">لديك {cart.length} منتجات</p>
                    <p className="text-sm font-black">إتمام الطلب الآن</p>
                 </div>
              </div>
              <span className="text-lg font-black">{formatCurrency(cart.reduce((s, i) => s + (i.product.price * i.quantity), 0))}</span>
           </button>
        </div>
      )}

      {/* نافذة الدفع Checkout */}
      {showCheckout && (
        <div className="fixed inset-0 z-[2000] bg-white flex flex-col">
           <header className="p-6 flex items-center justify-between border-b">
              <button onClick={() => setShowCheckout(false)} className="p-2 bg-slate-50 rounded-full"><X/></button>
              <h2 className="text-lg font-black">تأكيد الطلب</h2>
              <div className="w-10"></div>
           </header>
           <div className="flex-1 overflow-y-auto p-6 space-y-8">
              <section className="space-y-4">
                 <h3 className="font-black text-slate-800 flex items-center gap-2"><MapPin size={18} className="text-orange-500"/> موقع التوصيل</h3>
                 <div className="h-48 rounded-[2rem] overflow-hidden border-2 border-slate-100 relative">
                    <MapVisualizer userLocation={deliveryCoords || profileData.coordinates} height="h-48" />
                    <div className="absolute inset-0 flex items-center justify-center pointer-events-none">
                       <div className="w-4 h-4 bg-orange-500 rounded-full border-2 border-white shadow-xl animate-ping"></div>
                    </div>
                 </div>
                 <p className="text-[10px] text-slate-400 font-bold text-center">سيقوم الموصل بالاعتماد على هذه النقطة بدقة</p>
              </section>

              <section className="space-y-4">
                 <h3 className="font-black text-slate-800">ملخص السلة</h3>
                 <div className="space-y-3">
                    {cart.map((item, idx) => (
                      <div key={idx} className="flex justify-between items-center bg-slate-50 p-4 rounded-2xl">
                         <div className="flex items-center gap-3">
                            <span className="w-8 h-8 bg-white rounded-lg flex items-center justify-center font-black text-orange-500 text-xs">{item.quantity}x</span>
                            <p className="text-xs font-black text-slate-700">{item.product.name}</p>
                         </div>
                         <span className="text-xs font-black">{formatCurrency(item.product.price * item.quantity)}</span>
                      </div>
                    ))}
                 </div>
              </section>

              <div className="bg-orange-50 p-6 rounded-[2rem] space-y-3">
                 <div className="flex justify-between text-xs font-bold text-slate-600"><span>المجموع الفرعي</span> <span>{formatCurrency(cart.reduce((s, i) => s + (i.product.price * i.quantity), 0))}</span></div>
                 <div className="flex justify-between text-xs font-bold text-slate-600"><span>رسوم التوصيل</span> <span>{formatCurrency(200)}</span></div>
                 <div className="flex justify-between text-lg font-black text-orange-600 pt-3 border-t border-orange-100"><span>الإجمالي</span> <span>{formatCurrency(cart.reduce((s, i) => s + (i.product.price * i.quantity), 0) + 200)}</span></div>
              </div>
           </div>
           <footer className="p-6 border-t">
              <button onClick={handleCheckout} className="w-full bg-slate-900 text-white py-5 rounded-[2rem] font-black text-lg shadow-xl active:scale-95 transition-all">تأكيد وطلب الآن</button>
           </footer>
        </div>
      )}

      {/* صفحة المتجر Store Page */}
      {selectedStore && (
        <div className="fixed inset-0 z-[1500] bg-white overflow-y-auto animate-fade-in">
           <div className="h-64 relative">
              <img src={selectedStore.image} className="w-full h-full object-cover" />
              <div className="absolute inset-0 bg-black/40"></div>
              <button onClick={() => setSelectedStore(null)} className="absolute top-8 right-6 p-2 bg-white/20 backdrop-blur-md rounded-full text-white"><X/></button>
              <div className="absolute bottom-6 right-6 text-white">
                 <h2 className="text-3xl font-black mb-1">{selectedStore.name}</h2>
                 <div className="flex items-center gap-3 text-xs font-black">
                    <div className="flex items-center gap-1 text-yellow-400"><Star size={14} fill="currentColor"/> {selectedStore.rating}</div>
                    <div className="w-1 h-1 bg-white/50 rounded-full"></div>
                    <div>{selectedStore.wilaya}</div>
                 </div>
              </div>
           </div>
           <div className="p-6 -mt-8 bg-white rounded-t-[3rem] relative z-10 space-y-8">
              <div className="flex gap-4 p-4 bg-slate-50 rounded-[2rem]">
                 <div className="flex-1 text-center border-l border-slate-200">
                    <p className="text-[10px] font-black text-slate-400 mb-1">وقت التوصيل</p>
                    <p className="text-xs font-black text-slate-700">25-35 دقيقة</p>
                 </div>
                 <div className="flex-1 text-center">
                    <p className="text-[10px] font-black text-slate-400 mb-1">الحد الأدنى</p>
                    <p className="text-xs font-black text-slate-700">500 د.ج</p>
                 </div>
              </div>

              <div className="space-y-4">
                 <h3 className="text-lg font-black text-slate-800">قائمة الطعام</h3>
                 <div className="grid grid-cols-1 gap-4">
                    {allProducts.filter(p => p.storeId === selectedStore.id).map(p => (
                      <div key={p.id} className="bg-white border border-slate-100 p-4 rounded-[2rem] flex items-center gap-4 shadow-sm">
                         <img src={p.image} className="w-20 h-20 rounded-2xl object-cover" />
                         <div className="flex-1">
                            <h4 className="text-sm font-black text-slate-800 mb-1">{p.name}</h4>
                            <p className="text-[10px] text-slate-400 font-bold mb-2 line-clamp-1">{p.description}</p>
                            <span className="text-sm font-black text-orange-500">{formatCurrency(p.price)}</span>
                         </div>
                         <button onClick={() => addToCart(p)} className="w-10 h-10 bg-slate-900 text-white rounded-xl flex items-center justify-center active:scale-90 transition-all"><Plus size={18}/></button>
                      </div>
                    ))}
                 </div>
              </div>
           </div>
        </div>
      )}

      {/* Header */}
      <header className="bg-white sticky top-0 z-[100] px-6 pt-8 pb-4 border-b border-slate-50">
