                 <div className="flex items-center gap-1">
                    <h2 className="text-sm font-black text-slate-800">{profileData.wilaya || 'بئر العاتر'}</h2>
                    <ChevronRight size={14} className="text-slate-400" />
                 </div>
              </div>
           </div>
           <button onClick={() => setActiveTab('PROFILE')} className="w-12 h-12 rounded-2xl bg-slate-50 flex items-center justify-center border border-slate-100 overflow-hidden shadow-sm">
              {profileData.avatar ? <img src={profileData.avatar} className="w-full h-full object-cover" /> : <User size={20} className="text-slate-400" />}
           </button>
