  TrendingUp, DollarSign, ShoppingBag, Clock, Eye, EyeOff, LayoutDashboard,
  BarChart3, Calendar, ChevronLeft, MapPin, Edit3, Sparkles, Save, X, Phone, Globe,
  Store, Star, Settings, Bell, Info, Layers
} from 'lucide-react';
