  const [availableOrders, setAvailableOrders] = useState<Order[]>([]);
  const [activeOrder, setActiveOrder] = useState<Order | null>(null);
  const [loading, setLoading] = useState(true);
  const [isOnline, setIsOnline] = useState(true);
  const [driverProfile, setDriverProfile] = useState<any>(null);
  const [myOrdersHistory, setMyOrdersHistory] = useState<Order[]>([]);

  // Profile Edit
  const [isEditingProfile, setIsEditingProfile] = useState(false);
  const [isUploading, setIsUploading] = useState(false);
  const [editForm, setEditForm] = useState({ name: '', phone: '', wilaya: '', avatar: '', vehicle: 'دراجة' });
  const fileInputRef = useRef<HTMLInputElement>(null);

  const currentDriverId = auth.currentUser?.uid;

  useEffect(() => {
    if (!currentDriverId) return;

    onValue(ref(db, `drivers/${currentDriverId}`), (snap) => {
      if (snap.exists()) {
        const data = snap.val();
        setDriverProfile(data);
        setEditForm({
          name: data.name || '',
          phone: data.phone || '',
          wilaya: data.wilaya || '',
          avatar: data.avatar || '',
          vehicle: data.vehicle || 'دراجة'
        });
      }
    });

    onValue(ref(db, 'orders'), (snapshot) => {
        const data = snapshot.val();
        const available: Order[] = [];
        const history: Order[] = [];
        let myActive: Order | null = null;

        if (data && driverProfile) {
            Object.keys(data).forEach(key => {
                const order = { ...data[key], id: key } as Order;
                if (order.driverId === currentDriverId) {
                  if (order.status !== OrderStatus.DELIVERED && order.status !== OrderStatus.CANCELLED) myActive = order;
                  else history.push(order);
                }
                if (isOnline && order.status === OrderStatus.ACCEPTED_BY_STORE && !order.driverId && order.wilaya === driverProfile.wilaya) {
                  available.push(order);
                }
