             <button onClick={() => setIsOnline(!isOnline)} className={`flex items-center gap-3 px-6 py-3 rounded-2xl font-black text-xs transition-all shadow-lg ${isOnline ? 'bg-green-500 text-white shadow-green-100' : 'bg-slate-100 text-slate-400 shadow-slate-50'}`}>
