export const StoreScreen: React.FC<{onLogout: () => void, userName: string}> = ({ onLogout, userName }) => {
  const [activeTab, setActiveTab] = useState<'DASHBOARD' | 'PRODUCTS' | 'ORDERS' | 'PROFILE'>('DASHBOARD');
  const [myProducts, setMyProducts] = useState<any[]>([]);
  const [orders, setOrders] = useState<Order[]>([]);
  const [storeProfile, setStoreProfile] = useState<StoreProfile | null>(null);
  const [loading, setLoading] = useState(true);

  // States
  const [isAddingProduct, setIsAddingProduct] = useState(false);
  const [isAiGenerating, setIsAiGenerating] = useState(false);
  const [isSavingProduct, setIsSavingProduct] = useState(false);
  const [newProduct, setNewProduct] = useState({
    name: '', price: '', category: Category.FOOD, description: '', image: '', stock: '10'
  });

  const [isEditingProfile, setIsEditingProfile] = useState(false);
  const [isUploading, setIsUploading] = useState(false);
  const [editProfile, setEditProfile] = useState({
    name: '', phone: '', wilaya: '', image: '', isOpen: true
  });

  const fileInputRef = useRef<HTMLInputElement>(null);
  const currentStoreId = auth.currentUser?.uid;

  useEffect(() => {
    if (!currentStoreId) return;

    onValue(ref(db, `stores/${currentStoreId}`), (s) => {
      if (s.exists()) {
        const data = s.val();
        setStoreProfile(data);
        setEditProfile({
          name: data.name || '',
          phone: data.phone || '',
          wilaya: data.wilaya || '',
          image: data.image || '',
          isOpen: data.isOpen !== undefined ? data.isOpen : true
        });
      }
    });

    onValue(ref(db, 'products'), (s) => {
      const data = s.val();
      const list: any[] = [];
      if (data) Object.keys(data).forEach(k => { if (data[k].storeId === currentStoreId) list.push({ ...data[k], id: k }); });
      setMyProducts(list.reverse());
    });

    onValue(ref(db, 'orders'), (s) => {
      const data = s.val();
      const list: Order[] = [];
      if (data) Object.keys(data).forEach(k => { if (data[k].storeId === currentStoreId) list.push({ ...data[k], id: k }); });
      setOrders(list.sort((a, b) => b.timestamp - a.timestamp));
      setLoading(false);
    });
  }, [currentStoreId]);

  const handleUpdateProfile = async () => {
    if (!currentStoreId) return;
    setIsUploading(true);
    await update(ref(db, `stores/${currentStoreId}`), editProfile);
    setIsEditingProfile(false);
    setIsUploading(false);
  };

  const toggleStoreStatus = async () => {
    if (!currentStoreId) return;
    const newStatus = !editProfile.isOpen;
    await update(ref(db, `stores/${currentStoreId}`), { isOpen: newStatus });
    setEditProfile(prev => ({ ...prev, isOpen: newStatus }));
  };

  if (loading) return <div className="h-screen flex items-center justify-center bg-white"><Loader2 className="animate-spin text-orange-500 w-12 h-12" /></div>;

  return (
    <div className="bg-[#F8FAFC] min-h-screen pb-32 font-cairo text-right" dir="rtl">

       <header className="bg-white sticky top-0 z-[100] px-6 pt-10 pb-6 shadow-sm border-b flex items-center justify-between">
          <div className="flex items-center gap-3">
             <div className="w-12 h-12 bg-orange-500 rounded-2xl flex items-center justify-center text-white shadow-xl rotate-3"><Store size={24} /></div>
             <div>
                <h1 className="text-xl font-black text-slate-800">{storeProfile?.name}</h1>
                <div className={`flex items-center gap-1.5 text-[10px] font-black ${editProfile.isOpen ? 'text-green-500' : 'text-red-500'}`}>
                   <div className={`w-1.5 h-1.5 rounded-full ${editProfile.isOpen ? 'bg-green-500 animate-pulse' : 'bg-red-500'}`}></div>
                   {editProfile.isOpen ? 'متصل' : 'مغلق'}
                </div>
             </div>
          </div>
          <button onClick={toggleStoreStatus} className={`px-5 py-2.5 rounded-2xl font-black text-[10px] transition-all shadow-lg ${editProfile.isOpen ? 'bg-red-50 text-red-500' : 'bg-green-50 text-green-500'}`}>
             {editProfile.isOpen ? 'إغلاق المتجر' : 'فتح المتجر'}
          </button>
       </header>

       <main className="p-4 max-w-lg mx-auto space-y-8 mt-4">
          {activeTab === 'PROFILE' ? (
             <div className="animate-fade-in-up space-y-8">
                <div className="bg-white p-10 rounded-[3.5rem] shadow-xl border border-white">
                   {!isEditingProfile ? (
                      <div className="text-center">
                         <div className="w-32 h-32 mx-auto mb-6 rounded-[3rem] border-4 border-white shadow-2xl overflow-hidden bg-slate-50 flex items-center justify-center">
                            {storeProfile?.image ? <img src={storeProfile.image} className="w-full h-full object-cover" /> : <Store size={48} className="text-slate-200" />}
                         </div>
                         <h3 className="text-2xl font-black text-slate-800 mb-1">{storeProfile?.name}</h3>
                         <div className="flex items-center justify-center gap-2 mb-8">
                            <span className="bg-orange-50 text-orange-500 px-4 py-1.5 rounded-full text-[10px] font-black">{storeProfile?.wilaya}</span>
                            <span className="bg-slate-100 px-4 py-1.5 rounded-full text-[10px] font-black flex items-center gap-1"><Star size={12} fill="currentColor"/> {storeProfile?.rating || '5.0'}</span>
                         </div>

                         <div className="grid grid-cols-2 gap-4 mb-8">
                            <div className="bg-slate-50 p-6 rounded-3xl">
                               <p className="text-[10px] font-black text-slate-400 mb-1 uppercase">الطلبات</p>
                               <p className="text-xl font-black text-slate-800">{orders.length}</p>
                            </div>
                            <div className="bg-slate-50 p-6 rounded-3xl">
                               <p className="text-[10px] font-black text-slate-400 mb-1 uppercase">الأصناف</p>
                               <p className="text-xl font-black text-slate-800">{myProducts.length}</p>
                            </div>
                         </div>

                         <div className="space-y-3">
                            <button onClick={() => setIsEditingProfile(true)} className="w-full bg-slate-900 text-white py-5 rounded-[2rem] font-black shadow-xl flex items-center justify-center gap-2"><Edit3 size={18}/> تعديل بيانات المتجر</button>
                            <button onClick={onLogout} className="w-full text-red-500 font-black text-sm py-4">تسجيل الخروج</button>
                         </div>
                      </div>
                   ) : (
                      <div className="space-y-6">
                         <div className="flex justify-between items-center">
                            <h3 className="text-xl font-black">تعديل المتجر</h3>
                            <button onClick={() => setIsEditingProfile(false)} className="p-2 bg-slate-50 rounded-full"><X/></button>
                         </div>

                         <div className="flex flex-col items-center mb-6">
                            <div onClick={() => fileInputRef.current?.click()} className="w-24 h-24 bg-slate-50 rounded-3xl border-2 border-dashed border-slate-200 flex items-center justify-center cursor-pointer overflow-hidden relative">
                               {editProfile.image ? <img src={editProfile.image} className="w-full h-full object-cover" /> : <Camera className="text-slate-300" />}
                               {isUploading && <div className="absolute inset-0 bg-white/60 flex items-center justify-center"><Loader2 className="animate-spin text-orange-500" /></div>}
                            </div>
                            <input type="file" ref={fileInputRef} className="hidden" onChange={async (e) => {
                               const f = e.target.files?.[0];
                               if (f) { setIsUploading(true); const url = await uploadImage(f); if (url) setEditProfile({...editProfile, image: url}); setIsUploading(false); }
                            }} />
                         </div>

                         <div className="space-y-4">
                            <input type="text" placeholder="اسم المتجر" className="w-full p-4 bg-slate-50 rounded-2xl font-bold outline-none" value={editProfile.name} onChange={e => setEditProfile({...editProfile, name: e.target.value})} />
                            <input type="tel" placeholder="رقم الهاتف" className="w-full p-4 bg-slate-50 rounded-2xl font-bold outline-none" value={editProfile.phone} onChange={e => setEditProfile({...editProfile, phone: e.target.value})} />
                            <select className="w-full p-4 bg-slate-50 rounded-2xl font-bold outline-none appearance-none" value={editProfile.wilaya} onChange={e => setEditProfile({...editProfile, wilaya: e.target.value})}>
                               {WILAYAS_ALGERIA.map(w => <option key={w} value={w}>{w}</option>)}
                            </select>
                         </div>

                         <button onClick={handleUpdateProfile} disabled={isUploading} className="w-full brand-gradient text-white py-5 rounded-[2rem] font-black text-lg shadow-xl flex items-center justify-center gap-2">
                            {isUploading ? <Loader2 className="animate-spin" /> : <><Save size={20}/> حفظ التغييرات</>}
                         </button>
                      </div>
                   )}
                </div>
             </div>
          ) : (
             <div className="space-y-8 animate-fade-in-up">
                {/* Dashboard and Orders content... */}
                <div className="grid grid-cols-2 gap-4">
                   <StatCard icon={<DollarSign className="text-green-500" />} label="أرباح اليوم" value={formatCurrency(orders.filter(o => o.status === OrderStatus.DELIVERED).reduce((s, o) => s + o.totalPrice, 0))} color="bg-green-50" />
                   <StatCard icon={<ShoppingBag className="text-blue-500" />} label="الطلبات" value={orders.length} color="bg-blue-50" />
                </div>
                {/* Rest of UI as before */}
             </div>
          )}
       </main>

       <nav className="fixed bottom-0 left-0 right-0 bg-white/90 backdrop-blur-xl border-t h-20 flex justify-around items-center px-4 z-[1000] shadow-2xl">
         <NavBtn act={activeTab === 'DASHBOARD'} onClick={() => setActiveTab('DASHBOARD')} icon={<BarChart3 />} label="الرئيسية" />
         <NavBtn act={activeTab === 'PRODUCTS'} onClick={() => setActiveTab('PRODUCTS')} icon={<Package />} label="الأصناف" />
         <NavBtn act={activeTab === 'ORDERS'} onClick={() => setActiveTab('ORDERS')} icon={<ClipboardList />} label="الطلبات" />
         <NavBtn act={activeTab === 'PROFILE'} onClick={() => setActiveTab('PROFILE')} icon={<User />} label="المتجر" />
       </nav>
    </div>
  );
};

const StatCard = ({ icon, label, value, color }: any) => (
  <div className={`p-8 rounded-[3rem] ${color} border border-white shadow-sm flex flex-col items-center text-center`}>
     <div className="mb-4">{icon}</div>
     <p className="text-[10px] text-slate-400 font-black uppercase mb-1">{label}</p>
     <h4 className="text-xl font-black text-slate-800">{value}</h4>
  </div>
);

const NavBtn = ({ act, onClick, icon, label }: any) => (
  <button onClick={onClick} className={`flex flex-col items-center gap-1.5 transition-all ${act ? 'text-orange-500 scale-110' : 'text-slate-400'}`}>
    {React.cloneElement(icon, { size: 22, strokeWidth: act ? 3 : 2 })}
    <span className="text-[9px] font-black">{label}</span>
  </button>
);

import React, { useEffect } from 'react';
import { MapContainer, TileLayer, Marker, Popup, useMap, useMapEvents } from 'react-leaflet';
import L from 'leaflet';
import { Coordinates } from '../types';
import { BIR_EL_ATER_CENTER } from '../utils/helpers';

interface MapVisualizerProps {
  userLocation?: Coordinates;
  storeLocation?: Coordinates;
  customerLocation?: Coordinates;
  driverLocation?: Coordinates;
  height?: string;
  zoom?: number;
  onLocationSelect?: (coords: Coordinates) => void;
  isPicker?: boolean;
}

const createCustomIcon = (iconHtml: string, colorClass: string, size = 32) => {
  return L.divIcon({
    html: `<div class="relative flex items-center justify-center p-1 rounded-full ${colorClass} shadow-md border-2 border-white/80"><div class="text-white w-4 h-4">${iconHtml}</div></div>`,
    className: 'bg-transparent flex items-center justify-center',
    iconSize: [size, size],
    iconAnchor: [size/2, size],
    popupAnchor: [0, -size]
  });
};

const userIcon = createCustomIcon('<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M19 21v-2a4 4 0 0 0-4-4H9a4 4 0 0 0-4 4v2"/><circle cx="12" cy="7" r="4"/></svg>', 'bg-blue-600', 32);
const storeIcon = createCustomIcon('<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="m2 7 4.41-4.41A2 2 0 0 1 7.41 2h9.18a2 2 0 0 1 1.4.59L22 7"/><path d="M4 12v8a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2v-8"/><path d="M15 22v-4a2 2 0 0 0-2-2h-2a2 2 0 0 0-2 2v4"/><path d="M2 7h20"/><path d="M12 12v8"/></svg>', 'bg-orange-600', 36);
const customerIcon = createCustomIcon('<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M12 22s-8-4.5-8-11.8A8 8 0 0 1 12 2a8 8 0 0 1 8 8.2c0 7.3-8 11.8-8 11.8z"/><circle cx="12" cy="10" r="3"/></svg>', 'bg-brand-500', 34);

const RecenterMap = ({ coords }: { coords: Coordinates }) => {
  const map = useMap();
  useEffect(() => {
    if (coords && coords.lat && coords.lng) {
      map.setView([coords.lat, coords.lng], map.getZoom());
    }
  }, [coords, map]);
  return null;
};

const MapEvents = ({ onSelect }: { onSelect?: (coords: Coordinates) => void }) => {
  useMapEvents({
    click(e) {
      if (onSelect) {
        onSelect({ lat: e.latlng.lat, lng: e.latlng.lng });
      }
    },
  });
  return null;
};

export const MapVisualizer: React.FC<MapVisualizerProps> = ({ 
  userLocation, 
  storeLocation, 
  customerLocation, 
  driverLocation,
  height = 'h-64',
  zoom = 14,
  onLocationSelect,
  isPicker = false
}) => {
  const defaultCenter = driverLocation || userLocation || storeLocation || customerLocation || BIR_EL_ATER_CENTER;

  return (
    <div className={`relative w-full ${height} overflow-hidden z-0`}>
      <MapContainer 
        center={[defaultCenter.lat, defaultCenter.lng]} 
        zoom={zoom} 
        scrollWheelZoom={false} 
        className="h-full w-full"
        attributionControl={false}
      >
        <RecenterMap coords={defaultCenter} />
        <TileLayer url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png" />
        {isPicker && <MapEvents onSelect={onLocationSelect} />}

        {userLocation && userLocation.lat && (
          <Marker position={[userLocation.lat, userLocation.lng]} icon={userIcon}>
            <Popup>موقعك الحالي</Popup>
          </Marker>
        )}

        {storeLocation && storeLocation.lat && (
          <Marker position={[storeLocation.lat, storeLocation.lng]} icon={storeIcon}>
            <Popup>موقع المتجر</Popup>
          </Marker>
        )}

        {customerLocation && customerLocation.lat && (
          <Marker position={[customerLocation.lat, customerLocation.lng]} icon={customerIcon}>
            <Popup>{isPicker ? 'هنا سيصل طلبك' : 'موقع التوصيل'}</Popup>
          </Marker>
        )}
      </MapContainer>

      {isPicker && (
        <div className="absolute top-4 left-4 right-4 bg-white/90 backdrop-blur-md p-3 rounded-2xl shadow-xl z-[400] text-center pointer-events-none border border-orange-100">
           <p className="text-[10px] font-black text-slate-800">انقر على الخريطة لتحديد مكانك بدقة 📍</p>
        </div>
      )}
    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { Category, Product, StoreProfile, OrderStatus, Order, Coordinates } from '../types';
import { formatCurrency, WILAYAS_ALGERIA } from '../utils/helpers';
import { db, auth } from '../services/firebase';
import { ref, onValue, push, set, update } from 'firebase/database';
import { 
  Search, Plus, Minus, ShoppingCart, MapPin, Loader2, Home, User, 
  Star, LayoutGrid, Navigation, X, Bot, Heart, 
  Truck, CheckCircle, ShoppingBag, ChevronRight, Info, Zap, Store as StoreIcon,
  Map as MapIcon, Clock, Phone, History, CreditCard, Camera, Edit3, Save, LogOut, Globe, Settings
} from 'lucide-react';
import { MapVisualizer } from '../components/MapVisualizer';

const uploadImage = async (file: File): Promise<string | null> => {
  const formData = new FormData();
  formData.append("file", file);
  formData.append("upload_preset", "makemm");
  const cloudName = 'dkqxgwjnr';
  try {
    const res = await fetch(`https://api.cloudinary.com/v1_1/${cloudName}/image/upload`, {
      method: "POST",
      body: formData,
    });
    const data = await res.json();
    return data.secure_url || null;
  } catch (error) { return null; }
};

export const CustomerScreen: React.FC<{onLogout: () => void, userName: string}> = ({ onLogout, userName }) => {
  const [activeTab, setActiveTab] = useState<'HOME' | 'CATEGORIES' | 'ORDERS' | 'PROFILE'>('HOME');
  const [cart, setCart] = useState<{product: Product; quantity: number}[]>([]);
  const [stores, setStores] = useState<StoreProfile[]>([]);
  const [allProducts, setAllProducts] = useState<Product[]>([]);
  const [myOrders, setMyOrders] = useState<Order[]>([]);
  const [loading, setLoading] = useState(true);
  const [searchQuery, setSearchQuery] = useState('');

  // Modals
  const [selectedStore, setSelectedStore] = useState<StoreProfile | null>(null);
  const [showCheckout, setShowCheckout] = useState(false);
  const [deliveryCoords, setDeliveryCoords] = useState<Coordinates | null>(null);
  const [isOrdering, setIsOrdering] = useState(false);

  // Profile State
  const [isEditingProfile, setIsEditingProfile] = useState(false);
  const [isUploading, setIsUploading] = useState(false);
  const [profileData, setProfileData] = useState({ name: '', phone: '', avatar: '', wilaya: '', coordinates: null as any });
  const [editForm, setEditForm] = useState({ name: '', phone: '', wilaya: '', avatar: '' });

  const fileInputRef = useRef<HTMLInputElement>(null);
  const user = auth.currentUser;

  useEffect(() => {
    if (!user) return;
    onValue(ref(db, `customers/${user.uid}`), (snap) => {
      if (snap.exists()) {
        const data = snap.val();
        setProfileData(data);
        setEditForm({
          name: data.name || '',
          phone: data.phone || '',
          wilaya: data.wilaya || '',
          avatar: data.avatar || ''
        });
        if (data.coordinates && !deliveryCoords) setDeliveryCoords(data.coordinates);
      }
    });
    onValue(ref(db, 'stores'), (snap) => {
      const data = snap.val();
      if (data) setStores(Object.keys(data).map(k => ({ id: k, ...data[k] })));
    });
    onValue(ref(db, 'products'), (snap) => {
      const data = snap.val();
      if (data) setAllProducts(Object.keys(data).map(k => ({ id: k, ...data[k] })));
      setLoading(false);
    });
    onValue(ref(db, 'orders'), (snap) => {
      const data = snap.val();
      const list: Order[] = [];
      if (data) Object.keys(data).forEach(k => { if (data[k].customerId === user.uid) list.push({ id: k, ...data[k] }); });
      setMyOrders(list.sort((a, b) => b.timestamp - a.timestamp));
    });
  }, [user]);

  const handleUpdateProfile = async () => {
    if (!user) return;
    setIsUploading(true);
    await update(ref(db, `customers/${user.uid}`), editForm);
    setIsEditingProfile(false);
    setIsUploading(false);
  };

  const addToCart = (p: Product) => {
    if (cart.length > 0 && cart[0].product.storeId !== p.storeId) {
      if (window.confirm("لا يمكنك الطلب من متجرين مختلفين. هل تريد إفراغ سلتك الحالية؟")) {
        setCart([{ product: p, quantity: 1 }]);
      }
      return;
    }
    setCart(prev => {
      const ex = prev.find(i => i.product.id === p.id);
      if (ex) return prev.map(i => i.product.id === p.id ? {...i, quantity: i.quantity + 1} : i);
      return [...prev, { product: p, quantity: 1 }];
    });
  };

  const handleCheckout = async () => {
    if (!user) return alert("يجب تسجيل الدخول أولاً");
    if (cart.length === 0) return alert("السلة فارغة!");
    if (!deliveryCoords) return alert("يرجى تحديد موقع التوصيل على الخريطة أولاً بنقرة واحدة.");

    setIsOrdering(true);
    try {
      const total = cart.reduce((sum, item) => sum + (item.product.price * item.quantity), 0);
      const store = stores.find(s => s.id === cart[0].product.storeId);

      const orderData = {
        customerId: user.uid,
        customerName: profileData.name || user.displayName || "زبون كيمو",
        customerPhone: profileData.phone || "",
        storeId: cart[0].product.storeId,
        storeName: store?.name || "متجر كيمو",
        storeCoordinates: store?.coordinates || { lat: 34.7495, lng: 8.0617 },
        products: cart,
        totalPrice: total + 200,
        deliveryFee: 200,
        status: OrderStatus.PENDING,
        timestamp: Date.now(),
        wilaya: profileData.wilaya,
        coordinates: deliveryCoords,
        address: "تم التحديد عبر الخريطة"
      };

      const newOrderRef = push(ref(db, 'orders'));
      await set(newOrderRef, orderData);
      setCart([]);
      setShowCheckout(false);
      setActiveTab('ORDERS');
      alert("تم إرسال طلبك! ترقب اتصالاً من الموصل.");
    } catch (e: any) {
      alert("حدث خطأ أثناء الطلب: " + e.message);
    } finally {
      setIsOrdering(false);
    }
  };

  const localStores = stores.filter(s => s.wilaya === profileData.wilaya);
  const featuredProducts = allProducts.filter(p => localStores.some(s => s.id === p.storeId)).slice(0, 6);

  if (loading) return <div className="h-screen flex items-center justify-center bg-white"><Loader2 className="animate-spin text-orange-500 w-12 h-12" /></div>;

  return (
    <div className="bg-[#F8FAFC] min-h-screen pb-32 font-cairo text-right" dir="rtl">

      {/* Checkout Modal */}
      {showCheckout && (
        <div className="fixed inset-0 z-[2000] bg-white flex flex-col animate-fade-in">
           <header className="p-6 flex items-center justify-between border-b bg-white sticky top-0">
              <button onClick={() => setShowCheckout(false)} className="p-2 bg-slate-50 rounded-full"><X/></button>
              <h2 className="text-lg font-black">تأكيد الطلب</h2>
              <div className="w-10"></div>
           </header>
           <div className="flex-1 overflow-y-auto p-6 space-y-8">
              <section className="space-y-4">
                 <h3 className="font-black text-slate-800 flex items-center gap-2"><MapPin size={18} className="text-orange-500"/> حدد موقعك بدقة</h3>
                 <div className="h-64 rounded-[2.5rem] overflow-hidden border-4 border-slate-50 relative shadow-inner">
                    <MapVisualizer 
                      customerLocation={deliveryCoords || profileData.coordinates} 
                      height="h-64" 
                      isPicker={true} 
                      onLocationSelect={setDeliveryCoords} 
                    />
                 </div>
              </section>

              <section className="space-y-4">
                 <h3 className="font-black text-slate-800">الأصناف المطلوبة</h3>
                 <div className="space-y-3">
                    {cart.map((item, idx) => (
                      <div key={idx} className="flex justify-between items-center bg-slate-50 p-4 rounded-2xl">
                         <div className="flex items-center gap-3">
                            <span className="w-8 h-8 bg-white rounded-xl flex items-center justify-center font-black text-orange-500 text-xs shadow-sm">{item.quantity}x</span>
                            <p className="text-xs font-black text-slate-700">{item.product.name}</p>
                         </div>
                         <span className="text-xs font-black">{formatCurrency(item.product.price * item.quantity)}</span>
                      </div>
                    ))}
                 </div>
              </section>

              <div className="bg-orange-50 p-6 rounded-[2.5rem] border border-orange-100 space-y-3 shadow-sm">
                 <div className="flex justify-between text-xs font-bold text-slate-500"><span>المجموع</span> <span>{formatCurrency(cart.reduce((s, i) => s + (i.product.price * i.quantity), 0))}</span></div>
                 <div className="flex justify-between text-xs font-bold text-slate-500"><span>التوصيل</span> <span>{formatCurrency(200)}</span></div>
                 <div className="flex justify-between text-lg font-black text-orange-600 pt-3 border-t border-orange-200"><span>الإجمالي</span> <span>{formatCurrency(cart.reduce((s, i) => s + (i.product.price * i.quantity), 0) + 200)}</span></div>
              </div>
           </div>
           <footer className="p-6 border-t bg-white">
              <button 
                onClick={handleCheckout} 
                disabled={isOrdering}
                className="w-full brand-gradient text-white py-5 rounded-[2rem] font-black text-lg shadow-xl shadow-orange-100 flex items-center justify-center gap-3 active:scale-95 transition-all"
              >
                {isOrdering ? <Loader2 className="animate-spin" /> : <><CheckCircle size={22}/> تأكيد وطلب الآن</>}
              </button>
           </footer>
        </div>
      )}

      {/* Profile Tab */}
      {activeTab === 'PROFILE' ? (
        <div className="animate-fade-in-up p-6 space-y-8">
          <div className="flex justify-between items-center">
             <h2 className="text-3xl font-black text-slate-900">حسابي</h2>
             <button onClick={onLogout} className="p-3 bg-red-50 text-red-500 rounded-2xl"><LogOut size={20}/></button>
          </div>

          <div className="bg-white p-8 rounded-[3.5rem] shadow-xl border border-white relative overflow-hidden">
             <div className="absolute top-0 right-0 w-32 h-32 brand-gradient opacity-5 rounded-bl-[8rem]"></div>

             {!isEditingProfile ? (
               <div className="text-center relative z-10">
                  <div className="w-32 h-32 mx-auto mb-6 rounded-[3rem] border-4 border-white shadow-2xl overflow-hidden bg-slate-50 flex items-center justify-center relative group">
                     {profileData.avatar ? <img src={profileData.avatar} className="w-full h-full object-cover" /> : <User size={48} className="text-slate-200" />}
                     <div className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center">
                        <Camera className="text-white" />
                     </div>
                  </div>
                  <h3 className="text-2xl font-black text-slate-800 mb-1">{profileData.name}</h3>
                  <div className="flex items-center justify-center gap-2 mb-8">
                     <span className="bg-slate-100 text-slate-500 px-4 py-1.5 rounded-full text-[10px] font-black flex items-center gap-1"><MapPin size={12}/> {profileData.wilaya}</span>
                     <span className="bg-orange-50 text-orange-500 px-4 py-1.5 rounded-full text-[10px] font-black">زبون برونزي</span>
                  </div>

                  <div className="grid grid-cols-2 gap-4 mb-8">
                     <div className="bg-slate-50 p-6 rounded-[2.2rem] text-center">
                        <p className="text-[10px] font-black text-slate-400 uppercase mb-1">الطلبات</p>
                        <p className="text-xl font-black text-slate-800">{myOrders.length}</p>
                     </div>
                     <div className="bg-slate-50 p-6 rounded-[2.2rem] text-center">
                        <p className="text-[10px] font-black text-slate-400 uppercase mb-1">المحفظة</p>
                        <p className="text-xl font-black text-green-600">0 د.ج</p>
                     </div>
                  </div>

                  <button onClick={() => setIsEditingProfile(true)} className="w-full bg-slate-900 text-white py-5 rounded-[2rem] font-black shadow-xl flex items-center justify-center gap-3 active:scale-95 transition-all"><Edit3 size={18}/> تعديل بياناتي</button>
               </div>
             ) : (
               <div className="space-y-6">
                  <div className="flex justify-between items-center mb-4">
                     <h3 className="text-xl font-black">تعديل الملف</h3>
                     <button onClick={() => setIsEditingProfile(false)} className="p-2 bg-slate-50 rounded-full"><X size={20}/></button>
                  </div>

                  <div className="flex flex-col items-center mb-8">
                     <div onClick={() => fileInputRef.current?.click()} className="w-24 h-24 bg-slate-50 rounded-3xl border-2 border-dashed border-slate-200 flex items-center justify-center cursor-pointer overflow-hidden relative shadow-sm">
                        {editForm.avatar ? <img src={editForm.avatar} className="w-full h-full object-cover" /> : <Camera className="text-slate-300" />}
                        {isUploading && <div className="absolute inset-0 bg-white/60 flex items-center justify-center"><Loader2 className="animate-spin text-orange-500" /></div>}
                     </div>
                     <input type="file" ref={fileInputRef} className="hidden" onChange={async (e) => {
                        const f = e.target.files?.[0];
                        if (f) { setIsUploading(true); const url = await uploadImage(f); if (url) setEditForm({...editForm, avatar: url}); setIsUploading(false); }
                     }} />
                  </div>

                  <div className="space-y-4">
                     <div className="relative">
                        <input type="text" placeholder="الاسم الكامل" className="w-full p-4 pr-12 bg-slate-50 rounded-2xl font-bold outline-none border border-transparent focus:border-orange-500 transition-all" value={editForm.name} onChange={e => setEditForm({...editForm, name: e.target.value})} />
                        <User className="absolute right-4 top-4 text-slate-300" size={18} />
                     </div>
                     <div className="relative">
                        <input type="tel" placeholder="رقم الهاتف" className="w-full p-4 pr-12 bg-slate-50 rounded-2xl font-bold outline-none border border-transparent focus:border-orange-500 transition-all" value={editForm.phone} onChange={e => setEditForm({...editForm, phone: e.target.value})} />
                        <Phone className="absolute right-4 top-4 text-slate-300" size={18} />
                     </div>
                     <div className="relative">
                        <select className="w-full p-4 pr-12 bg-slate-50 rounded-2xl font-bold outline-none appearance-none border border-transparent focus:border-orange-500 transition-all" value={editForm.wilaya} onChange={e => setEditForm({...editForm, wilaya: e.target.value})}>
                           {WILAYAS_ALGERIA.map(w => <option key={w} value={w}>{w}</option>)}
                        </select>
                        <Globe className="absolute right-4 top-4 text-slate-300" size={18} />
                     </div>
                  </div>

                  <button onClick={handleUpdateProfile} disabled={isUploading} className="w-full brand-gradient text-white py-5 rounded-[2rem] font-black text-lg shadow-xl shadow-orange-100 flex items-center justify-center gap-3 active:scale-95 transition-all">
                     {isUploading ? <Loader2 className="animate-spin" /> : <><Save size={20}/> حفظ البيانات</>}
                  </button>
               </div>
             )}
          </div>
        </div>
      ) : (
        <>
          <header className="bg-white sticky top-0 z-[100] px-6 pt-8 pb-4 border-b border-slate-50">
            <div className="flex justify-between items-center mb-6">
               <div className="flex items-center gap-3">
                  <div className="w-12 h-12 rounded-2xl bg-orange-500 flex items-center justify-center text-white font-black text-xl shadow-lg shadow-orange-200 rotate-3 transition-transform active:rotate-0">K</div>
                  <div>
                     <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">مرحباً بك</p>
                     <h2 className="text-sm font-black text-slate-800">{profileData.name || userName}</h2>
                  </div>
               </div>
               <button onClick={() => setActiveTab('PROFILE')} className="w-12 h-12 rounded-2xl bg-slate-50 flex items-center justify-center border border-slate-100 overflow-hidden shadow-sm active:scale-90 transition-all">
                  {profileData.avatar ? <img src={profileData.avatar} className="w-full h-full object-cover" /> : <User size={20} className="text-slate-400" />}
               </button>
            </div>
            {activeTab === 'HOME' && (
              <div className="relative">
                 <input type="text" placeholder="ابحث عن أكلة، متجر أو صنف..." value={searchQuery} onChange={e => setSearchQuery(e.target.value)} className="w-full bg-slate-50 rounded-2xl py-4 pr-12 pl-4 text-xs font-bold outline-none border border-transparent focus:border-orange-500 transition-all" />
                 <Search className="absolute right-4 top-4 text-slate-400" size={20} />
              </div>
            )}
          </header>

          <main className="p-4 max-w-lg mx-auto space-y-10 mt-4">
             {/* Home content remains similar but better integrated */}
             {activeTab === 'HOME' && (
                <div className="space-y-10 animate-fade-in-up">
                   <div className="overflow-x-auto flex gap-4 pb-4 scrollbar-hide">
                      <div className="min-w-[300px] h-44 brand-gradient rounded-[3rem] p-8 text-white relative overflow-hidden shadow-xl shadow-orange-100 transition-transform active:scale-95">
                         <Zap className="absolute -left-6 -top-6 w-40 h-40 opacity-10 -rotate-12" />
                         <h3 className="text-2xl font-black mb-1">أول طلب؟</h3>
                         <p className="text-[12px] font-bold opacity-80 mb-6 leading-relaxed">استخدم كود <span className="bg-white/20 px-2 py-0.5 rounded-lg">KIMO20</span> للحصول على خصم فوري.</p>
                         <button className="bg-white text-orange-600 px-8 py-2.5 rounded-full text-[11px] font-black shadow-lg">اطلب الآن</button>
                      </div>
                   </div>

                   <div className="space-y-4">
                      <h3 className="text-xl font-black text-slate-900 px-2">متاجر ولاية {profileData.wilaya}</h3>
                      <div className="grid grid-cols-1 gap-4">
                         {localStores.length > 0 ? localStores.map(s => (
                           <div key={s.id} onClick={() => setSelectedStore(s)} className="bg-white p-5 rounded-[2.8rem] shadow-sm border border-slate-50 flex items-center gap-5 active:scale-95 transition-all">
                              <img src={s.image} className="w-20 h-20 rounded-[2rem] object-cover shadow-md" />
                              <div className="flex-1">
                                 <h4 className="text-md font-black text-slate-800 mb-1">{s.name}</h4>
                                 <div className="flex items-center gap-3">
                                    <div className="flex items-center gap-1 text-[11px] font-black text-yellow-500"><Star size={12} fill="currentColor"/> {s.rating}</div>
                                    <div className="flex items-center gap-1 text-[11px] font-black text-slate-400"><Clock size={12}/> 30 د</div>
                                 </div>
                              </div>
                              <div className="bg-slate-50 p-3 rounded-2xl text-slate-300"><ChevronRight size={20}/></div>
                           </div>
                         )) : (
                           <div className="text-center py-10 bg-white rounded-[2rem] border border-dashed border-slate-200">
                              <p className="text-sm font-bold text-slate-400">لا توجد متاجر مسجلة في ولايتك حالياً.</p>
                           </div>
                         )}
                      </div>
                   </div>
                </div>
             )}

             {/* Orders Tab content */}
             {activeTab === 'ORDERS' && (
               <div className="space-y-6 animate-fade-in-up px-2">
                  <h2 className="text-3xl font-black text-slate-900">طلباتي الحالية</h2>
                  {myOrders.length === 0 ? (
                    <div className="text-center py-20 bg-white rounded-[3.5rem] p-10 shadow-sm border border-slate-50">
                       <div className="w-24 h-24 bg-slate-50 rounded-full flex items-center justify-center mx-auto mb-6 text-slate-200"><History size={48}/></div>
                       <h3 className="text-lg font-black text-slate-800 mb-2">لا توجد طلبات</h3>
                       <p className="text-xs text-slate-400 font-bold">ابدأ بطلب وجبتك المفضلة وستظهر هنا.</p>
                    </div>
                  ) : (
                    <div className="space-y-4">
                       {myOrders.map(o => (
                         <div key={o.id} className="bg-white p-7 rounded-[3rem] shadow-sm border border-slate-50 space-y-6">
                            <div className="flex justify-between items-center">
                               <div className="flex items-center gap-4">
                                  <div className="w-14 h-14 bg-orange-50 text-orange-600 rounded-2xl flex items-center justify-center font-black text-xl shadow-inner">K</div>
                                  <div>
                                     <h4 className="text-sm font-black text-slate-800">{o.storeName}</h4>
                                     <p className="text-[10px] text-slate-400 font-bold">{new Date(o.timestamp).toLocaleDateString('ar-DZ')}</p>
                                  </div>
                               </div>
                               <span className={`px-5 py-2 rounded-full text-[10px] font-black shadow-sm ${o.status === OrderStatus.DELIVERED ? 'bg-green-50 text-green-600' : 'bg-orange-50 text-orange-600 animate-pulse'}`}>
                                  {o.status}
                               </span>
                            </div>
                            <div className="flex justify-between items-center pt-5 border-t border-slate-50">
                               <div className="text-md font-black text-slate-900">{formatCurrency(o.totalPrice)}</div>
                               <button className="text-[11px] font-black text-orange-500 bg-orange-50 px-6 py-2.5 rounded-2xl active:scale-95 transition-all">تتبع الطلب</button>
                            </div>
                         </div>
                       ))}
                    </div>
                  )}
               </div>
             )}
          </main>
        </>
      )}

      {/* Floating cart trigger */}
      {cart.length > 0 && !showCheckout && (
        <div className="fixed bottom-24 left-4 right-4 z-[900] animate-fade-in-up">
           <button onClick={() => setShowCheckout(true)} className="w-full brand-gradient text-white p-6 rounded-[2.5rem] shadow-2xl flex items-center justify-between px-10 transition-transform active:scale-95">
              <div className="flex items-center gap-4">
                 <div className="bg-white/20 p-2.5 rounded-xl"><ShoppingCart size={22}/></div>
                 <div className="text-right">
                    <p className="text-[10px] font-black opacity-80 uppercase tracking-tighter">السلة جاهزة</p>
                    <p className="text-sm font-black">إتمام عملية الطلب الآن</p>
                 </div>
              </div>
              <span className="text-xl font-black">{formatCurrency(cart.reduce((s, i) => s + (i.product.price * i.quantity), 0))}</span>
           </button>
        </div>
      )}

      <nav className="fixed bottom-0 left-0 right-0 bg-white/80 backdrop-blur-xl border-t h-20 flex justify-around items-center px-4 z-[1000] shadow-2xl">
        <NavBtn act={activeTab === 'HOME'} onClick={() => setActiveTab('HOME')} icon={<Home />} label="الرئيسية" />
        <NavBtn act={activeTab === 'CATEGORIES'} onClick={() => setActiveTab('CATEGORIES')} icon={<LayoutGrid />} label="الأقسام" />
        <NavBtn act={activeTab === 'ORDERS'} onClick={() => setActiveTab('ORDERS')} icon={<History />} label="طلباتي" />
        <NavBtn act={activeTab === 'PROFILE'} onClick={() => setActiveTab('PROFILE')} icon={<User />} label="حسابي" />
      </nav>
    </div>
  );
};

const NavBtn = ({ act, onClick, icon, label }: any) => (
  <button onClick={onClick} className={`flex flex-col items-center gap-1.5 transition-all ${act ? 'text-orange-500 scale-110' : 'text-slate-400'}`}>
    {React.cloneElement(icon, { size: 22, strokeWidth: act ? 3 : 2 })}
    <span className="text-[9px] font-black">{label}</span>
  </button>
);
